def _fmt_local(dt, tz_name=None):
    """Format a UTC datetime in the given IANA timezone (defaults to America/New_York)."""
    if dt is None:
        return ''
    try:
        from zoneinfo import ZoneInfo
        tz = ZoneInfo(tz_name or 'America/New_York')
        local_dt = dt.replace(tzinfo=ZoneInfo('UTC')).astimezone(tz)
        return local_dt.strftime('%-I:%M %p')
    except Exception:
        return dt.strftime('%-I:%M %p')


# ── Cloudflare R2 helpers ──────────────────────────────────────────────────────
_R2_ACCOUNT_ID  = os.getenv('R2_ACCOUNT_ID', '')
_R2_ACCESS_KEY  = os.getenv('R2_ACCESS_KEY_ID', '')
_R2_SECRET      = os.getenv('R2_SECRET_ACCESS_KEY', '')
_R2_BUCKET      = os.getenv('R2_BUCKET', 'fpbudget-docs')

_R2_VERSION_LOGGED = False
_R2_CLIENT_CACHE = None

def _r2_client():
    # Cache the client at module level. Building a boto3 client is expensive
    # (~100-500ms) and every build walks botocore's endpoint/SSL init — which
    # is exactly where the gevent ssl-monkey-patch recursion bug hits on
    # Python 3.12+. One build per worker, not per request.
    global _R2_CLIENT_CACHE
    if _R2_CLIENT_CACHE is not None:
        return _R2_CLIENT_CACHE
    import boto3, botocore
    from botocore.config import Config
    global _R2_VERSION_LOGGED
    if not _R2_VERSION_LOGGED:
        logging.warning(
            "[R2] boto3=%s botocore=%s checksum_env=%s",
            getattr(boto3, '__version__', '?'),
            getattr(botocore, '__version__', '?'),
            os.environ.get('AWS_REQUEST_CHECKSUM_CALCULATION'),
        )
        _R2_VERSION_LOGGED = True

    # Build Config kwargs incrementally so unknown kwargs on older botocore
    # don't blow away the entire config (the previous try/except wrapped
    # the WHOLE Config(), so any version mismatch silently fell back to a
    # config WITHOUT the checksum suppression and the recursion bug came
    # back). Try each new kwarg individually.
    base_kwargs = dict(
        signature_version='s3v4',
        s3={'addressing_style': 'path'},
        retries={'max_attempts': 3, 'mode': 'standard'},
    )
    for opt_kwarg in ('request_checksum_calculation', 'response_checksum_validation'):
        try:
            Config(**{**base_kwargs, opt_kwarg: 'when_required'})
            base_kwargs[opt_kwarg] = 'when_required'
        except TypeError:
            logging.warning("[R2] botocore Config does not accept %s — env var fallback active", opt_kwarg)

    cfg = Config(**base_kwargs)
    _R2_CLIENT_CACHE = boto3.client(
        's3',
        endpoint_url=f"https://{_R2_ACCOUNT_ID}.r2.cloudflarestorage.com",
        aws_access_key_id=_R2_ACCESS_KEY,
        aws_secret_access_key=_R2_SECRET,
        region_name='auto',
        config=cfg,
    )
    return _R2_CLIENT_CACHE

def _r2_upload(file_bytes, key, content_type='application/octet-stream'):
    """Upload bytes to R2. Returns True on success."""
    try:
        _r2_client().put_object(Bucket=_R2_BUCKET, Key=key, Body=file_bytes, ContentType=content_type)
        return True
    except RecursionError:
        # botocore got into a retry loop (usually checksum-related on R2).
        # Surface the cause clearly so we don't waste another debugging
        # cycle thinking the env var fix is in place when it isn't.
        logging.exception("[R2] RecursionError — checksum suppression NOT effective. "
                          "Verify boto3/botocore version and AWS_REQUEST_CHECKSUM_CALCULATION env.")
        return False
    except Exception:
        logging.exception("R2 upload failed")
        return False


def _r2_download(key):
    """Download bytes from R2 by key. Returns (bytes, None) on success or
    (None, error_message) on failure — never raises, so callers don't have
    to deal with boto3's recursion/retry quirks on missing objects."""
    try:
        resp = _r2_client().get_object(Bucket=_R2_BUCKET, Key=key)
        return (resp['Body'].read(), None)
    except Exception as e:
        # Common cases: NoSuchKey (the file was never actually stored — happens
        # for rows created before the arg-swap bug fix), credentials missing,
        # or a genuine network error. Collapse all into a friendly string.
        msg = str(e).lower()
        if 'nosuchkey' in msg or 'not found' in msg or '404' in msg:
            return (None, "File data missing from storage. Delete this row and re-upload.")
        if 'recursion' in msg or 'endpoint' in msg:
            return (None, "R2 storage is unreachable (check R2 env vars on Render).")
        return (None, f"R2 fetch failed: {str(e)[:200]}")


def _r2_presigned_url(key, expires=3600):
    """Return a presigned URL for a private R2 object (expires in `expires` seconds)."""
    try:
        return _r2_client().generate_presigned_url(
            'get_object', Params={'Bucket': _R2_BUCKET, 'Key': key}, ExpiresIn=expires)
    except Exception as e:
        logging.warning(f"R2 presigned URL failed: {e}")
        return None


# ── Dropbox helpers ────────────────────────────────────────────────────────────
_DBX_TEMPLATE_NAME  = os.getenv('DROPBOX_TEMPLATE_FOLDER', '!_PRODUCTION_PROJECT_TEMPLATE')
_DBX_NAMESPACE_ID   = os.getenv('DROPBOX_NAMESPACE_ID', '')   # shared folder namespace ID
# Legacy path-based fallback (used only when namespace ID is not set).
# Paths are relative to the authenticated Dropbox user's root — if the app
# is connected as Steven, the prefix `/Steven Pierce/` would DUPLICATE and
# land everything under `Steven Pierce/Steven Pierce/...`. Keep it root-
# relative.
_DBX_OPS_ROOT       = os.getenv('DROPBOX_OPERATIONS_PATH', '/_FP OPERATIONS FOLDER')
# Archive and Wrap destinations live as SIBLINGS of _FP OPERATIONS FOLDER
# (not children). Both exist at the top of the Dropbox user root.
_DBX_ARCHIVE_ROOT   = os.getenv('DROPBOX_ARCHIVE_PATH',   '/_ARCHIVED')
_DBX_WRAP_ROOT      = os.getenv('DROPBOX_WRAP_PATH',      '/_WRAPPED PROJECTS')

_DBX_CLIENT_CACHE = None

def _dbx_client():
    # Cache the client at module level (one per worker). Building a Dropbox
    # SDK client allocates an HTTP session + OAuth2 refresh handler +
    # namespace path-root wrapper. Per user 2026-04-29: hot paths
    # (/docs/upload/<uid>/raw, /preview-link, /verify) call this on
    # every request — without caching, a few rapid uploads / previews
    # can push a Render free-tier worker over its memory limit.
    global _DBX_CLIENT_CACHE
    if _DBX_CLIENT_CACHE is not None:
        return _DBX_CLIENT_CACHE
    import dropbox as _dbx_mod
    refresh_token = os.getenv('DROPBOX_REFRESH_TOKEN', '')
    app_key       = os.getenv('DROPBOX_APP_KEY', '')
    app_secret    = os.getenv('DROPBOX_APP_SECRET', '')
    if refresh_token and app_key and app_secret:
        dbx = _dbx_mod.Dropbox(
            oauth2_refresh_token=refresh_token,
            app_key=app_key,
            app_secret=app_secret,
        )
    else:
        dbx = _dbx_mod.Dropbox(os.getenv('DROPBOX_ACCESS_TOKEN', ''))
    # Route into the shared folder namespace so paths like /!_TEMPLATE work directly
    if _DBX_NAMESPACE_ID:
        from dropbox.common import PathRoot
        dbx = dbx.with_path_root(PathRoot.namespace_id(_DBX_NAMESPACE_ID))
    _DBX_CLIENT_CACHE = dbx
    return dbx

def _dbx_paths(dropbox_folder):
    """Return (src, dest) paths for provision, adjusted for namespace mode."""
    if _DBX_NAMESPACE_ID:
        # Namespace root IS the ops folder — paths are relative to it
        src  = f"/{_DBX_TEMPLATE_NAME}"
        dest = f"/{dropbox_folder}"
    else:
        src  = f"{_DBX_OPS_ROOT}/{_DBX_TEMPLATE_NAME}"
        dest = f"{_DBX_OPS_ROOT}/{dropbox_folder}"
    return src, dest

def _provision_dropbox_folder(dropbox_folder):
    """Copy the project template tree to a new project folder. Returns path or None."""
    has_refresh = os.getenv('DROPBOX_REFRESH_TOKEN') and os.getenv('DROPBOX_APP_KEY')
    if not has_refresh and not os.getenv('DROPBOX_ACCESS_TOKEN'):
        logging.warning("[DBX PROVISION] skipped — no credentials set")
        return None
    try:
        src, dest = _dbx_paths(dropbox_folder)
        logging.warning(f"[DBX PROVISION] copying '{src}' → '{dest}' "
                        f"(OPS_ROOT={_DBX_OPS_ROOT!r}, TEMPLATE={_DBX_TEMPLATE_NAME!r}, "
                        f"NAMESPACE={_DBX_NAMESPACE_ID!r})")
        _dbx_client().files_copy_v2(src, dest)
        logging.warning(f"[DBX PROVISION] success → {dest}")
        return dest
    except Exception as e:
        # Log with full type + message so Render logs clearly show what broke.
        import traceback as _tb
        logging.error(f"[DBX PROVISION] FAILED for slug={dropbox_folder!r}: "
                      f"{type(e).__name__}: {e}\n{_tb.format_exc()}")
        return None


@app.route("/admin/dropbox/status")
@login_required
def admin_dropbox_status():
    # Super admin check inline — super_admin_required decorator is defined
    # further down in this module, can't apply it at import time here.
    if not current_user.is_authenticated or getattr(current_user, 'role', None) != 'super_admin':
        return jsonify({"error": "super admin only"}), 403
    """Diagnostic: show current Dropbox config + test connection + check
    the template folder exists. Super-admin only. Paste the JSON back to
    the engineer when project folders aren't being created."""
    out = {
        "env": {
            "DROPBOX_REFRESH_TOKEN_set": bool(os.getenv('DROPBOX_REFRESH_TOKEN')),
            "DROPBOX_APP_KEY_set":       bool(os.getenv('DROPBOX_APP_KEY')),
            "DROPBOX_ACCESS_TOKEN_set":  bool(os.getenv('DROPBOX_ACCESS_TOKEN')),
            "DROPBOX_OPERATIONS_PATH":   os.getenv('DROPBOX_OPERATIONS_PATH'),
            "DROPBOX_TEMPLATE_FOLDER":   os.getenv('DROPBOX_TEMPLATE_FOLDER'),
            "DROPBOX_NAMESPACE_ID":      os.getenv('DROPBOX_NAMESPACE_ID'),
            "DROPBOX_ARCHIVE_PATH":      os.getenv('DROPBOX_ARCHIVE_PATH'),
            "DROPBOX_WRAP_PATH":         os.getenv('DROPBOX_WRAP_PATH'),
        },
        "resolved": {
            "_DBX_OPS_ROOT":      _DBX_OPS_ROOT,
            "_DBX_TEMPLATE_NAME": _DBX_TEMPLATE_NAME,
            "_DBX_NAMESPACE_ID":  _DBX_NAMESPACE_ID,
            "_DBX_ARCHIVE_ROOT":  _DBX_ARCHIVE_ROOT,
            "template_source_path": (f"/{_DBX_TEMPLATE_NAME}" if _DBX_NAMESPACE_ID
                                     else f"{_DBX_OPS_ROOT}/{_DBX_TEMPLATE_NAME}"),
        },
        "connection": None,
        "template_folder_exists": None,
        "template_folder_error": None,
    }
    # Try authenticating + listing the template folder.
    has_refresh = os.getenv('DROPBOX_REFRESH_TOKEN') and os.getenv('DROPBOX_APP_KEY')
    if not has_refresh and not os.getenv('DROPBOX_ACCESS_TOKEN'):
        out["connection"] = "NO CREDENTIALS"
        return jsonify(out)
    try:
        dbx = _dbx_client()
        # Sanity: who are we authed as
        try:
            acct = dbx.users_get_current_account()
            out["connection"] = {
                "status": "connected",
                "account_email":  getattr(acct, 'email', None),
                "account_name":   getattr(getattr(acct, 'name', None), 'display_name', None),
            }
        except Exception as _ae:
            out["connection"] = f"auth failed: {type(_ae).__name__}: {_ae}"
            return jsonify(out)
        # Try to stat the template folder.
        template_path = out["resolved"]["template_source_path"]
        try:
            md = dbx.files_get_metadata(template_path)
            out["template_folder_exists"] = True
            out["template_folder_path_on_dropbox"] = getattr(md, 'path_display', None)
        except Exception as _te:
            out["template_folder_exists"] = False
            out["template_folder_error"] = f"{type(_te).__name__}: {_te}"
    except Exception as e:
        out["connection"] = f"unexpected: {type(e).__name__}: {e}"
    return jsonify(out)


@app.route("/admin/veryfi/status")
@login_required
def admin_veryfi_status():
    """Diagnostic: check Veryfi env vars + try a lightweight API call.
    Mirrors /admin/dropbox/status — paste the JSON back when uploads fail
    with 401/other Veryfi errors."""
    if not current_user.is_authenticated or getattr(current_user, 'role', None) != 'super_admin':
        return jsonify({"error": "super admin only"}), 403
    out = {
        "env": {
            "VERYFI_CLIENT_ID_set":     bool(os.getenv('VERYFI_CLIENT_ID')),
            "VERYFI_CLIENT_SECRET_set": bool(os.getenv('VERYFI_CLIENT_SECRET')),
            "VERYFI_USERNAME_set":      bool(os.getenv('VERYFI_USERNAME')),
            "VERYFI_API_KEY_set":       bool(os.getenv('VERYFI_API_KEY')),
        },
        "client_init": None,
        "test_call": None,
    }
    missing = [k for k, v in out["env"].items() if not v]
    if missing:
        out["client_init"] = f"MISSING ENV VARS: {', '.join(missing)}"
        return jsonify(out)
    try:
        import veryfi
        client = veryfi.Client(
            client_id=os.getenv("VERYFI_CLIENT_ID"),
            client_secret=os.getenv("VERYFI_CLIENT_SECRET"),
            username=os.getenv("VERYFI_USERNAME"),
            api_key=os.getenv("VERYFI_API_KEY"),
        )
        out["client_init"] = "ok"
        # Hit a lightweight endpoint that doesn't cost a document credit.
        # get_categories is a read-only listing call.
        try:
            cats = client.get_categories()
            # Some SDK versions return a list, others a dict. Normalize.
            if isinstance(cats, list):
                out["test_call"] = {
                    "status": "ok",
                    "category_count": len(cats),
                    "sample": cats[:3],
                }
            elif isinstance(cats, dict):
                out["test_call"] = {
                    "status": "ok",
                    "keys": list(cats.keys())[:10],
                }
            else:
                out["test_call"] = {"status": "ok", "type": str(type(cats))}
        except Exception as _te:
            out["test_call"] = f"{type(_te).__name__}: {_te}"
    except Exception as e:
        out["client_init"] = f"{type(e).__name__}: {e}"
    return jsonify(out)


@app.route("/admin/docs/project/<int:pid>/wipe", methods=["POST"])
@login_required
def admin_docs_wipe_project(pid):
    """Super admin testing tool: delete every DocUpload row for a project
    and move each filed Dropbox file to /_TRASH/{date}_{slug}/. Lets us
    do clean-start iteration while the Analyzer pipeline is still
    being refined. Dropbox files are MOVED (not deleted) so there's a
    recovery window if we trash something we shouldn't have.
    """
    if not current_user.is_authenticated or getattr(current_user, 'role', None) != 'super_admin':
        return jsonify({"error": "super admin only"}), 403

    project = ProjectSheet.query.get_or_404(pid)
    uploads = DocUpload.query.filter_by(project_id=pid).all()

    deleted_count = 0
    moved_count   = 0
    errors        = []
    trash_root    = None

    # Only bother with Dropbox if we have credentials.
    dbx = None
    has_refresh = os.getenv('DROPBOX_REFRESH_TOKEN') and os.getenv('DROPBOX_APP_KEY')
    if has_refresh or os.getenv('DROPBOX_ACCESS_TOKEN'):
        try:
            dbx = _dbx_client()
        except Exception as _de:
            logging.warning(f"[DOCS WIPE] dropbox client init failed: {_de}")
            dbx = None

    if dbx and uploads:
        # Build a dated trash folder specific to this wipe so we can find
        # the files again if a mistake was made.
        from datetime import datetime as _dt
        _stamp = _dt.utcnow().strftime("%Y-%m-%d_%H%M%S")
        _slug  = project.dropbox_folder or f"project-{pid}"
        trash_root = f"/_TRASH/{_stamp}_{_slug}"
        # Ensure trash folder exists (Dropbox auto-creates parent folders
        # on move, so this is best-effort).
        try:
            dbx.files_create_folder_v2(trash_root, autorename=False)
        except Exception:
            pass  # already exists or Dropbox handles it via move autocreate

    # When the app is in namespace mode, paths stored on DocUpload rows
    # may have been written by BOTH generations of fp_analyzer:
    #   (a) pre-namespace-fix: stored as '/Steven Pierce/_FP OPERATIONS FOLDER/...'
    #       (absolute user-root path). Passing this through the
    #       namespace-scoped client double-prepends → not_found.
    #   (b) post-namespace-fix: stored as '/{project}/...' (relative to
    #       the namespace root). Works as-is.
    # Strip the OPS prefix from (a)-style paths before calling move so
    # both generations end up at the same working path for the wipe.
    _ops_prefix_str = (_DBX_OPS_ROOT or "").rstrip("/") if _DBX_NAMESPACE_ID else ""

    def _normalize_for_namespace(p):
        """If p starts with the legacy ops prefix under namespace mode,
        strip it so the namespace client can locate the file."""
        if not p:
            return p
        if _ops_prefix_str and p.startswith(_ops_prefix_str + "/"):
            return p[len(_ops_prefix_str):]  # leave leading '/'
        return p

    def _move_to_trash(original_src, label_id):
        """Move one Dropbox file to the dated trash folder. Returns True
        if moved (or if there was no Dropbox client / no trash root).
        Records errors against the running list."""
        if not original_src or not dbx or not trash_root:
            return False
        src = _normalize_for_namespace(original_src)
        _safe_path_frag = original_src.lstrip('/').replace('/', '_')
        dest = f"{trash_root}/{_safe_path_frag}"
        try:
            dbx.files_move_v2(src, dest, autorename=True)
            return True
        except Exception as _me1:
            err1 = str(_me1)
            if src != original_src:
                try:
                    dbx.files_move_v2(original_src, dest, autorename=True)
                    return True
                except Exception as _me2:
                    errors.append(
                        f"{label_id} ({original_src}): "
                        f"both paths failed — normalized: {err1}; "
                        f"original: {_me2}"
                    )
            else:
                errors.append(f"{label_id} ({original_src}): {err1}")
        return False

    # Step 0: delete every Transaction row for this project FIRST.
    # The 2026-04-30 doc-upload→Transaction auto-create wire means
    # every DocUpload now has a Transaction with doc_upload_id FK
    # pointing at it. Deleting the upload without first dropping the
    # txn raises ForeignKeyViolation. We clear all project txns at
    # once (faster than per-row) — for the wipe-test path that's the
    # right semantics anyway: Doc rows go, txn rows go, fresh slate.
    try:
        _txn_count = (db.session.query(Transaction)
                      .filter_by(project_id=pid)
                      .delete(synchronize_session=False))
        if _txn_count:
            logging.info(f"[DOCS WIPE] deleted {_txn_count} Transaction rows for project {pid}")
    except Exception as _txe:
        errors.append(f"transaction wipe failed: {_txe}")

    for up in uploads:
        # Step 1: move the filed (processed) Dropbox copy to trash.
        if _move_to_trash(up.filed_dropbox_path, f"upload {up.id} filed"):
            moved_count += 1
        # Step 1b: also move the source-archive copy to trash, but only
        # if it's a different path. (For status='review' rows, filed_=
        # archive_path so we don't double-move.)
        if (up.source_archive_path
                and up.source_archive_path != up.filed_dropbox_path):
            if _move_to_trash(up.source_archive_path, f"upload {up.id} archive"):
                moved_count += 1
        # Step 2: delete the DB row regardless of Dropbox outcome.
        try:
            db.session.delete(up)
            deleted_count += 1
        except Exception as _re:
            errors.append(f"upload {up.id}: db delete failed: {_re}")

    # Step 2.5: COMMIT THE DB DELETES NOW. Critical ordering — without
    # this, any subsequent exception in the folder-cleanup phase could
    # roll back the deletes, leaving orphan DocUpload rows even after
    # Dropbox has been wiped (the "I have rows in software pointing at
    # files Dropbox no longer has" symptom).
    try:
        db.session.commit()
    except Exception as _ce:
        db.session.rollback()
        errors.append(f"commit failed: {_ce}")
        return jsonify({
            "error": f"Commit failed, wipe partial: {_ce}",
            "deleted_count": 0,
            "moved_count": moved_count,
            "errors": errors[:20],
        }), 500

    # Step 3: nuke the project's PROCESSED DOCUMENTS + source-archive
    # subtrees so an empty-folder skeleton doesn't sit around between
    # test runs. Each test should start with the same clean state so
    # processing-path bugs are visible. Per user 2026-04-30: "I want
    # to see it process it every time so we can identify potential
    # errors." Errors are logged but never fatal — the wipe's primary
    # job (DB rows + filed files) is already done by here.
    if dbx and project.dropbox_folder:
        proj_root = f"/{project.dropbox_folder.strip('/')}"
        # Folders that the Analyzer writes into. We delete the ones that
        # exist; missing ones are a no-op. files_delete_v2 on a folder
        # cascades and deletes everything inside it.
        from fp_analyzer import DOCUMENT_TYPES as _DOC_TYPES_FOR_WIPE
        wipe_folders = set()
        for _folder in _DOC_TYPES_FOR_WIPE.values():
            wipe_folders.add(f"{proj_root}/{_folder}")
        # Source archive (project-scoped, added 2026-04-30)
        wipe_folders.add(f"{proj_root}/01_ADMIN/PROCESSED DOCUMENTS/_SOURCE_ARCHIVE")
        # Legacy "Duplicate" sub-folder
        wipe_folders.add(f"{proj_root}/01_ADMIN/PROCESSED DOCUMENTS/Duplicate")
        for _wf in sorted(wipe_folders):
            try:
                dbx.files_delete_v2(_wf)
                logging.info(f"[DOCS WIPE] deleted folder {_wf}")
            except Exception as _fe:
                # not_found is fine — folder didn't exist for this project.
                if "not_found" not in str(_fe):
                    logging.info(f"[DOCS WIPE] could not delete {_wf}: {_fe}")

    return jsonify({
        "ok":            True,
        "deleted_count": deleted_count,
        "moved_count":   moved_count,
        "trash_folder":  trash_root,
        "error_count":   len(errors),
        "errors":        errors[:20],
    })


_ANALYZER_TYPE_TO_CAT = {
    'RECEIPT': 'receipt', 'INVOICE': 'invoice', 'ESTIMATE': 'estimate',
    'QUOTE': 'quote', 'EMPDOC': 'employee_vendor_doc', 'CONTRACT': 'contract',
    'PO': 'purchase_order', 'TAXFORM': 'tax_form', 'TAX': 'tax_form',
    'RELEASE': 'release', 'LEGAL': 'legal', 'INSURANCE': 'insurance',
}


def _parse_analyzer_filename(name):
    """Pull (doc_date, category, vendor, amount) out of an Analyzer-filed
    filename like '2026-04-27_RECEIPT_Office_Supplies_Software_Video_Village_140.45.pdf'.
    Best-effort — date + amount are the reliable, match-critical bits. Returns
    a dict with any fields it could recover. (User 2026-06-02.)"""
    import re as _re
    out = {'doc_date': None, 'category': None, 'vendor': None, 'amount': None}
    base = (name or '').rsplit('.', 1)[0]
    base = _re.sub(r'\s*\(\d+\)\s*$', '', base).strip()      # strip Dropbox " (1)"
    parts = [p for p in base.split('_') if p != '']
    if parts and _re.match(r'^\d{4}-\d{2}-\d{2}$', parts[0]):
        out['doc_date'] = parts[0]; parts = parts[1:]
    elif parts and parts[0].lower() == 'unknown':
        parts = parts[1:]
    if parts:
        cat = _ANALYZER_TYPE_TO_CAT.get(parts[0].upper())
        if cat or parts[0].isupper():
            out['category'] = cat
            parts = parts[1:]
    if parts and _re.match(r'^\d{1,3}(,\d{3})*(\.\d{1,2})?$|^\d+(\.\d{1,2})?$', parts[-1]):
        try:
            out['amount'] = float(parts[-1].replace(',', ''))
        except ValueError:
            pass
        parts = parts[:-1]
    if parts and _re.match(r'^[0-9a-f]{16,}$', parts[-1].lower()):   # drop content-hash token
        parts = parts[:-1]
    vend = ' '.join(p for p in parts if p and p.lower() != 'unknown').strip()
    out['vendor'] = vend or None
    return out


# Canonical filename→amounts parser (CONSOLIDATED 2026-06-04 — was duplicated
# 3x with a regex that read dot-dates as money: "Receipt 2026.05.14.pdf"
# parsed $2,026.05 and OVERRODE the OCR total on the ledger. Code review CR-4.)
_AMOUNT_TOKEN_RE = re.compile(
    # not preceded by a digit or dot (rejects the "05.14" inside 2026.05.14),
    # then 1,234.56 or 1234.56, not followed by more dot-digits (rejects the
    # "2026.05" prefix of a dot-date).
    r'(?<![\d.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?!\.?\d)')


def _amounts_in_name(nm):
    """Dollar amounts curated into a filename, as integer cents. Hardened:
    skips dot-date fragments and year.month-looking tokens; ignores bare ints
    (too noisy) and sub-$1 tokens."""
    out = set()
    for m in _AMOUNT_TOKEN_RE.findall(nm or ''):
        try:
            v = float(m.replace(',', ''))
        except ValueError:
            continue
        if v < 1:
            continue
        # "2026.05" (year.month) heuristic: 4-digit 19xx/20xx integer part with
        # a <=12 two-digit decimal is a date fragment, not money.
        ip, dp = m.replace(',', '').split('.')
        if len(ip) == 4 and ip[:2] in ('19', '20') and int(dp) <= 12:
            continue
        out.add(int(round(v * 100)))
    return out


@app.route("/admin/docs/project/<int:pid>/dup-coding-audit", methods=["GET"])
@login_required
def admin_docs_dup_coding_audit(pid):
    """READ-ONLY: find byte-identical receipt sets (same file_hash) where more
    than one copy carries a CODED transaction — the same spend counted twice in
    Actuals. Lists each set + which copies are coded (and on what source).
    Changes nothing. (User 2026-06-17.)"""
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    ProjectSheet.query.get_or_404(pid)
    from collections import defaultdict as _dd
    ups = (DocUpload.query.filter_by(project_id=pid)
           .filter(DocUpload.file_hash.isnot(None), DocUpload.file_hash != '').all())
    groups = _dd(list)
    for u in ups:
        groups[u.file_hash].append(u)
    coded_rows = (db.session.query(Transaction.doc_upload_id, Transaction.amount,
                                   Transaction.account_code_name, Transaction.account_code,
                                   Transaction.source)
                  .filter(Transaction.project_id == pid,
                          Transaction.doc_upload_id.isnot(None),
                          db.or_(Transaction.budget_line_id.isnot(None),
                                 Transaction.account_code.isnot(None))).all())
    coded_by_doc = _dd(list)
    for r in coded_rows:
        coded_by_doc[r[0]].append({"amount": float(r[1]) if r[1] is not None else None,
                                   "code": r[2] or (str(r[3]) if r[3] else None),
                                   "source": r[4]})
    out = []
    for h, members in groups.items():
        if len(members) < 2:
            continue
        coded_members = [m for m in members if m.id in coded_by_doc]
        if len(coded_members) < 2:
            continue   # only flag genuine double-counts (>=2 coded copies)
        amt = next((m.amount for m in members if m.amount), None)
        out.append({
            "file_hash": h[:12],
            "copies": len(members),
            "coded_copies": len(coded_members),
            "vendor": (members[0].vendor or ''),
            "amount": float(amt) if amt is not None else None,
            "overcount": (float(amt) * (len(coded_members) - 1)) if amt is not None else None,
            "docs": [{"id": m.id, "filed": m.filed_filename or m.original_filename,
                      "is_duplicate": bool(m.is_duplicate), "status": m.status,
                      "coded": (m.id in coded_by_doc),
                      "codings": coded_by_doc.get(m.id, [])} for m in members],
        })
    out.sort(key=lambda g: (g["overcount"] or 0), reverse=True)
    total_overcount = round(sum((g["overcount"] or 0) for g in out), 2)
    return jsonify({"ok": True, "project_id": pid, "double_counted_sets": len(out),
                    "total_overcount": total_overcount, "sets": out})


@app.route("/admin/docs/project/<int:pid>/scan-audit", methods=["GET", "POST"])
@login_required
def admin_docs_scan_audit(pid):
    """READ-ONLY: compare Dropbox files against DocUpload rows to find receipts
    that never reached the DB (orphans), plus DocUpload health (status/category
    breakdown, how many lack an amount, are duplicates, or are already linked).
    ?q=<text> searches existing DocUploads (filename/vendor/amount). Helps
    answer 'why isn't this receipt showing up?'. (User 2026-06-02.)"""
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    project = ProjectSheet.query.get_or_404(pid)
    q = (request.args.get('q') or (request.get_json(silent=True) or {}).get('q') or '').strip().lower()
    from collections import Counter as _Counter

    ups = DocUpload.query.filter_by(project_id=pid).all()
    linked_ids = {r[0] for r in db.session.query(Transaction.doc_upload_id)
                  .filter(Transaction.project_id == pid,
                          Transaction.doc_upload_id.isnot(None)).all() if r[0]}
    by_status = _Counter((u.status or '?') for u in ups)
    by_cat = _Counter((u.category or '?') for u in ups)
    matches = []
    if q:
        for u in ups:
            hay = ' '.join([str(u.original_filename or ''), str(u.filed_filename or ''),
                            str(u.vendor or ''), str(u.amount or '')]).lower()
            if q in hay:
                matches.append({"id": u.id, "vendor": u.vendor,
                                "amount": float(u.amount) if u.amount is not None else None,
                                "date": u.doc_date.isoformat() if u.doc_date else None,
                                "status": u.status, "category": u.category,
                                "is_duplicate": bool(u.is_duplicate),
                                "linked": (u.id in linked_ids),
                                "filename": u.filed_filename or u.original_filename,
                                "note": (u.note or '')[:70]})

    orphans, scanned, dbx_err = [], 0, None
    try:
        dbx = _dbx_client()
        proj_root = (f"/{project.dropbox_folder}" if _DBX_NAMESPACE_ID
                     else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}")
        existing_full, existing_names = set(), set()
        for u in ups:
            if u.filed_dropbox_path:
                existing_full.add(u.filed_dropbox_path.lower())
                existing_names.add(os.path.basename(u.filed_dropbox_path).lower())
            for nm in (u.filed_filename, u.original_filename):
                if nm:
                    existing_names.add(nm.lower())
        # Walk the ENTIRE project root recursively — earlier we only walked an
        # enumerated subfolder set, which MISSED receipts filed under person
        # folders (PROCESSED DOCUMENTS/<name>/) and any other location, so they
        # were never imported or even flagged as orphans. (User 2026-06-02.)
        res = dbx.files_list_folder(proj_root + "/01_ADMIN/PROCESSED DOCUMENTS", recursive=True)
        while True:
            for entry in res.entries:
                if not hasattr(entry, 'size'):
                    continue
                pl = (entry.path_display or '').lower()
                if '/_trash' in pl or '/_source_archive' in pl:
                    continue   # trash + the pre-processing archive copy aren't real orphans
                scanned += 1
                if pl in existing_full or (entry.name or '').lower() in existing_names:
                    continue
                if '/_duplicates' in pl:
                    continue
                if len(orphans) < 100:
                    orphans.append({"filename": entry.name, "path": entry.path_display})
            if not res.has_more:
                break
            try:
                res = dbx.files_list_folder_continue(res.cursor)
            except Exception:
                break
    except Exception as _e:
        dbx_err = str(_e)

    return jsonify({
        "project": project.name, "dropbox_folder": project.dropbox_folder,
        "docupload_total": len(ups),
        "by_status": dict(by_status), "by_category": dict(by_cat),
        "null_amount": sum(1 for u in ups if u.amount is None),
        "duplicates": sum(1 for u in ups if u.is_duplicate or u.status == 'duplicate'),
        "linked_to_txn": len(linked_ids & {u.id for u in ups}),
        "dropbox_files_scanned": scanned,
        "orphan_count": len(orphans), "orphans_sample": orphans,
        "search_q": q, "search_matches": matches, "dbx_error": dbx_err,
    })


@app.route("/admin/docs/project/<int:pid>/import-missing", methods=["POST"])
@login_required
def admin_docs_import_missing(pid):
    """Import every Dropbox file in the project that has no DocUpload row, with
    date/amount/category/vendor parsed from the Analyzer filename so it's
    immediately matchable. Walks the WHOLE project root (skips _TRASH /
    _DUPLICATES / _SOURCE_ARCHIVE). Defensive: truncates to column limits,
    guards amount overflow, commits in batches, returns sanitized errors.
    Dry-run by default; ?apply=1 to write. (User 2026-06-02.)"""
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    project = ProjectSheet.query.get_or_404(pid)
    if not project.dropbox_folder:
        return jsonify({"error": "Project has no Dropbox folder configured"}), 400
    apply = (request.args.get('apply') == '1') or bool((request.get_json(silent=True) or {}).get('apply'))
    import mimetypes as _mt
    from datetime import datetime as _dt
    try:
        dbx = _dbx_client()
    except Exception as e:
        return jsonify({"error": "Dropbox init failed", "detail": type(e).__name__}), 500
    proj_root = (f"/{project.dropbox_folder}" if _DBX_NAMESPACE_ID
                 else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}")
    existing_full, existing_names = set(), set()
    for u in DocUpload.query.with_entities(
                DocUpload.filed_dropbox_path, DocUpload.original_filename,
                DocUpload.filed_filename).filter_by(project_id=pid).all():
        if u.filed_dropbox_path:
            existing_full.add(u.filed_dropbox_path.lower())
            existing_names.add(os.path.basename(u.filed_dropbox_path).lower())
        for nm in (u.filed_filename, u.original_filename):
            if nm:
                existing_names.add(nm.lower())

    def _clip(s, n):
        return s[:n] if (isinstance(s, str) and len(s) > n) else s

    created, scanned, errors, sample, batch = 0, 0, [], [], 0
    try:
        res = dbx.files_list_folder(proj_root + "/01_ADMIN/PROCESSED DOCUMENTS", recursive=True)
    except Exception as e:
        return jsonify({"error": "list failed", "detail": type(e).__name__}), 500
    while True:
        for entry in res.entries:
            if not hasattr(entry, 'size'):
                continue
            pl = (entry.path_display or '').lower()
            if '/_trash' in pl or '/_source_archive' in pl or '/_duplicates' in pl:
                continue
            scanned += 1
            if pl in existing_full:
                continue
            fn = entry.name or ''
            if fn.lower() in existing_names:
                continue
            existing_names.add(fn.lower()); existing_full.add(pl)   # dedupe within this walk
            p = _parse_analyzer_filename(fn)
            amt = p.get('amount')
            if amt is not None and (amt >= 10_000_000 or amt < 0):
                amt = None                                          # Numeric(10,2) guard
            dd = None
            if p.get('doc_date'):
                try:
                    dd = _dt.strptime(p['doc_date'], '%Y-%m-%d').date()
                except ValueError:
                    dd = None
            if apply:
                try:
                    db.session.add(DocUpload(
                        project_id=pid, uploader_id=current_user.id,
                        uploaded_at=getattr(entry, 'server_modified', None) or _dt.utcnow(),
                        original_filename=_clip(fn, 300), filed_filename=_clip(fn, 300),
                        filed_dropbox_path=_clip(entry.path_display, 500),
                        filed_at=getattr(entry, 'server_modified', None) or _dt.utcnow(),
                        file_size=getattr(entry, 'size', None),
                        content_type=_clip(_mt.guess_type(fn)[0] or 'application/octet-stream', 100),
                        status='filed', category=_clip(p.get('category'), 100),
                        vendor=_clip(p.get('vendor'), 200), amount=amt, doc_date=dd,
                        note='Imported from Dropbox scan'))
                    batch += 1
                    if batch >= 150:
                        db.session.commit(); batch = 0
                except Exception as _ce:
                    db.session.rollback(); batch = 0
                    errors.append(_clip(type(_ce).__name__ + ' @ ' + fn, 140))
            created += 1
            if len(sample) < 25:
                sample.append({"category": p.get('category'), "amount": amt, "date": p.get('doc_date')})
        if not res.has_more:
            break
        try:
            res = dbx.files_list_folder_continue(res.cursor)
        except Exception as _ce:
            errors.append('continue: ' + type(_ce).__name__); break
    if apply:
        try:
            db.session.commit()
        except Exception as _ce:
            db.session.rollback(); errors.append('final commit: ' + type(_ce).__name__)

    txns_created = 0
    if apply and created:
        for u in (DocUpload.query.filter_by(project_id=pid)
                  .filter(DocUpload.note == 'Imported from Dropbox scan').all()):
            # Only receipts/invoices become Actuals transactions. Other imported
            # doc types stay in Docs but never enter the Actuals tab. (User 2026-06-02.)
            if (u.category or '') not in ('receipt', 'invoice'):
                continue
            if Transaction.query.filter_by(doc_upload_id=u.id).first():
                continue
            try:
                db.session.add(Transaction(
                    project_id=pid, source='doc_upload', doc_upload_id=u.id,
                    vendor=u.vendor, amount=u.amount,
                    txn_date=u.doc_date.isoformat() if u.doc_date else None,
                    is_expense=True, match_status='unmatched',
                    created_via_user_id=current_user.id if current_user.is_authenticated else None))
                txns_created += 1
            except Exception:
                db.session.rollback()
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()

    # Clean the Actuals tab to receipts/invoices only: drop doc-only txns whose
    # receipt is NOT a receipt/invoice AND that aren't coded or confirmed (so we
    # never touch real work). The DocUpload stays in Docs. (User 2026-06-02.)
    removed_non_proof = 0
    if apply:
        _proof_ids = {r[0] for r in db.session.query(DocUpload.id)
                      .filter(DocUpload.project_id == pid,
                              DocUpload.category.in_(('receipt', 'invoice'))).all()}
        cand = (Transaction.query
                .filter(Transaction.project_id == pid,
                        Transaction.source == 'doc_upload',
                        Transaction.doc_upload_id.isnot(None),
                        Transaction.budget_line_id.is_(None),
                        Transaction.account_code.is_(None),
                        Transaction.match_status != 'confirmed').all())
        rm_ids = [t.id for t in cand if t.doc_upload_id not in _proof_ids]
        if rm_ids:
            try:
                removed_non_proof = (Transaction.query
                                     .filter(Transaction.id.in_(rm_ids))
                                     .delete(synchronize_session=False))
                db.session.commit()
            except Exception:
                db.session.rollback(); removed_non_proof = 0

    return jsonify({"dry": (not apply), "applied": apply, "scanned": scanned,
                    "created": created, "txns_created": txns_created,
                    "removed_non_proof_txns": removed_non_proof,
                    "errors": errors[:25], "sample": sample})


def _resolve_dbx_path(raw, project=None):
    """Turn a user-supplied path (local CloudStorage / /Volumes mount, or an
    already-Dropbox-relative path) into a path the namespace-scoped client can
    use. The app's Dropbox client is rooted at the shared-folder namespace whose
    root IS '_FP OPERATIONS FOLDER', so we strip everything up to & including
    that segment. (User 2026-06-03 — Cliburn source-folder audit.)"""
    import re as _re
    if not raw:
        return None
    p = str(raw).strip().strip('"').strip("'").replace('\\', '/')
    # Cut at the ops-folder marker (case-insensitive), keep what's after it.
    m = _re.search(r'_FP OPERATIONS FOLDER/?', p, _re.IGNORECASE)
    if m:
        rel = '/' + p[m.end():].strip('/')
    elif p.startswith('/'):
        rel = p                      # already looks Dropbox-relative
    else:
        rel = '/' + p.strip('/')
    rel = _re.sub(r'/+', '/', rel).rstrip('/')
    if _DBX_NAMESPACE_ID:
        return rel                   # namespace root == ops folder
    return f"{_DBX_OPS_ROOT.rstrip('/')}{rel}"


def _path_in_project(src_path, project):
    """True iff a resolved Dropbox path is within the project's OWN folder — so a
    project editor can't point the scan/import tools at another project's
    receipts. (Code review 2026-06-04.)"""
    if not src_path or not project or not getattr(project, 'dropbox_folder', None):
        return False
    proj_root = (f"/{project.dropbox_folder}" if _DBX_NAMESPACE_ID
                 else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}")
    s = src_path.rstrip('/').lower()
    r = proj_root.rstrip('/').lower()
    return s == r or s.startswith(r + '/')


def _walk_dbx_files(dbx, root, status=None):
    """Yield FileMetadata entries under `root` recursively, skipping trash.
    If `status` (a dict) is passed and any Dropbox list/continue call fails, sets
    status['truncated']=True — callers that build a dedup/exclusion set from this
    walk MUST refuse to import on a truncated walk, or a partial set causes mass
    re-import of already-filed receipts. (Code review 2026-06-04.)"""
    try:
        res = dbx.files_list_folder(root, recursive=True)
    except Exception as e:
        if status is not None:
            status['truncated'] = True
            status['error'] = type(e).__name__
        return
    while True:
        for entry in res.entries:
            if not hasattr(entry, 'content_hash'):   # FolderMetadata / deleted
                continue
            if '/_trash' in (entry.path_display or '').lower():
                continue
            yield entry
        if not res.has_more:
            break
        try:
            res = dbx.files_list_folder_continue(res.cursor)
        except Exception as e:
            if status is not None:
                status['truncated'] = True
                status['error'] = type(e).__name__
            break


@app.route("/admin/docs/project/<int:pid>/source-audit", methods=["POST"])
@login_required
def admin_docs_source_audit(pid):
    """READ-ONLY: reconcile a folder of ORIGINAL receipts (a backup folder whose
    filenames differ from the Analyzer-renamed copies) against what the software
    has already filed. Matching is by Dropbox content_hash (free from metadata,
    no byte download), so it's exact and fast even for big folders.

    For every file in the source folder, bucket it as:
      * in_software  — its bytes are already in the project's PROCESSED
        DOCUMENTS tree (filed copy OR _SOURCE_ARCHIVE original) ⇒ it went
        through the app.
      * name_match    — no content_hash match, but a file/DocUpload with the
        same basename exists (likely the same receipt re-exported/re-scanned;
        needs a human eye, NOT auto-imported).
      * missing       — neither ⇒ this original never reached the software.

    Body: {"source_path": "<path>"}. Makes NO writes. (User 2026-06-03.)"""
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    project = ProjectSheet.query.get_or_404(pid)
    if not project.dropbox_folder:
        return jsonify({"error": "Project has no Dropbox folder configured"}), 400
    body = request.get_json(silent=True) or {}
    src_path = _resolve_dbx_path(body.get('source_path') or request.args.get('source_path'))
    if not src_path:
        return jsonify({"error": "source_path required"}), 400
    if not _path_in_project(src_path, project):
        return jsonify({"error": "source_path must be inside this project's own "
                                 "Dropbox folder."}), 403
    try:
        dbx = _dbx_client()
    except Exception as e:
        return jsonify({"error": "Dropbox init failed", "detail": type(e).__name__}), 500

    proj_root = (f"/{project.dropbox_folder}" if _DBX_NAMESPACE_ID
                 else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}")

    # 1) Index everything the software already has: content hashes (filed copies
    #    + original-bytes archive) and basenames, from the processed tree.
    proc_hashes, proc_names = set(), set()
    proc_scanned = 0
    for e in _walk_dbx_files(dbx, proj_root + "/01_ADMIN/PROCESSED DOCUMENTS"):
        proc_scanned += 1
        proc_hashes.add(e.content_hash)
        proc_names.add((e.name or '').lower())
    # DocUpload basenames too (covers rows whose file moved or whose name was
    # the original, pre-rename form).
    for u in DocUpload.query.with_entities(
                DocUpload.original_filename, DocUpload.filed_filename
            ).filter_by(project_id=pid).all():
        for nm in (u.original_filename, u.filed_filename):
            if nm:
                proc_names.add(nm.lower())

    # Semantic safety net: this kind of backup folder is often CURATED — files
    # hand-renamed / re-combined (e.g. "INVOICE+PROOFofPAYMENT.pdf"), so their
    # bytes differ from whatever was uploaded and content_hash alone over-counts
    # "missing". So for every byte-missing file we also parse its dollar amount
    # from the filename and check it against amounts ALREADY in the project
    # (transactions + docs). A byte-missing file whose amount is already in the
    # system is almost certainly the same expense in a different wrapper — NOT a
    # true gap. (User 2026-06-03.)
    # (Uses the canonical module-level _amounts_in_name — hardened 2026-06-04.)
    existing_cents = set()
    for (a,) in db.session.query(Transaction.amount).filter(
            Transaction.project_id == pid, Transaction.amount.isnot(None)).all():
        try: existing_cents.add(int(round(float(a) * 100)))
        except Exception: pass
    for (a,) in db.session.query(DocUpload.amount).filter(
            DocUpload.project_id == pid, DocUpload.amount.isnot(None)).all():
        try: existing_cents.add(int(round(float(a) * 100)))
        except Exception: pass

    # 2) Walk the source originals folder; bucket by hash, then name.
    SKIP = {'.ds_store', 'thumbs.db', 'desktop.ini', 'icon\r'}
    src_prefix = src_path.rstrip('/') + '/'
    in_software = name_match = missing = src_total = 0
    # missing sub-buckets (content_hash miss + name miss):
    amt_in_system = amt_no_match = no_amount = 0
    missing_sample, name_sample, true_gap_sample = [], [], []
    from collections import Counter as _Counter
    by_subfolder = _Counter()
    src_err = None
    try:
        for e in _walk_dbx_files(dbx, src_path):
            nm = (e.name or '')
            if nm.lower() in SKIP or nm.startswith('.') or getattr(e, 'size', 0) == 0:
                continue
            src_total += 1
            if e.content_hash in proc_hashes:
                in_software += 1
                continue
            if nm.lower() in proc_names:
                name_match += 1
                if len(name_sample) < 40:
                    name_sample.append({"filename": nm, "path": e.path_display})
                continue
            # byte-missing → classify by amount-in-filename vs amounts in system
            missing += 1
            pd = (e.path_display or '')
            sub = pd[len(src_prefix):].split('/')[0] if pd.lower().startswith(src_prefix.lower()) and '/' in pd[len(src_prefix):] else '(root)'
            by_subfolder[sub] += 1
            amts = _amounts_in_name(nm)
            row = {"filename": nm, "path": e.path_display,
                   "size": getattr(e, 'size', None),
                   "amounts": sorted(a/100 for a in amts)}
            if amts and (amts & existing_cents):
                amt_in_system += 1
            elif amts:
                amt_no_match += 1
                if len(true_gap_sample) < 60:
                    true_gap_sample.append(row)
            else:
                no_amount += 1
            if len(missing_sample) < 60:
                missing_sample.append(row)
    except Exception as _e:
        src_err = type(_e).__name__

    return jsonify({
        "project": project.name,
        "source_path": src_path,
        "source_files": src_total,
        "processed_files_indexed": proc_scanned,
        "in_software_exact": in_software,
        "name_match_only": name_match,
        "byte_missing": missing,
        # the breakdown that actually matters:
        "missing_amount_already_in_system": amt_in_system,
        "missing_amount_NOT_in_system": amt_no_match,
        "missing_no_amount_in_filename": no_amount,
        "by_subfolder": dict(by_subfolder.most_common()),
        "true_gap_sample": true_gap_sample,
        "missing_sample": missing_sample,
        "name_match_sample": name_sample,
        "source_error": src_err,
        "note": "byte_missing = no content_hash match. Of those, "
                "'amount_already_in_system' is almost certainly the same expense "
                "in a different file wrapper (not a real gap). The real review "
                "set is 'amount_NOT_in_system' + 'no_amount_in_filename'.",
    })


@app.route("/admin/docs/project/<int:pid>/source-import", methods=["POST"])
@login_required
def admin_docs_source_import(pid):
    """Pull the MISSING originals (per source-audit's content_hash logic) back
    into the software: download each from the source folder and run it through
    the real upload pipeline (Veryfi OCR → auto-file → DocUpload → Actuals
    Transaction), exactly like an interactive upload. The pipeline's own SHA-256
    dedup still applies, so a re-run is safe.

    Body: {"source_path": "<path>", "apply": bool, "limit": int}. Dry-run by
    default (apply=false) — reports which files WOULD be imported without
    touching anything. `limit` caps how many files are OCR'd per call (OCR is
    slow; run repeatedly to drain a large backlog). (User 2026-06-03.)"""
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    project = ProjectSheet.query.get_or_404(pid)
    if not project.dropbox_folder:
        return jsonify({"error": "Project has no Dropbox folder configured"}), 400
    body = request.get_json(silent=True) or {}
    src_path = _resolve_dbx_path(body.get('source_path') or request.args.get('source_path'))
    if not src_path:
        return jsonify({"error": "source_path required"}), 400
    if not _path_in_project(src_path, project):
        return jsonify({"error": "source_path must be inside this project's own "
                                 "Dropbox folder."}), 403
    apply = bool(body.get('apply')) or (request.args.get('apply') == '1')
    try:
        limit = int(body.get('limit') or request.args.get('limit') or 10)
    except (TypeError, ValueError):
        limit = 10
    limit = max(1, min(limit, 50))
    try:
        dbx = _dbx_client()
    except Exception as e:
        return jsonify({"error": "Dropbox init failed", "detail": type(e).__name__}), 500

    proj_root = (f"/{project.dropbox_folder}" if _DBX_NAMESPACE_ID
                 else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}")

    # Re-derive the missing set (same content_hash logic as the audit). If the
    # Dropbox walk truncates we must NOT import — a partial proc_hashes set would
    # treat already-filed receipts as missing and re-import them. (CR 2026-06-04.)
    proc_hashes, proc_names = set(), set()
    _walk_status = {}
    for e in _walk_dbx_files(dbx, proj_root + "/01_ADMIN/PROCESSED DOCUMENTS", status=_walk_status):
        proc_hashes.add(e.content_hash)
        proc_names.add((e.name or '').lower())
    if _walk_status.get('truncated'):
        return jsonify({"error": "Dropbox listing was incomplete (rate-limited or "
                                 "transient error); refusing to import to avoid "
                                 "re-importing already-filed receipts. Try again.",
                        "detail": _walk_status.get('error')}), 503
    for u in DocUpload.query.with_entities(
                DocUpload.original_filename, DocUpload.filed_filename
            ).filter_by(project_id=pid).all():
        for nm in (u.original_filename, u.filed_filename):
            if nm:
                proc_names.add(nm.lower())

    # Same semantic guard as the audit: by default DON'T re-import a byte-missing
    # file whose dollar amount is already present in the project (it's the same
    # expense in a different wrapper). Pass include_amount_in_system=true to
    # override. (User 2026-06-03.)
    include_amt_in_system = bool(body.get('include_amount_in_system'))
    # (Uses the canonical module-level _amounts_in_name — hardened 2026-06-04.)
    existing_cents = set()
    if not include_amt_in_system:
        for (a,) in db.session.query(Transaction.amount).filter(
                Transaction.project_id == pid, Transaction.amount.isnot(None)).all():
            try: existing_cents.add(int(round(float(a) * 100)))
            except Exception: pass
        for (a,) in db.session.query(DocUpload.amount).filter(
                DocUpload.project_id == pid, DocUpload.amount.isnot(None)).all():
            try: existing_cents.add(int(round(float(a) * 100)))
            except Exception: pass

    SKIP = {'.ds_store', 'thumbs.db', 'desktop.ini', 'icon\r'}
    missing, skipped_amt_in_system = [], 0
    for e in _walk_dbx_files(dbx, src_path):
        nm = (e.name or '')
        if nm.lower() in SKIP or nm.startswith('.') or getattr(e, 'size', 0) == 0:
            continue
        if e.content_hash in proc_hashes or nm.lower() in proc_names:
            continue
        if not include_amt_in_system:
            amts = _amounts_in_name(nm)
            if amts and (amts & existing_cents):
                skipped_amt_in_system += 1
                continue
        missing.append(e)
    total_missing = len(missing)
    batch = missing[:limit]

    if not apply:
        return jsonify({
            "dry": True, "source_path": src_path,
            "candidates_after_amount_filter": total_missing,
            "skipped_amount_already_in_system": skipped_amt_in_system,
            "include_amount_in_system": include_amt_in_system,
            "would_import_now": len(batch),
            "remaining_after": max(0, total_missing - len(batch)),
            "sample": [{"filename": e.name, "size": getattr(e, 'size', None)} for e in batch],
            "note": "Dry run. POST apply=true to OCR + file these. Re-run to drain the rest. "
                    "Set include_amount_in_system=true to also import files whose amount already exists.",
        })

    # APPLY: download + run the real pipeline per file.
    import re as _re, json as _json
    from datetime import datetime as _dt
    from fp_analyzer import analyze_and_file_single, extract_card_last4 as _extract_card4
    _raw_user = (getattr(current_user, 'name', None)
                 or (current_user.email or '').split('@')[0] or 'unknown')
    _safe_user = _re.sub(r"[^\w\- ]", "", _raw_user) or "unknown"

    imported, dup_flagged, errors, txns = 0, 0, [], 0
    detail = []
    for e in batch:
        try:
            _md, resp = dbx.files_download(e.path_display)
            data = resp.content
        except Exception as _de:
            errors.append(f"download {e.name}: {type(_de).__name__}")
            continue
        import hashlib as _hl
        file_hash = _hl.sha256(data).hexdigest()
        # Skip if the exact bytes are already a filed DocUpload (defensive — the
        # content_hash pre-filter should have caught it, but SHA-256 is the
        # pipeline's own dedup key).
        dup = (DocUpload.query.filter_by(project_id=pid, file_hash=file_hash)
               .filter(DocUpload.filed_dropbox_path.isnot(None))
               .filter(DocUpload.status != 'review')
               .filter(DocUpload.status != 'deleted').first())
        try:
            result = analyze_and_file_single(
                file_bytes=data, filename=e.name,
                project_name=project.dropbox_folder, user_name=_safe_user)
        except Exception as _ae:
            errors.append(f"analyze {e.name}: {type(_ae).__name__}")
            continue
        vr = result.get("vr") or {}
        vendor_name = amount = doc_date = doc_number = None
        if vr:
            v = vr.get("vendor") or {}
            vendor_name = v.get("name") or v.get("raw_name")
            try:
                amount = float(vr.get("total")) if vr.get("total") is not None else None
            except Exception:
                amount = None
            try:
                _d = vr.get("date") or ""
                doc_date = _dt.strptime(_d[:10], "%Y-%m-%d").date() if _d else None
            except Exception:
                doc_date = None
            doc_number = (vr.get("invoice_number") or vr.get("purchase_order_number")
                          or vr.get("tax_id") or vr.get("ein") or None)
            if doc_number:
                doc_number = str(doc_number)[:100]
        status_map = {"filed": "done", "needs_review": "review", "error": "error"}
        upload_status = status_map.get(result.get("status"), "error")

        # Fix 1 (User 2026-06-03): the dollar amount the user curated INTO the
        # filename is more reliable than OCR on these backups (especially the
        # foreign-language receipts OCR misreads). Prefer it when present; for
        # multiple amounts take the largest magnitude (the total vs a tip/fee),
        # stored positive.
        _fn_amts = _amounts_in_name(e.name)
        if _fn_amts:
            amount = max(_fn_amts) / 100.0
        # Fix 2 (User 2026-06-03): "INVOICE+PROOFofPAYMENT" PDFs often misclassify
        # as estimate/quote/PO — forecast types that never reach the ledger. If
        # the filename says invoice, force category=invoice so it becomes an
        # Actuals transaction.
        _doc_cat = result.get("doc_type")
        if ('invoice' in (e.name or '').lower()
                and (_doc_cat or '') in ('estimate', 'quote', 'purchase_order', 'misc', '', None)):
            _doc_cat = 'invoice'
        try:
            up = DocUpload(
                project_id=pid, uploader_id=current_user.id,
                original_filename=e.name, file_size=len(data),
                content_type='application/octet-stream', file_hash=file_hash,
                status=upload_status, veryfi_data=_json.dumps(vr) if vr else None,
                vendor=vendor_name, amount=amount, doc_date=doc_date,
                doc_number=doc_number,
                card_last4=(_extract_card4(vr) if vr else None),
                confidence=round(float(result.get("confidence") or 0) * 100, 2),
                category=_doc_cat,
                veryfi_category=(vr.get("category") if vr else None),
                filed_filename=result.get("new_filename") or None,
                filed_dropbox_path=result.get("filed_path") or result.get("staged_path"),
                filed_at=_dt.utcnow() if result.get("filed_path") else None,
                source_archive_path=result.get("staged_path"),
                is_duplicate=bool(dup),  # byte-hash only; autorename ≠ duplicate (CR 2026-06-04)
                duplicate_of_id=dup.id if dup else None,
                note='Imported from source-folder audit')
            db.session.add(up)
            db.session.commit()
        except Exception as _ce:
            db.session.rollback()
            errors.append(f"save {e.name}: {type(_ce).__name__}")
            continue
        imported += 1
        if up.is_duplicate:
            dup_flagged += 1
        # Actuals Transaction for receipts/invoices that aren't duplicates.
        if (up.status in ('done', 'review') and not up.is_duplicate
                and (up.category or '') in ('receipt', 'invoice')):
            try:
                db.session.add(Transaction(
                    project_id=pid, source='doc_upload', doc_upload_id=up.id,
                    vendor=up.vendor, amount=up.amount,
                    txn_date=up.doc_date.isoformat() if up.doc_date else None,
                    card_last4=up.card_last4, is_expense=True,
                    match_status='unmatched',
                    created_via_user_id=current_user.id))
                db.session.commit(); txns += 1
            except Exception:
                db.session.rollback()
        if len(detail) < 25:
            detail.append({"filename": e.name, "category": up.category,
                           "amount": float(up.amount) if up.amount is not None else None,
                           "status": up.status, "duplicate": bool(up.is_duplicate)})

    return jsonify({
        "dry": False, "applied": True, "source_path": src_path,
        "total_missing": total_missing, "processed_this_call": len(batch),
        "imported": imported, "duplicate_flagged": dup_flagged,
        "txns_created": txns, "remaining": max(0, total_missing - len(batch)),
        "errors": errors[:25], "detail": detail,
    })


# ── Server-side background drainer for source-folder import ─────────────────
# A browser-driven loop gets frozen by Chrome's background-tab timer throttling,
# so a long (hundreds of files) import can't run unattended there. This runs the
# whole drain in a daemon thread on the server, independent of the browser, with
# per-file commits (resumable) and a polled status dict. (User 2026-06-03.)
_SOURCE_DRAIN = {}   # pid -> progress dict


# Alias kept for the drain worker's call sites; the canonical hardened parser
# lives next to _parse_analyzer_filename. (Consolidated 2026-06-04, CR-4.)
_source_drain_amounts_in_name = _amounts_in_name


def _source_drain_worker(flask_app, pid, src_path, user_id, include_amt):
    import hashlib as _hl, json as _json, re as _re
    from datetime import datetime as _dt
    from fp_analyzer import analyze_and_file_single, extract_card_last4 as _extract_card4
    prog = _SOURCE_DRAIN[pid]
    with flask_app.app_context():
        try:
            project = ProjectSheet.query.get(pid)
            user = User.query.get(user_id)
            _raw_user = (getattr(user, 'name', None)
                         or (user.email or '').split('@')[0] or 'unknown') if user else 'unknown'
            _safe_user = _re.sub(r"[^\w\- ]", "", _raw_user) or "unknown"
            dbx = _dbx_client()
            proj_root = (f"/{project.dropbox_folder}" if _DBX_NAMESPACE_ID
                         else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}")
            SKIP = {'.ds_store', 'thumbs.db', 'desktop.ini', 'icon\r'}

            # Build exclusion + amount sets ONCE; keep them current incrementally.
            # Abort if the proc-tree walk truncated — a partial set would
            # re-import already-filed receipts. (Code review 2026-06-04.)
            proc_hashes, proc_names = set(), set()
            _walk_status = {}
            for e in _walk_dbx_files(dbx, proj_root + "/01_ADMIN/PROCESSED DOCUMENTS", status=_walk_status):
                proc_hashes.add(e.content_hash); proc_names.add((e.name or '').lower())
            if _walk_status.get('truncated'):
                prog['running'] = False
                prog['done'] = True
                prog['note'] = ('aborted: Dropbox listing incomplete (' +
                                str(_walk_status.get('error')) + ') — not importing on a '
                                'partial file list; re-run when Dropbox is healthy')
                return
            for u in DocUpload.query.with_entities(
                        DocUpload.original_filename, DocUpload.filed_filename
                    ).filter_by(project_id=pid).all():
                for nm in (u.original_filename, u.filed_filename):
                    if nm:
                        proc_names.add(nm.lower())
            existing_cents = set()
            if not include_amt:
                for (a,) in db.session.query(Transaction.amount).filter(
                        Transaction.project_id == pid, Transaction.amount.isnot(None)).all():
                    try: existing_cents.add(int(round(float(a) * 100)))
                    except Exception: pass
                for (a,) in db.session.query(DocUpload.amount).filter(
                        DocUpload.project_id == pid, DocUpload.amount.isnot(None)).all():
                    try: existing_cents.add(int(round(float(a) * 100)))
                    except Exception: pass

            # Walk the source folder ONCE → ordered candidate list.
            candidates = []
            for e in _walk_dbx_files(dbx, src_path):
                nm = (e.name or '')
                if nm.lower() in SKIP or nm.startswith('.') or getattr(e, 'size', 0) == 0:
                    continue
                if e.content_hash in proc_hashes or nm.lower() in proc_names:
                    continue
                if not include_amt:
                    amts = _source_drain_amounts_in_name(nm)
                    if amts and (amts & existing_cents):
                        continue
                candidates.append(e)
            prog['total'] = len(candidates)

            consec_fail = 0
            for target in candidates:
                if not prog['running']:
                    break
                nm = (target.name or '')
                if nm.lower() in proc_names:      # imported earlier this run / dup name
                    prog['skipped'] += 1; continue
                try:
                    _md, resp = dbx.files_download(target.path_display)
                    data = resp.content
                    file_hash = _hl.sha256(data).hexdigest()
                    dup = (DocUpload.query.filter_by(project_id=pid, file_hash=file_hash)
                           .filter(DocUpload.filed_dropbox_path.isnot(None))
                           .filter(DocUpload.status != 'review')
               .filter(DocUpload.status != 'deleted').first())
                    result = analyze_and_file_single(
                        file_bytes=data, filename=nm,
                        project_name=project.dropbox_folder, user_name=_safe_user)
                    vr = result.get("vr") or {}
                    vendor_name = amount = doc_date = doc_number = None
                    if vr:
                        v = vr.get("vendor") or {}
                        vendor_name = v.get("name") or v.get("raw_name")
                        try: amount = float(vr.get("total")) if vr.get("total") is not None else None
                        except Exception: amount = None
                        try:
                            _d = vr.get("date") or ""
                            doc_date = _dt.strptime(_d[:10], "%Y-%m-%d").date() if _d else None
                        except Exception: doc_date = None
                        doc_number = (vr.get("invoice_number") or vr.get("purchase_order_number")
                                      or vr.get("tax_id") or vr.get("ein") or None)
                        if doc_number:
                            doc_number = str(doc_number)[:100]
                    _fn = _source_drain_amounts_in_name(nm)
                    if _fn:
                        amount = max(_fn) / 100.0
                    _doc_cat = result.get("doc_type")
                    if ('invoice' in nm.lower()
                            and (_doc_cat or '') in ('estimate', 'quote', 'purchase_order', 'misc', '', None)):
                        _doc_cat = 'invoice'
                    status_map = {"filed": "done", "needs_review": "review", "error": "error"}
                    up = DocUpload(
                        project_id=pid, uploader_id=user_id, original_filename=nm,
                        uploaded_at=_dt.utcnow(),
                        file_size=len(data), content_type='application/octet-stream',
                        file_hash=file_hash, status=status_map.get(result.get("status"), "error"),
                        veryfi_data=_json.dumps(vr) if vr else None, vendor=vendor_name,
                        amount=amount, doc_date=doc_date, doc_number=doc_number,
                        card_last4=(_extract_card4(vr) if vr else None),
                        confidence=round(float(result.get("confidence") or 0) * 100, 2),
                        category=_doc_cat, veryfi_category=(vr.get("category") if vr else None),
                        filed_filename=result.get("new_filename") or None,
                        filed_dropbox_path=result.get("filed_path") or result.get("staged_path"),
                        filed_at=_dt.utcnow() if result.get("filed_path") else None,
                        source_archive_path=result.get("staged_path"),
                        is_duplicate=bool(dup),  # byte-hash only; autorename ≠ duplicate (CR 2026-06-04)
                        duplicate_of_id=dup.id if dup else None,
                        note='Imported from source-folder audit')
                    db.session.add(up); db.session.commit()
                    proc_names.add(nm.lower()); proc_hashes.add(target.content_hash)
                    prog['imported'] += 1
                    if up.is_duplicate:
                        prog['dups'] += 1
                    if (up.status in ('done', 'review') and not up.is_duplicate
                            and (up.category or '') in ('receipt', 'invoice')):
                        try:
                            db.session.add(Transaction(
                                project_id=pid, source='doc_upload', doc_upload_id=up.id,
                                vendor=up.vendor, amount=up.amount,
                                txn_date=up.doc_date.isoformat() if up.doc_date else None,
                                card_last4=up.card_last4, is_expense=True,
                                match_status='unmatched', created_via_user_id=user_id))
                            db.session.commit(); prog['txns'] += 1
                        except Exception:
                            db.session.rollback()
                    prog['last'] = nm; consec_fail = 0
                except Exception as _pe:
                    db.session.rollback()
                    prog['failed'] += 1
                    if len(prog['errors']) < 30:
                        prog['errors'].append((type(_pe).__name__ + ' @ ' + nm)[:140])
                    consec_fail += 1
                    if consec_fail >= 5:
                        prog['note'] = 'aborted after 5 consecutive failures'
                        break
                finally:
                    prog['processed'] += 1
                    # Release per-file working set so OCR'ing big multi-page PDFs
                    # doesn't grow the worker until Render's 512MB OOM killer
                    # reaps it (which would silently kill this thread). (2026-06-03)
                    try:
                        del data
                    except Exception:
                        pass
                    try:
                        import gc as _gc; _gc.collect()
                    except Exception:
                        pass
            # All receipts imported — run the matcher once so they get paired
            # with open bank charges without a manual ⚡ Auto-Match. (2026-06-11.)
            if prog.get('imported'):
                try:
                    from actuals import run_auto_match
                    _am = run_auto_match(pid)
                    prog['auto_match_suggestions'] = _am.get('suggestions')
                except Exception as _ame:
                    prog['errors'].append('automatch:' + type(_ame).__name__)
        except Exception as _we:
            prog['errors'].append('worker:' + type(_we).__name__)
        finally:
            prog['running'] = False
            prog['done'] = True
            try:
                db.session.remove()
            except Exception:
                pass


@app.route("/admin/docs/project/<int:pid>/source-import-drain", methods=["POST"])
@login_required
def admin_docs_source_import_drain(pid):
    """Start a SERVER-SIDE background drain of all missing source originals
    (same logic/fixes as /source-import, but runs in a daemon thread so it
    survives browser-tab throttling). Returns immediately; poll
    /source-import-drain-status. Re-callable: a finished run can be restarted to
    catch stragglers (dedup makes it safe). (User 2026-06-03.)"""
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    project = ProjectSheet.query.get_or_404(pid)
    if not project.dropbox_folder:
        return jsonify({"error": "Project has no Dropbox folder configured"}), 400
    body = request.get_json(silent=True) or {}
    src_path = _resolve_dbx_path(body.get('source_path') or request.args.get('source_path'))
    if not src_path:
        return jsonify({"error": "source_path required"}), 400
    if not _path_in_project(src_path, project):
        return jsonify({"error": "source_path must be inside this project's own "
                                 "Dropbox folder."}), 403
    # DB-derived single-flight (works across gunicorn workers, unlike an
    # in-memory flag): if an import landed in the last 90s, a drain is actively
    # running somewhere — don't spawn a second one that would race it. Pass
    # force=true to override (e.g. after a confirmed stall). (User 2026-06-03.)
    force = bool(body.get('force')) or (request.args.get('force') == '1')
    last_dt, secs = _drain_heartbeat(pid)
    if last_dt is not None and secs is not None and secs < 90 and not force:
        return jsonify({"already_running": True, "seconds_since_last_import": round(secs, 1),
                        "hint": "A drain is active (an import landed <90s ago). "
                                "Pass force=true to start another anyway."})
    include_amt = bool(body.get('include_amount_in_system'))
    _SOURCE_DRAIN[pid] = {'running': True, 'done': False, 'total': None, 'processed': 0,
                          'imported': 0, 'txns': 0, 'dups': 0, 'failed': 0, 'skipped': 0,
                          'last': None, 'errors': [], 'note': None, 'src': src_path}
    import threading
    t = threading.Thread(target=_source_drain_worker,
                         args=(app, pid, src_path, current_user.id, include_amt),
                         daemon=True)
    t.start()
    return jsonify({"started": True, "source_path": src_path,
                    "include_amount_in_system": include_amt})


def _drain_heartbeat(pid):
    """(latest import timestamp, seconds-since) for source-folder imports in this
    project — the DB-derived heartbeat that survives worker splits/restarts."""
    from datetime import datetime as _dt
    row = (db.session.query(db.func.max(DocUpload.uploaded_at))
           .filter(DocUpload.project_id == pid,
                   DocUpload.note == 'Imported from source-folder audit').first())
    last_dt = row[0] if row else None
    if not last_dt:
        return None, None
    try:
        return last_dt, (_dt.utcnow() - last_dt).total_seconds()
    except Exception:
        return last_dt, None


@app.route("/admin/docs/project/<int:pid>/source-import-drain-status", methods=["GET"])
@login_required
def admin_docs_source_import_drain_status(pid):
    """DB-derived progress (worker-independent): total imported so far, whether a
    drain is currently active (an import landed in the last 90s), and this
    worker's in-memory counters if it happens to be the one running the thread."""
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    imported_total = (DocUpload.query
                      .filter(DocUpload.project_id == pid,
                              DocUpload.note == 'Imported from source-folder audit').count())
    last_dt, secs = _drain_heartbeat(pid)
    active = (secs is not None and secs < 90)
    out = {"imported_total": imported_total,
           "last_import_at": last_dt.isoformat() + 'Z' if last_dt else None,
           "seconds_since_last_import": round(secs, 1) if secs is not None else None,
           "active": active}
    p = _SOURCE_DRAIN.get(pid)
    if p:
        out["this_worker"] = {k: p[k] for k in
                              ('running', 'done', 'total', 'processed', 'imported',
                               'txns', 'dups', 'failed', 'skipped', 'last', 'note')}
        out["this_worker"]["errors"] = p['errors'][:10]
    return jsonify(out)


@app.route("/admin/docs/project/<int:pid>/reconcile", methods=["POST"])
@login_required
def admin_docs_reconcile_project(pid):
    """Walk the project's Dropbox doc folders and create DocUpload rows
    for any files present in Dropbox but missing from our DB.

    Motivation: if a user closes the browser tab mid-upload batch, the
    file can land in Dropbox (the Analyzer runs synchronously inside the
    request, but the browser may abort before the response is handled
    and the DocUpload row still commits — OR, in the legacy / pre-OCR
    pipeline, some files were filed manually). This tool gives us a way
    to reconcile the two sources of truth.

    Strategy:
      * For every subfolder in DOCUMENT_TYPES (+ the default receipts
        folder), list files recursively under the project root.
      * For each file, check whether a DocUpload row already references
        its path (filed_dropbox_path) for THIS project.
      * If not, create a status='filed' DocUpload row with whatever we
        can derive (filename, size, content-type, category from subfolder
        name). uploader_id = current user (best effort).

    Returns counts + sample orphan list. Does NOT move or re-OCR files.
    """
    # Permission: project editor or higher (was super_admin only). The
    # reconcile is a recovery action — when a user's upload made it to
    # Dropbox but the DB commit got cut off (page refresh mid-upload,
    # network blip, server timeout), they need to be able to fix it
    # themselves without flagging an admin.
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    if current_user.role not in ('super_admin', 'admin'):
        # Non-admins must have editor or higher access on this project.
        access = ProjectAccess.query.filter_by(
            project_id=pid, user_id=current_user.id
        ).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403

    project = ProjectSheet.query.get_or_404(pid)
    if not project.dropbox_folder:
        return jsonify({"error": "Project has no Dropbox folder configured"}), 400

    from fp_analyzer import DOCUMENT_TYPES
    try:
        dbx = _dbx_client()
    except Exception as e:
        return jsonify({"error": f"Dropbox client init failed: {e}"}), 500

    # Build the project root. Namespace vs legacy mode matters here —
    # mirrors the pattern used in docs_upload_retry_filing.
    proj_root = (f"/{project.dropbox_folder}"
                 if _DBX_NAMESPACE_ID
                 else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}")

    # Collect the set of doc-type subfolders we care about. DOCUMENT_TYPES
    # gives us canonical paths; de-dupe because several types share a
    # folder (invoice + contract → CONTRACTS & INVOICES).
    subfolders = set(DOCUMENT_TYPES.values())
    subfolders.add("01_ADMIN/RECEIPTS FOLDER")  # Analyzer's default fallback
    # Per 2026-04-30 fail-safe: every uploaded file is also archived
    # under _SOURCE_ARCHIVE/. A file that exists ONLY in archive (no
    # processed copy) means OCR/copy completed but the DB commit was
    # interrupted — exactly the orphan case we're trying to recover.
    subfolders.add("01_ADMIN/PROCESSED DOCUMENTS/_SOURCE_ARCHIVE")

    # Pre-load existing filed paths so we can do set-membership checks
    # without re-hitting the DB per file.
    # Pre-load identifiers we'll match incoming Dropbox files against.
    # Earlier reconcile passes used path equality only — but stored
    # filed_dropbox_path can have THREE forms depending on when the row
    # was saved (legacy ops-prefix / namespace-relative / different
    # capitalization). The result was scan creating duplicate rows for
    # files that were already tracked. We now match on multiple keys:
    #
    #   - the full lowercased path (both raw and namespace-normalized)
    #   - the BASENAME (final filename) — strongest signal that two
    #     rows refer to the same file regardless of path drift
    #   - the file content hash (file_hash) when present, looked up
    #     out-of-band by basename match below
    #
    # If ANY of these hit, we skip the file. False negatives (real
    # orphans we don't reconcile) are recoverable by re-uploading; false
    # positives (duplicate rows) are user-visible bugs that erode trust.
    import os as _os_for_scan
    existing_full   = set()
    existing_names  = set()  # basename, lowercased
    for u in DocUpload.query.with_entities(
                DocUpload.filed_dropbox_path,
                DocUpload.original_filename,
                DocUpload.filed_filename
            ).filter_by(project_id=pid).all():
        if u.filed_dropbox_path:
            full = u.filed_dropbox_path.lower()
            existing_full.add(full)
            existing_names.add(_os_for_scan.basename(full))
            if _DBX_NAMESPACE_ID and _DBX_OPS_ROOT:
                pfx = _DBX_OPS_ROOT.rstrip('/').lower()
                if full.startswith(pfx + '/'):
                    existing_full.add(full[len(pfx):])
                else:
                    existing_full.add(pfx + full)
        for nm in (u.filed_filename, u.original_filename):
            if nm:
                existing_names.add(nm.lower())

    created = 0
    scanned = 0
    errors  = []
    sample  = []

    from datetime import datetime as _dt
    import mimetypes as _mt

    _do_dry = (request.args.get('dry') == '1') or bool((request.get_json(silent=True) or {}).get('dry'))

    # Walk the ENTIRE project root recursively. Previously we walked only an
    # enumerated subfolder set, which MISSED receipts filed under person
    # folders (PROCESSED DOCUMENTS/<name>/) or any non-listed location — they
    # were never imported, so they never surfaced for matching. Parse each
    # Analyzer filename to backfill date/amount/category/vendor so the imported
    # receipt is immediately matchable (not a blank row). Skip trash, parked
    # duplicates, and the pre-processing _SOURCE_ARCHIVE copy. (User 2026-06-02.)
    try:
        res = dbx.files_list_folder(proj_root + "/01_ADMIN/PROCESSED DOCUMENTS", recursive=True)
    except Exception as _le:
        return jsonify({"error": f"list {proj_root}: {_le}"}), 500
    while True:
        for entry in res.entries:
            if not hasattr(entry, 'size'):
                continue
            pl = (entry.path_display or "").lower()
            if '/_trash' in pl or '/_source_archive' in pl or '/_duplicates' in pl:
                continue
            scanned += 1
            if pl in existing_full:
                continue
            filename = entry.name or ""
            if filename.lower() in existing_names:
                continue
            guessed_ct = _mt.guess_type(filename)[0] or "application/octet-stream"
            parsed = _parse_analyzer_filename(filename)
            _dd = None
            if parsed.get('doc_date'):
                try:
                    _dd = _dt.strptime(parsed['doc_date'], '%Y-%m-%d').date()
                except ValueError:
                    _dd = None
            try:
                new_row = DocUpload(
                    project_id=pid,
                    uploader_id=current_user.id,
                    uploaded_at=getattr(entry, 'server_modified', None) or _dt.utcnow(),
                    r2_key=None,
                    original_filename=filename,
                    filed_filename=filename,
                    filed_dropbox_path=entry.path_display,
                    filed_at=getattr(entry, 'server_modified', None) or _dt.utcnow(),
                    file_size=getattr(entry, 'size', None),
                    content_type=guessed_ct,
                    status='filed',
                    category=parsed.get('category'),
                    vendor=parsed.get('vendor'),
                    amount=parsed.get('amount'),
                    doc_date=_dd,
                    note="Reconciled from Dropbox scan",
                )
                if not _do_dry:
                    db.session.add(new_row)
                    existing_names.add(filename.lower())   # don't double-create archive vs processed
                    existing_full.add(pl)
                created += 1
                if len(sample) < 25:
                    sample.append({"filename": filename, "path": entry.path_display,
                                   "category": parsed.get('category'),
                                   "amount": parsed.get('amount'), "date": parsed.get('doc_date')})
            except Exception as _ce:
                errors.append(f"create row for {entry.path_display}: {_ce}")
        if not res.has_more:
            break
        try:
            res = dbx.files_list_folder_continue(res.cursor)
        except Exception as _ce:
            errors.append(f"continue: {_ce}")
            break

    if _do_dry:
        db.session.rollback()
        return jsonify({"dry": True, "would_create": created, "scanned": scanned,
                        "sample": sample, "errors": errors[:20]})

    try:
        db.session.commit()
    except Exception as _ce:
        db.session.rollback()
        return jsonify({
            "error": f"Commit failed: {_ce}",
            "created": 0,
            "scanned": scanned,
            "errors": errors[:20],
        }), 500

    # ── Auto-create Transaction rows for the freshly-reconciled docs ──
    # Mirrors the upload handler's behavior so reconciled receipts show
    # up in the Actuals tab too. Skips non-ledger doc types (tax forms,
    # contracts, releases, etc.) — same rule as the upload path.
    txns_created = 0
    if created:
        _NON_LEDGER_TYPES = {'tax_form', 'contract', 'release', 'legal',
                              'insurance', 'misc', 'employee_vendor_doc'}
        # Re-fetch the new rows by note marker (we tagged them with
        # "Reconciled from Dropbox scan"). Faster than re-checking each
        # path against existing_full.
        new_uploads = (DocUpload.query
                       .filter_by(project_id=pid)
                       .filter(DocUpload.note == "Reconciled from Dropbox scan")
                       .all())
        for u in new_uploads:
            if (u.category or '') in _NON_LEDGER_TYPES:
                continue
            # Skip if a Transaction already references this doc — covers
            # repeated reconcile runs.
            existing_txn = (Transaction.query
                            .filter_by(doc_upload_id=u.id)
                            .first())
            if existing_txn:
                continue
            try:
                db.session.add(Transaction(
                    project_id          = pid,
                    source              = 'doc_upload',
                    doc_upload_id       = u.id,
                    vendor              = u.vendor,
                    amount              = u.amount,
                    txn_date            = u.doc_date.isoformat() if u.doc_date else None,
                    is_expense          = True,
                    note                = u.note,
                    match_status        = 'unmatched',
                    created_via_user_id = current_user.id if current_user.is_authenticated else None,
                ))
                txns_created += 1
            except Exception as _te:
                errors.append(f"create txn for upload {u.id}: {_te}")
        if txns_created:
            try:
                db.session.commit()
            except Exception as _tce:
                db.session.rollback()
                errors.append(f"txn commit failed: {_tce}")
                txns_created = 0

    return jsonify({
        "ok":       True,
        "scanned":  scanned,
        "created":  created,
        "txns_created": txns_created,
        "existing": len(existing_full),
        "sample":   sample,
        "errors":   errors[:20],
        "proj_root": proj_root,
    })


# ── Project folder slug generation ────────────────────────────────────────────
def _make_project_slug(project_name, client_name=None, dt=None):
    """Generate a Dropbox folder slug: YYYY-MM_ClientSlug_ProjectSlug"""
    import re
    from datetime import date as _date
    dt = dt or _date.today()

    def slugify(s, maxlen):
        s = re.sub(r"[^a-zA-Z0-9 ]", "", (s or "").strip())
        return "".join(w.capitalize() for w in s.split())[:maxlen]

    month     = dt.strftime("%Y-%m")
    c_slug    = slugify(client_name or "FP", 20)
    p_slug    = slugify(project_name, 30)
    return f"{month}_{c_slug}_{p_slug}"

def _unique_project_slug(project_name, client_name=None, exclude_id=None):
    """Return a slug guaranteed unique in the project_sheet table."""
    from models import ProjectSheet as _PS
    base = _make_project_slug(project_name, client_name)
    slug = base
    # Check DB for collision
    q = _PS.query.filter(_PS.dropbox_folder == slug)
    if exclude_id:
        q = q.filter(_PS.id != exclude_id)
    if not q.first():
        return slug
    # Fallback: append sequential number
    for n in range(2, 99):
        slug = f"{base}_{n}"
        q = _PS.query.filter(_PS.dropbox_folder == slug)
        if exclude_id:
            q = q.filter(_PS.id != exclude_id)
        if not q.first():
            return slug
    return base  # give up — extremely unlikely


def _send_email(to, subject, body, attachment_bytes=None, attachment_filename=None):
    """Send email — silently no-ops if mail not configured."""
    if not app.config.get('MAIL_USERNAME'):
        return False
    try:
        msg = MailMessage(subject, recipients=[to], body=body)
        if attachment_bytes and attachment_filename:
            msg.attach(attachment_filename, 'application/pdf', attachment_bytes)
        mail.send(msg)
        return True
    except Exception as e:
        logging.warning(f"Email send failed: {e}")
        return False


def _project_notify_recipients(pid, extra_emails=None):
    """Active Super-Admin / Admin users who are ON this project (have a
    ProjectAccess row), plus any explicit extra addresses, de-duped. This is the
    audience for project-update emails. Scoped to Super/Admin for now per
    user request 2026-06-22 ("for now let's just work Super and Admin")."""
    seen = {}
    try:
        rows = (User.query
                .join(ProjectAccess, ProjectAccess.user_id == User.id)
                .filter(ProjectAccess.project_id == pid,
                        User.role.in_(('super_admin', 'admin')),
                        User.is_active == True)
                .all())
        for u in rows:
            if u.email:
                seen[u.email.lower()] = (u.email, u.name or u.email)
    except Exception:
        logging.warning("project notify recipient lookup failed", exc_info=True)
    for e in (extra_emails or []):
        if e and e.lower() not in seen:
            seen[e.lower()] = (e, e)
    return list(seen.values())


def _notify_project_event(pid, subject, body, extra_emails=None):
    """Best-effort email to the project's Super/Admin audience about a
    project-level event (estimate sent / approved / declined / new version).
    Fail-open: a mail problem never breaks the originating action. Returns count
    of messages sent."""
    if not app.config.get('MAIL_USERNAME'):
        return 0
    sent = 0
    for email, _name in _project_notify_recipients(pid, extra_emails=extra_emails):
        try:
            if _send_email(email, subject, body):
                sent += 1
        except Exception:
            logging.warning("project notify send failed for %s", email, exc_info=True)
    return sent


def _send_sms(to_phone, body):
    """Send SMS via Twilio — silently no-ops if not configured."""
    sid   = os.getenv('TWILIO_ACCOUNT_SID', '')
    token = os.getenv('TWILIO_AUTH_TOKEN', '')
    from_num = os.getenv('TWILIO_FROM_NUMBER', '')
    if not sid or not token or not from_num:
        return False
    # Normalize phone: strip everything except digits and leading +
    import re as _re
    digits = _re.sub(r'[^\d+]', '', to_phone.strip())
    if not digits:
        return False
    if not digits.startswith('+'):
        digits = '+1' + digits  # default to US
    try:
        from twilio.rest import Client as _TwilioClient
        _TwilioClient(sid, token).messages.create(body=body, from_=from_num, to=digits)
        return True
    except Exception as e:
        logging.warning(f"SMS send failed: {e}")
        return False


def _generate_callsheet_pdf(send_obj, project_name, date_display, cs_data, crew_rows, locations_today):
    """Generate a PDF of the call sheet using weasyprint. Returns bytes or None."""
    try:
        import weasyprint
        html_str = _render_callsheet_pdf_html(
            send_obj=send_obj,
            project_name=project_name,
            date_display=date_display,
            cs_data=cs_data,
            crew_rows=crew_rows,
            locations_today=locations_today,
        )
        pdf_bytes = weasyprint.HTML(string=html_str, base_url=None).write_pdf()
        return pdf_bytes
    except Exception as e:
        logging.warning(f"PDF generation failed: {e}")
        return None


def _render_callsheet_pdf_html(send_obj, project_name, date_display, cs_data, crew_rows, locations_today):
    """Render a lightweight HTML string suitable for PDF conversion."""
    import html as _html
    esc = _html.escape
    kp  = cs_data.get('key_personnel') or []
    cct = cs_data.get('crew_call_times') or {}
    dn  = cs_data.get('dept_notes') or []
    uc  = cs_data.get('useful_contacts') or []

    def row(label, val):
        if not val:
            return ''
        return f'<tr><td class="lbl">{esc(label)}</td><td>{esc(str(val))}</td></tr>'

    # Build location blocks
    loc_html = ''
    for loc in (locations_today or []):
        loc_html += f'<div class="loc-block"><strong>{esc(loc.name or "")}</strong>'
        if getattr(loc, 'facility_name', None):
            loc_html += f' — {esc(loc.facility_name)}'
        if getattr(loc, 'address', None):
            loc_html += f'<br><span class="sub">{esc(loc.address)}</span>'
        if getattr(loc, 'contact_name', None):
            loc_html += f'<br><span class="sub">Contact: {esc(loc.contact_name)}'
            if getattr(loc, 'contact_phone', None):
                loc_html += f' · {esc(loc.contact_phone)}'
            loc_html += '</span>'
        loc_html += '</div>'

    # Build crew call time rows grouped by section
    section_order = []
    section_rows = {}
    for key, t in cct.items():
        parts = key.split('||', 2)
        sec   = parts[0] if len(parts) > 0 else ''
        role  = parts[1] if len(parts) > 1 else ''
        name  = parts[2] if len(parts) > 2 else ''
        if sec not in section_rows:
            section_order.append(sec)
            section_rows[sec] = []
        section_rows[sec].append((role, name, t))

    crew_html = ''
    for sec in section_order:
        crew_html += f'<tr class="sec-hdr"><td colspan="3">{esc(sec)}</td></tr>'
        for role, name, t in section_rows[sec]:
            crew_html += f'<tr><td>{esc(role)}</td><td>{esc(name)}</td><td class="time">{esc(t)}</td></tr>'

    # Key personnel
    kp_html = ''
    for p in kp:
        if not isinstance(p, dict) or (not p.get('name') and not p.get('role')):
            continue
        kp_html += f'<tr><td>{esc(p.get("role",""))}</td><td>{esc(p.get("name",""))}</td><td>{esc(p.get("phone",""))}</td></tr>'

    # Dept notes
    dnotes_html = ''
    for d in dn:
        if isinstance(d, dict) and d.get('dept') and d.get('note'):
            dnotes_html += f'<div class="dnote"><strong>{esc(d["dept"])}:</strong> {esc(d["note"])}</div>'

    version_label = getattr(send_obj, 'version_label', '') or ''

    return f"""<!DOCTYPE html>
<html><head><meta charset="UTF-8">
<style>
  body {{ font-family: Arial, sans-serif; font-size: 9pt; margin: 0; padding: 0; color: #111; }}
  .page {{ padding: 18px 22px; }}
  h1 {{ font-size: 14pt; margin: 0 0 2px; }}
  .sub-head {{ font-size: 8pt; color: #555; margin-bottom: 10px; }}
  h2 {{ font-size: 10pt; border-bottom: 1px solid #bbb; margin: 12px 0 4px; padding-bottom: 2px; text-transform: uppercase; letter-spacing: .04em; }}
  table {{ width: 100%; border-collapse: collapse; margin-bottom: 8px; }}
  td {{ padding: 2px 6px; vertical-align: top; font-size: 8.5pt; }}
  .lbl {{ color: #555; width: 130px; white-space: nowrap; }}
  .time {{ font-weight: bold; text-align: right; }}
  .sec-hdr td {{ background: #eee; font-weight: bold; font-size: 8pt; padding: 3px 6px; }}
  .loc-block {{ margin-bottom: 8px; font-size: 8.5pt; }}
  .sub {{ color: #555; }}
  .dnote {{ margin-bottom: 4px; font-size: 8.5pt; }}
  .info-table td {{ border-bottom: 1px solid #f0f0f0; }}
  .footer {{ font-size: 7pt; color: #888; margin-top: 16px; border-top: 1px solid #ddd; padding-top: 6px; }}
</style>
</head><body><div class="page">

<h1>{esc(project_name)}</h1>
<div class="sub-head">Call Sheet · {esc(date_display)}{' · ' + esc(version_label) if version_label else ''}</div>

{"<h2>General</h2><table class='info-table'>" + "".join(filter(None, [row('General Crew Call', cs_data.get('general_crew_call','')), row('Est. Wrap', cs_data.get('estimated_wrap_time','')), row('Weather', cs_data.get('weather','')), row('Sunrise', cs_data.get('sunrise','')), row('Sunset', cs_data.get('sunset','')), row('Courtesy Breakfast', cs_data.get('courtesy_breakfast_time','')), row('First Meal', cs_data.get('first_meal_time','')), row('Second Meal', cs_data.get('second_meal_time',''))])) + "</table>" if any([cs_data.get('general_crew_call'), cs_data.get('estimated_wrap_time'), cs_data.get('first_meal_time'), cs_data.get('second_meal_time')]) else ''}

{'<h2>Locations</h2>' + loc_html if loc_html else ''}

{'<h2>Key Contacts</h2><table><tr><td class="lbl">Role</td><td>Name</td><td>Phone</td></tr>' + kp_html + '</table>' if kp_html else ''}

{'<h2>Crew Call Times</h2><table>' + crew_html + '</table>' if crew_html else ''}

{'<h2>Department Notes</h2>' + dnotes_html if dnotes_html else ''}

{'<p>' + esc(cs_data.get('additional_notes','')) + '</p>' if cs_data.get('additional_notes') else ''}

<div class="footer">Sent by Framework Productions · contact@thefp.tv</div>
</div></body></html>"""


