@app.route("/projects/<int:pid>/actuals/link-split", methods=["POST"])
@login_required
def actuals_link_split(pid):
    """Link ONE receipt to MULTIPLE charges as an intentional split. Body:
    {keeper_doc_id, charge_tids:[...], remove_doc_ids:[...]}. Each charge gets
    doc_upload_id=keeper, match_status='confirmed', and a shared split_group;
    the keeper's own doc-source row is removed (it's now backing real charges),
    and any redundant duplicate receipts (the same file uploaded once per line)
    are folded into the keeper. (User 2026-06-16.)"""
    if getattr(current_user, 'role', None) == 'viewer':
        return jsonify({"error": "Forbidden"}), 403
    ProjectSheet.query.get_or_404(pid)
    data = request.get_json(force=True) or {}
    try:
        keeper = int(data.get('keeper_doc_id'))
        tids = [int(t) for t in (data.get('charge_tids') or [])]
    except (TypeError, ValueError):
        return jsonify({"error": "keeper_doc_id and charge_tids required"}), 400
    remove = []
    for x in (data.get('remove_doc_ids') or []):
        try:
            if int(x) != keeper:
                remove.append(int(x))
        except (TypeError, ValueError):
            pass
    if not keeper or len(tids) < 2:
        return jsonify({"error": "Need a receipt and at least two charges to split."}), 400
    doc = DocUpload.query.filter_by(id=keeper, project_id=pid).first()
    if not doc:
        return jsonify({"error": "Receipt not on this project"}), 404
    sg = f"SG-{keeper}"
    linked = 0
    for tid in tids:
        txn = Transaction.query.filter_by(id=tid, project_id=pid).first()
        if not txn:
            continue
        txn.doc_upload_id = keeper
        txn.match_status = 'confirmed'
        txn.split_group = sg
        if not txn.vendor and doc.vendor:
            txn.vendor = doc.vendor
        if txn.source in ('qbo_sync', 'csv_import'):
            txn.source = 'reconciled'
        txn.updated_at = datetime.utcnow()
        linked += 1
    # The keeper's OWN auto-created doc_upload row is now redundant (the receipt
    # is backing real charges) — drop it so it isn't double-counted.
    Transaction.query.filter_by(doc_upload_id=keeper, source='doc_upload').delete(synchronize_session=False)
    # Fold redundant duplicate receipts into the keeper.
    folded = 0
    for rid in remove:
        rdoc = DocUpload.query.filter_by(id=rid, project_id=pid).first()
        if not rdoc:
            continue
        # Any charge still pointing at the dup → repoint to the keeper.
        Transaction.query.filter(Transaction.project_id == pid,
                                 Transaction.doc_upload_id == rid,
                                 Transaction.source != 'doc_upload').update(
            {"doc_upload_id": keeper}, synchronize_session=False)
        Transaction.query.filter_by(doc_upload_id=rid, source='doc_upload').delete(synchronize_session=False)
        rdoc.is_duplicate = True
        rdoc.duplicate_of_id = keeper
        rdoc.status = 'duplicate'
        folded += 1
    db.session.commit()
    try:
        _log_activity(action='update', entity_type='transaction_match', entity_id=keeper,
                      entity_label=f'Split receipt #{keeper}', project_id=pid,
                      note=f'Linked receipt #{keeper} to {linked} charges as a split'
                           + (f'; folded {folded} duplicate receipt(s)' if folded else ''))
    except Exception:
        pass
    return jsonify({"ok": True, "linked": linked, "folded": folded, "split_group": sg})


@app.route("/projects/<int:pid>/actuals/transaction/<int:tid>/mark-not-project", methods=["POST"])
@login_required
def actuals_mark_not_project(pid, tid):
    """Mark a transaction as 'not a project expense' — drops it from
    Actuals rollup but keeps it on the row (greyed) for audit. Like
    the old FPBudgetSync /confirm-suggestion 'Not Project' path."""
    txn = Transaction.query.filter_by(id=tid, project_id=pid).first_or_404()
    _before_npe = {'not_project_expense': bool(txn.not_project_expense),
                   'account_code': txn.account_code,
                   'budget_line_id': txn.budget_line_id}
    txn.not_project_expense = True
    txn.budget_line_id      = None
    txn.account_code        = None
    txn.account_code_name   = None
    txn.match_status        = 'unmatched'
    txn.updated_at          = datetime.utcnow()
    _sync_claim_state(txn)
    db.session.commit()
    try:
        _amt = float(txn.amount or 0)
        _log_activity(
            action='update', entity_type='transaction',
            entity_id=txn.id,
            entity_label=(txn.vendor or txn.note or f'Txn #{txn.id}')[:80],
            project_id=pid,
            before=_before_npe,
            after={'not_project_expense': True, 'account_code': None,
                   'budget_line_id': None},
            note=f'Marked ${_amt:,.2f} as not a project expense')
    except Exception: pass
    return jsonify({"ok": True, "transaction_id": tid})


@app.route("/admin/cross-project-claim-backfill", methods=["GET", "POST"])
@login_required
@super_admin_required
def admin_cross_project_claim_backfill():
    """One-shot: run _sync_claim_state across every already-coded
    transaction in the database so the new fuzzy-match channel
    retroactively claims siblings in other projects.

    User report 2026-05-15: a Lyft $37.93 was coded in Project A but
    still showing in Project B because the pre-fuzzy claim logic only
    matched on qbo_txn_id and Project A's row was doc-only. After
    deploying the fuzzy match, NEW coding actions claim correctly, but
    historical ones don't until we walk the table once.

    GET shows a dry-run preview (how many siblings would get claimed
    without writing anything). POST runs it for real and commits.
    """
    from sqlalchemy import or_ as _or
    # "Coded" for this backfill = any claim signal recognized by
    # _sync_claim_state. As of 2026-05-15 that includes doc_upload_id
    # too (receipt attachment → claim).
    coded_q = (Transaction.query
               .filter(_or(Transaction.budget_line_id.isnot(None),
                           Transaction.account_code.isnot(None),
                           Transaction.not_project_expense == True,
                           Transaction.doc_upload_id.isnot(None)))
               .filter(Transaction.amount.isnot(None),
                       Transaction.txn_date.isnot(None),
                       Transaction.vendor.isnot(None)))
    coded_count = coded_q.count()

    if request.method == "GET":
        # Dry-run preview: iterate but rollback at the end.
        marked = 0
        preview = []
        for t in coded_q.limit(2000).all():
            _before = {
                str(s.id): (s.claimed_by_project_id, bool(s.not_project_expense))
                for s in Transaction.query
                              .filter(Transaction.project_id != t.project_id,
                                      Transaction.amount == t.amount,
                                      Transaction.txn_date == t.txn_date)
                              .limit(20).all()
            }
            _sync_claim_state(t)
            for s in db.session.dirty:
                if not isinstance(s, Transaction):
                    continue
                _b = _before.get(str(s.id))
                if _b is None:
                    continue
                if _b != (s.claimed_by_project_id, bool(s.not_project_expense)):
                    marked += 1
                    if len(preview) < 25:
                        preview.append({
                            'sibling_id':   s.id,
                            'sibling_proj': s.project_id,
                            'vendor':       s.vendor,
                            'amount':       float(s.amount or 0),
                            'date':         s.txn_date,
                            'claimed_by':   s.claimed_by_project_id,
                            'not_project':  bool(s.not_project_expense),
                        })
        db.session.rollback()
        return jsonify({
            'ok': True,
            'mode': 'dry-run',
            'coded_transactions': coded_count,
            'siblings_would_claim': marked,
            'sample': preview,
            'next': 'POST to this URL to apply.',
        })

    # POST: actually run + commit.
    marked = 0
    errors = 0
    for t in coded_q.all():
        try:
            _sync_claim_state(t)
            for s in list(db.session.dirty):
                if isinstance(s, Transaction):
                    marked += 1
        except Exception as e:
            errors += 1
            logging.warning("[claim-backfill] failed on txn #%s: %s", t.id, e)
    db.session.commit()
    return jsonify({
        'ok': True,
        'mode': 'committed',
        'coded_transactions': coded_count,
        'siblings_marked_dirty': marked,
        'errors': errors,
    })


@app.route("/projects/<int:pid>/actuals/line/<int:lid>/transactions.json", methods=["GET"])
@login_required
def actuals_line_transactions(pid, lid):
    """Every transaction coded to a single budget line, for the per-line
    Reconcile panel (large thumbnail tiles + merge / unlink / unmatch / uncode).
    (User 2026-06-26 — "see a single budget line and all things coded to it".)"""
    ProjectSheet.query.get_or_404(pid)
    line = (BudgetLine.query
            .join(Budget, Budget.id == BudgetLine.budget_id)
            .filter(BudgetLine.id == lid, Budget.project_id == pid)
            .first_or_404())
    # Charges are coded to whichever budget's line id (Working vs Actual), so
    # resolve sibling lines across this project that represent the SAME line
    # (same section + description). Lets the panel open from any budget view.
    _sib_q = (BudgetLine.query
              .join(Budget, Budget.id == BudgetLine.budget_id)
              .filter(Budget.project_id == pid,
                      BudgetLine.account_code == line.account_code))
    if line.description:
        _sib_q = _sib_q.filter(BudgetLine.description == line.description)
    else:
        _sib_q = _sib_q.filter(BudgetLine.id == line.id)
    _sib_ids = [l.id for l in _sib_q.all()] or [line.id]
    txns = (Transaction.query
            .filter(Transaction.project_id == pid,
                    Transaction.budget_line_id.in_(_sib_ids))
            .order_by(Transaction.txn_date.desc().nullslast(), Transaction.id.desc())
            .all())
    out = []
    for t in txns:
        doc = DocUpload.query.get(t.doc_upload_id) if t.doc_upload_id else None
        _dt = t.txn_date
        out.append({
            "id": t.id,
            "vendor": t.vendor,
            "amount": float(t.amount) if t.amount is not None else None,
            "date": (_dt.isoformat() if hasattr(_dt, 'isoformat') else _dt),
            "source": t.source,
            "match_status": t.match_status,
            "is_expense": bool(t.is_expense),
            "doc_upload_id": t.doc_upload_id,
            "has_image": bool(doc and doc.content_type and doc.content_type.startswith('image/')),
            "doc_category": (doc.category if doc else None),
            "doc_filename": (doc.filed_filename or doc.original_filename) if doc else None,
            "qbo_txn_id": t.qbo_txn_id,
            "account_code": t.account_code,
            "note": t.note,
        })
    return jsonify({
        "ok": True,
        "line": {"id": line.id, "code": line.account_code,
                 "name": (line.description or line.account_name or ''),
                 "section_name": (_section_name(line.account_code) or line.account_name or '')},
        "transactions": out,
    })


@app.route("/projects/<int:pid>/actuals/transaction/merge", methods=["POST"])
@login_required
def actuals_merge_transactions(pid):
    """Manually reconcile a pair of transactions that are really the same
    expense. Most common case: a receipt was uploaded *after* the QBO
    charge synced, so the receipt-first reconciliation (qbo_sync.py's
    _find_unreconciled_doc_match — runs only during sync) didn't catch
    them, and the user ends up with two rows for the same $97.75 charge.

    Body: { "tids": [<id_a>, <id_b>] } — exactly two transaction ids.

    Canonical-row priority (winner keeps its id, the other is deleted):
      1. Has qbo_txn_id (QBO charge is the canonical "money out" record)
      2. Has account_code set (already user-coded)
      3. Has budget_line_id set
      4. Lower id (older)

    Then we transfer onto the canonical, only filling blanks (never
    overwriting work already there):
      - doc_upload_id   (the receipt — always wins from the other row
                         if canonical lacks one; this is the whole point)
      - budget_line_id  (only if canonical has none)
      - account_code / account_code_name (only if canonical has none)
      - note            (concatenated if both have notes)

    Result: canonical row gets source='reconciled', match_status='confirmed'.
    The losing row is deleted (its FK row count is small — no children).

    Both rows must belong to the same project (pid). User must have at
    least editor role on the project.
    """
    _require_project_role(pid, 'editor')
    ProjectSheet.query.get_or_404(pid)
    data = request.get_json(force=True) or {}
    tids = data.get("tids") or []
    if not isinstance(tids, list) or len(tids) != 2:
        return jsonify({"error": "tids must be a list of exactly 2 transaction ids"}), 400
    try:
        tid_a, tid_b = int(tids[0]), int(tids[1])
    except (TypeError, ValueError):
        return jsonify({"error": "tids must be integers"}), 400
    if tid_a == tid_b:
        return jsonify({"error": "Cannot merge a transaction with itself"}), 400

    a = Transaction.query.filter_by(id=tid_a, project_id=pid).first()
    b = Transaction.query.filter_by(id=tid_b, project_id=pid).first()
    if not a or not b:
        return jsonify({"error": "Both transactions must exist on this project"}), 404

    # Pick canonical — the one we keep.
    def _canon_priority(t):
        # Lower tuple wins.
        return (
            0 if t.qbo_txn_id else 1,
            0 if t.account_code else 1,
            0 if t.budget_line_id else 1,
            t.id,
        )
    if _canon_priority(a) <= _canon_priority(b):
        canon, loser = a, b
    else:
        canon, loser = b, a

    # Refuse to merge two DISTINCT QuickBooks charges — deleting the loser would
    # destroy a real bank record AND, since its qbo_txn_id would no longer exist
    # in any row, the next sync would re-import it as a fresh duplicate. (Code
    # review 2026-06-04.)
    if (a.qbo_txn_id and b.qbo_txn_id and a.qbo_txn_id != b.qbo_txn_id):
        return jsonify({"error": "Both rows are distinct QuickBooks charges "
                                 "(different qbo_txn_id). Merging would delete a "
                                 "real bank record — unmatch one first if it's wrong."}), 400

    _before = {
        'canon_id':           canon.id,
        'canon_source':       canon.source,
        'canon_doc_upload_id': canon.doc_upload_id,
        'canon_budget_line_id': canon.budget_line_id,
        'canon_account_code': canon.account_code,
        'canon_qbo_txn_id':   canon.qbo_txn_id,
        'loser_id':           loser.id,
        'loser_source':       loser.source,
        'loser_doc_upload_id': loser.doc_upload_id,
        'loser_budget_line_id': loser.budget_line_id,
        'loser_account_code': loser.account_code,
        'loser_qbo_txn_id':   loser.qbo_txn_id,
    }

    # ── Transfer fields onto canonical (only fill blanks) ──────────────
    # The receipt is the whole point of the manual merge, so doc_upload_id
    # always comes over if canonical lacks one. If both rows have a doc
    # (rare — would mean two receipts for the same charge) we keep
    # canonical's and note the conflict.
    transferred = []
    doc_conflict = False
    if loser.doc_upload_id and not canon.doc_upload_id:
        canon.doc_upload_id = loser.doc_upload_id
        transferred.append('doc_upload_id')
    elif loser.doc_upload_id and canon.doc_upload_id and loser.doc_upload_id != canon.doc_upload_id:
        doc_conflict = True
    if loser.budget_line_id and not canon.budget_line_id:
        canon.budget_line_id = loser.budget_line_id
        transferred.append('budget_line_id')
    if loser.account_code and not canon.account_code:
        canon.account_code      = loser.account_code
        canon.account_code_name = loser.account_code_name
        transferred.append('account_code')
    # Notes: concatenate distinct ones so user-typed context isn't lost.
    if loser.note and (loser.note or '').strip() != (canon.note or '').strip():
        if canon.note:
            canon.note = f"{canon.note}\n[merged from #{loser.id}] {loser.note}"
        else:
            canon.note = loser.note
        transferred.append('note')

    # Vendor: prefer the receipt-side vendor when one of the two rows is
    # doc-only (its OCR'd value is human-readable — "Amazon", "Lyft"
    # vs QBO's processor noise "AMAZON MKTPL*BJ3NU6KN0"). Only swap if
    # the canonical row currently holds the QBO-side string AND the
    # other row carries the doc-side string. Same rationale as the
    # reconciliation path in qbo_sync.py (2026-05-15).
    if (loser.doc_upload_id and not canon.doc_upload_id
            and loser.vendor and loser.vendor != canon.vendor):
        canon.vendor = loser.vendor
        transferred.append('vendor')

    # ── Promote canonical to 'reconciled' / 'confirmed' ────────────────
    # Keep qbo_txn_id intact (we only transfer onto canonical when it
    # lacks one — see below).
    if loser.qbo_txn_id and not canon.qbo_txn_id:
        canon.qbo_txn_id     = loser.qbo_txn_id
        canon.qbo_txn_type   = loser.qbo_txn_type
        canon.qbo_account_id = loser.qbo_account_id
        canon.qbo_category   = loser.qbo_category
        transferred.append('qbo_txn_id')

    canon.source       = 'reconciled'
    canon.match_status = 'confirmed' if canon.budget_line_id or canon.account_code else canon.match_status
    canon.updated_at   = datetime.utcnow()

    # Clear FK on loser BEFORE delete so cascade-on-delete behavior is
    # predictable (we don't want the loser's doc_upload_id row touched —
    # the DocUpload itself stays, just transferred to canonical).
    loser.doc_upload_id   = None
    loser.budget_line_id  = None

    # Reparent the loser's invoice-split children onto the canonical row before
    # deleting it — otherwise the parent_transaction_id FK blocks the delete on
    # Postgres (500 mid-merge) / orphans them on SQLite. (Code review 2026-06-04.)
    _reparented = (Transaction.query
                   .filter(Transaction.parent_transaction_id == loser.id)
                   .update({"parent_transaction_id": canon.id},
                           synchronize_session=False))
    if _reparented:
        transferred.append(f'{_reparented}_child_split(s)_reparented')

    _loser_amt    = float(loser.amount or 0)
    _loser_vendor = loser.vendor or ''
    _loser_id     = loser.id

    db.session.delete(loser)
    db.session.commit()

    # Activity log: one entry on the surviving row recording what was
    # merged in. Helps the audit trail explain "why is this txn marked
    # 'reconciled' even though we didn't run a QBO sync?".
    try:
        _log_activity(
            action='update', entity_type='transaction',
            entity_id=canon.id,
            entity_label=(canon.vendor or canon.note or f'Txn #{canon.id}')[:80],
            project_id=pid,
            before=_before,
            after={'canon_id': canon.id, 'source': canon.source,
                   'doc_upload_id': canon.doc_upload_id,
                   'budget_line_id': canon.budget_line_id,
                   'account_code': canon.account_code,
                   'qbo_txn_id': canon.qbo_txn_id,
                   'transferred': transferred,
                   'deleted_loser_id': _loser_id},
            note=f'Manually merged duplicate ${_loser_amt:,.2f} {_loser_vendor} '
                 f'(loser #{_loser_id}) into this row')
    except Exception: pass

    return jsonify({
        "ok": True,
        "canonical_id": canon.id,
        "deleted_id":   _loser_id,
        "transferred":  transferred,
        "doc_conflict": doc_conflict,
    })


# ── AI auto-coding (advisory) — categorize uncoded charges ────────────────
# ai_layer.categorize() proposes a COA section; we store it on the txn as a
# suggestion ONLY. The user accepts via the existing set-coa path. A learned
# vendor→code mapping (VendorCategoryMap) short-circuits the model. Everything
# here is fail-open: a model/key problem must never block uploads or the page.
def _ai_coa_taxonomy():
    from budget_calc import FP_COA_SECTIONS
    return [{"id": str(code), "label": name} for code, name in FP_COA_SECTIONS]


def _ai_past_corrections(pid, limit=200):
    """Learned vendor→code mappings (this project first, then global) as the
    LLM's PAST_CORRECTIONS hints."""
    from models import VendorCategoryMap
    from budget_calc import FP_COA_NAMES
    rows = (VendorCategoryMap.query
            .filter(db.or_(VendorCategoryMap.project_id == pid,
                           VendorCategoryMap.project_id.is_(None)),
                    VendorCategoryMap.account_code.isnot(None))
            .order_by(VendorCategoryMap.confirm_count.desc())
            .limit(limit).all())
    return [{"vendor": r.vendor_canonical, "account_code": str(r.account_code),
             "account_code_name": FP_COA_NAMES.get(r.account_code, ""),
             "confirm_count": r.confirm_count or 1} for r in rows]


def _ai_log_event(pid, doc_id, feature, provider, model, req, resp, latency):
    """Queue an AiEvent audit row on the session (caller commits). Fail-soft."""
    try:
        import json as _j
        from models import AiEvent
        db.session.add(AiEvent(
            project_id=pid, doc_upload_id=doc_id, feature=feature,
            provider=provider, model=model,
            request_json=_j.dumps(req, default=str)[:8000],
            response_json=_j.dumps(resp, default=str)[:8000], latency_ms=latency))
    except Exception:
        pass


def _ai_suggest_code_for_txn(txn, taxonomy=None, past=None, force=False):
    """Advisory COA suggestion for ONE uncoded charge. Memory-first (a learned
    vendor mapping wins, no model call), else ai_layer.categorize(). Writes
    ai_suggested_* onto txn (caller commits). Returns the suggestion dict or
    None. Never raises."""
    if txn is None or txn.account_code is not None or txn.not_project_expense:
        return None
    if txn.ai_suggested_code is not None and not force:
        return None
    from budget_calc import FP_COA_NAMES
    from actuals import canon_vendor
    import ai_layer, time as _t, json as _j
    pid = txn.project_id
    vendor = txn.vendor or ''
    doc_id = getattr(txn, 'doc_upload_id', None)

    # 1) Memory-first: a confirmed vendor mapping short-circuits the LLM.
    cv = canon_vendor(vendor)
    if cv:
        from models import VendorCategoryMap
        m = (VendorCategoryMap.query
             .filter(VendorCategoryMap.vendor_canonical == cv,
                     VendorCategoryMap.account_code.isnot(None),
                     db.or_(VendorCategoryMap.project_id == pid,
                            VendorCategoryMap.project_id.is_(None)))
             .order_by(VendorCategoryMap.project_id.isnot(None).desc(),
                       VendorCategoryMap.confirm_count.desc())
             .first())
        if m and m.account_code in FP_COA_NAMES:
            txn.ai_suggested_code = m.account_code
            txn.ai_suggested_code_name = (FP_COA_NAMES.get(m.account_code, '') or '')[:100]
            txn.ai_code_confidence = 0.96
            txn.ai_code_reason = (f'Matches how "{vendor}" was coded before')[:300]
            _ai_log_event(pid, doc_id, 'categorize', 'memory', None,
                          {"vendor": vendor, "canon": cv},
                          {"account_code": m.account_code, "via": "vendor_map"}, 0)
            return {"code": m.account_code, "name": txn.ai_suggested_code_name,
                    "confidence": 0.96, "source": "memory"}

    # 2) Ask the model.
    if taxonomy is None:
        taxonomy = _ai_coa_taxonomy()
    if past is None:
        past = _ai_past_corrections(pid)
    vd = {}
    doc = db.session.get(DocUpload, doc_id) if doc_id else None
    if doc is not None and doc.veryfi_data:
        try:
            vd = doc.veryfi_data if isinstance(doc.veryfi_data, dict) else _j.loads(doc.veryfi_data)
        except Exception:
            vd = {}
    document = {
        "vendor": vendor,
        "amount": float(txn.amount) if txn.amount is not None else None,
        "date": txn.txn_date,
        "veryfi_category": (doc.veryfi_category if doc else None) or vd.get("category"),
        "qbo_category": getattr(txn, 'qbo_category', None),
        "line_items": [li.get("description") for li in (vd.get("line_items") or [])
                       if isinstance(li, dict) and li.get("description")][:20],
    }
    payload = {"taxonomy": taxonomy, "document": document, "past_corrections": past}
    t0 = _t.time()
    res = ai_layer.categorize(payload)
    latency = int((_t.time() - t0) * 1000)
    _ai_log_event(pid, doc_id, 'categorize', res.get('_provider'), res.get('_model'),
                  payload, res, latency)
    code = None
    try:
        cid = res.get("document_category_id")
        if cid is not None and str(cid).strip().isdigit():
            code = int(str(cid).strip())
    except Exception:
        code = None
    try:
        conf = float(res.get("confidence") or 0)
    except (TypeError, ValueError):
        conf = 0.0
    if code is None or code not in FP_COA_NAMES or conf < 0.45:
        return None
    txn.ai_suggested_code = code
    txn.ai_suggested_code_name = (FP_COA_NAMES.get(code, '') or '')[:100]
    txn.ai_code_confidence = round(conf, 3)
    txn.ai_code_reason = (res.get("reasoning") or '')[:300]
    return {"code": code, "name": txn.ai_suggested_code_name,
            "confidence": conf, "source": res.get('_provider')}


# ── AI data cleanup + review-queue (AnomalyFlag) ──────────────────────────
def _flag_anomaly(pid, kind, severity='medium', title=None, explanation=None,
                  confidence=None, doc_upload_id=None, transaction_id=None,
                  payload=None, dedup_key=None):
    """Queue an AnomalyFlag review-queue row (caller commits). Idempotent on
    dedup_key: if an UNRESOLVED flag with the same key exists, refresh it in
    place instead of inserting a duplicate. Returns the flag or None. Fail-soft."""
    try:
        import json as _j
        from models import AnomalyFlag
        existing = None
        if dedup_key:
            prior = (AnomalyFlag.query
                     .filter_by(project_id=pid, dedup_key=dedup_key)
                     .order_by(AnomalyFlag.id.desc()).first())
            if prior is not None:
                if prior.resolved:
                    # User already dismissed this exact thing → don't nag again.
                    if (prior.resolution or '') == 'dismissed':
                        return None
                    # Resolved by a fix but it recurs → fall through to a new flag.
                else:
                    existing = prior
        pj = _j.dumps(payload, default=str)[:8000] if payload is not None else None
        if existing:
            existing.title = title or existing.title
            existing.explanation = explanation or existing.explanation
            existing.severity = severity or existing.severity
            if confidence is not None:
                existing.confidence = confidence
            if pj is not None:
                existing.payload_json = pj
            if transaction_id is not None:
                existing.transaction_id = transaction_id
            return existing
        flag = AnomalyFlag(project_id=pid, type=kind, severity=severity, title=title,
                           explanation=explanation, confidence=confidence,
                           doc_upload_id=doc_upload_id, transaction_id=transaction_id,
                           payload_json=pj, dedup_key=dedup_key, resolved=False)
        db.session.add(flag)
        return flag
    except Exception as e:
        logging.warning(f"[anomaly] flag failed ({kind}): {e}")
        return None


def _doc_image_temp_link(doc):
    """Short-lived Dropbox link to a doc's image, for the vision model to read.
    Returns a URL or None. Fail-soft."""
    path = getattr(doc, 'filed_dropbox_path', None) or getattr(doc, 'source_archive_path', None)
    if not path:
        return None
    try:
        ops_prefix = (_DBX_OPS_ROOT or "").rstrip("/") if _DBX_NAMESPACE_ID else ""
        norm = path
        if ops_prefix and norm.startswith(ops_prefix + "/"):
            norm = norm[len(ops_prefix):]
        dbx = _dbx_client()
        for p in ((norm, path) if norm != path else (norm,)):
            try:
                return dbx.files_get_temporary_link(p).link
            except Exception:
                continue
    except Exception as e:
        logging.warning(f"[ai-clean] temp link failed for doc #{getattr(doc,'id','?')}: {e}")
    return None


def _ai_known_vendors(pid, limit=80):
    """Clean vendor names already used in this project (from VendorAlias) — the
    consistency hint for clean_document so the same merchant always normalizes
    the same way."""
    names, seen = [], set()
    try:
        from models import VendorAlias
        for r in (VendorAlias.query
                  .filter(db.or_(VendorAlias.project_id == pid,
                                 VendorAlias.project_id.is_(None)))
                  .order_by(VendorAlias.confirm_count.desc()).limit(limit).all()):
            k = (r.clean_name or '').strip().lower()
            if k and k not in seen:
                seen.add(k)
                names.append(r.clean_name.strip())
    except Exception:
        pass
    return names[:limit]


def _ai_clean_document(upload, known=None, force=False):
    """Advisory OCR cleanup for ONE DocUpload: normalize the vendor name and
    flag bad extractions. Memory-first (a learned alias short-circuits the LLM).
    Auto-applies a clean vendor at >=0.70 confidence; below that it queues a
    vendor_cleanup review-flag. Mirrors the clean name onto linked transactions.
    Raw OCR is preserved in veryfi_data. Stamps ai_cleaned_at so batches drain.
    Caller commits. Fail-open: never raises."""
    if upload is None:
        return None
    if getattr(upload, 'ai_cleaned_at', None) is not None and not force:
        return None
    import ai_layer, time as _t, json as _j
    from actuals import apply_vendor_alias_lookup, record_vendor_alias
    from models import Transaction
    pid = upload.project_id
    raw = (upload.vendor or '').strip()
    result = {"applied": False, "flagged": False, "clean_vendor": None}

    def _mirror_vendor(clean):
        for tx in Transaction.query.filter_by(doc_upload_id=upload.id).all():
            tx.vendor = clean[:300]

    # 1) Memory-first: a learned alias wins, no model call.
    if raw:
        alias = apply_vendor_alias_lookup(pid, raw)
        if alias and alias.strip().lower() != raw.lower():
            upload.vendor = alias[:200]
            _mirror_vendor(alias)
            record_vendor_alias(pid, raw, alias)
            upload.ai_cleaned_at = datetime.utcnow()
            _ai_log_event(pid, upload.id, 'clean', 'memory', None,
                          {"raw_vendor": raw}, {"clean_vendor": alias, "via": "alias"}, 0)
            result.update(applied=True, clean_vendor=alias)
            return result

    # 2) Ask the model.
    if known is None:
        known = _ai_known_vendors(pid)
    vd = {}
    if upload.veryfi_data:
        try:
            vd = upload.veryfi_data if isinstance(upload.veryfi_data, dict) else _j.loads(upload.veryfi_data)
        except Exception:
            vd = {}
    document = {
        "raw_vendor": raw,
        "amount": float(upload.amount) if upload.amount is not None else None,
        "date": upload.doc_date.isoformat() if upload.doc_date else None,
        "veryfi_category": upload.veryfi_category or vd.get("category"),
        "doc_type": upload.category,
        "line_items": [li.get("description") for li in (vd.get("line_items") or [])
                       if isinstance(li, dict) and li.get("description")][:20],
    }
    payload = {"document": document, "known_vendors": known}
    # On LOW-confidence image docs, attach the actual receipt image so the model
    # reads it directly (vision) instead of trusting the shaky OCR text. PDFs and
    # high-confidence docs stay text-only. (User 2026-06-18.)
    image_url = None
    try:
        ct = (upload.content_type or '').lower()
        conf = upload.confidence
        low_conf = (conf is None) or (float(conf) < 70)
        if ct.startswith('image/') and low_conf:
            image_url = _doc_image_temp_link(upload)
    except Exception:
        image_url = None
    t0 = _t.time()
    res = ai_layer.clean_document(payload, image_url=image_url)
    latency = int((_t.time() - t0) * 1000)
    _ai_log_event(pid, upload.id, 'clean', res.get('_provider'), res.get('_model'),
                  payload, res, latency)

    clean = (res.get("clean_vendor") or '').strip()
    try:
        vconf = float(res.get("vendor_confidence") or 0)
    except (TypeError, ValueError):
        vconf = 0.0
    try:
        oconf = float(res.get("overall_confidence") or 0)
    except (TypeError, ValueError):
        oconf = 0.0
    differs = bool(clean) and clean.lower() != raw.lower()

    if clean and differs and vconf >= 0.80:
        upload.vendor = clean[:200]
        _mirror_vendor(clean)
        record_vendor_alias(pid, raw, clean)
        result.update(applied=True, clean_vendor=clean)
    elif clean and differs and vconf > 0:
        _flag_anomaly(pid, 'vendor_cleanup', severity='low',
                      title='Confirm vendor name',
                      explanation=(f'OCR read the vendor as "{raw or "(blank)"}". '
                                   f'AI suggests "{clean}" ({int(vconf*100)}% confident).'),
                      confidence=round(vconf, 3), doc_upload_id=upload.id,
                      payload={"raw": raw, "suggested": clean, "confidence": vconf},
                      dedup_key=f'vendor_cleanup:{upload.id}')
        result["flagged"] = True

    # Data sanity (amount / date) issues.
    if (res.get("amount_ok") is False) or (res.get("date_ok") is False):
        issues = res.get("issues") or []
        notes = '; '.join(i.get("note", "") for i in issues
                          if isinstance(i, dict) and i.get("note"))[:400]
        _flag_anomaly(pid, 'data_issue', severity='medium',
                      title='Check extracted data',
                      explanation=(notes or 'AI flagged the amount or date as possibly wrong.'),
                      confidence=round(oconf, 3), doc_upload_id=upload.id,
                      payload={"amount_ok": res.get("amount_ok"), "date_ok": res.get("date_ok"),
                               "suggested_amount": res.get("suggested_amount"),
                               "suggested_date": res.get("suggested_date"), "issues": issues},
                      dedup_key=f'data_issue:{upload.id}')
        result["flagged"] = True

    upload.ai_cleaned_at = datetime.utcnow()
    return result


def _ai_clean_transaction(txn, known=None, force=False):
    """Advisory vendor cleanup for ONE charge (CSV/QBO/manual with no receipt).
    Mirror of _ai_clean_document for the Actuals side: memory-first via
    VendorAlias, else clean_document AI; auto-applies a clean vendor at >=0.70,
    else queues a vendor_cleanup review-flag (keyed to the txn). Stamps
    ai_cleaned_at so batches drain. Caller commits. Fail-open: never raises."""
    if txn is None:
        return None
    if getattr(txn, 'ai_cleaned_at', None) is not None and not force:
        return None
    import ai_layer, time as _t, json as _j
    from actuals import apply_vendor_alias_lookup, record_vendor_alias
    pid = txn.project_id
    raw = (txn.vendor or '').strip()
    result = {"applied": False, "flagged": False, "clean_vendor": None}
    if not raw:
        txn.ai_cleaned_at = datetime.utcnow()
        return result

    # 1) Memory-first: a learned alias wins, no model call.
    alias = apply_vendor_alias_lookup(pid, raw)
    if alias and alias.strip().lower() != raw.lower():
        txn.vendor = alias[:300]
        record_vendor_alias(pid, raw, alias)
        txn.ai_cleaned_at = datetime.utcnow()
        _ai_log_event(pid, None, 'clean', 'memory', None,
                      {"raw_vendor": raw, "tid": txn.id},
                      {"clean_vendor": alias, "via": "alias"}, 0)
        result.update(applied=True, clean_vendor=alias)
        return result

    # 2) Ask the model.
    if known is None:
        known = _ai_known_vendors(pid)
    document = {
        "raw_vendor": raw,
        "amount": float(txn.amount) if txn.amount is not None else None,
        "date": txn.txn_date,
        "veryfi_category": getattr(txn, 'qbo_category', None),
        "doc_type": "bank/card charge",
        "line_items": [],
    }
    payload = {"document": document, "known_vendors": known}
    t0 = _t.time()
    res = ai_layer.clean_document(payload)
    _ai_log_event(pid, None, 'clean', res.get('_provider'), res.get('_model'),
                  payload, res, int((_t.time() - t0) * 1000))
    clean = (res.get("clean_vendor") or '').strip()
    try:
        vconf = float(res.get("vendor_confidence") or 0)
    except (TypeError, ValueError):
        vconf = 0.0
    differs = bool(clean) and clean.lower() != raw.lower()
    if clean and differs and vconf >= 0.80:
        txn.vendor = clean[:300]
        record_vendor_alias(pid, raw, clean)
        result.update(applied=True, clean_vendor=clean)
    elif clean and differs and vconf > 0:
        _flag_anomaly(pid, 'vendor_cleanup', severity='low',
                      title='Confirm vendor name',
                      explanation=(f'Charge vendor reads "{raw}". '
                                   f'AI suggests "{clean}" ({int(vconf*100)}% confident).'),
                      confidence=round(vconf, 3), transaction_id=txn.id,
                      payload={"raw": raw, "suggested": clean, "confidence": vconf,
                               "transaction_id": txn.id},
                      dedup_key=f'vendor_cleanup_txn:{txn.id}')
        result["flagged"] = True
    txn.ai_cleaned_at = datetime.utcnow()
    return result


_TRAVEL_VENDOR_HINTS = (
    'airline', 'airways', 'air lines', 'jetblue', 'delta', 'united', 'american air',
    'southwest', 'alaska air', 'spirit', 'frontier', 'lufthansa', 'british a', 'klm',
    'air canada', 'aer lingus', 'emirates',
    'hotel', 'inn', 'motel', 'suites', 'resort', 'lodging', 'marriott', 'hilton',
    'hyatt', 'sheraton', 'westin', 'airbnb', 'expedia', 'booking.com', 'hampton',
    'courtyard', 'residence inn', 'holiday inn', 'ritz', 'four seasons',
    'enterprise rent', 'hertz', 'avis', 'budget rent', 'national car', 'alamo',
    'rental car', 'car rental', 'zipcar',
)


def _looks_like_travel(upload):
    """Heuristic gate for auto travel-extraction: is this doc plausibly a hotel,
    flight, or car-rental reservation? Category first, then vendor keywords."""
    if upload is None:
        return False
    cat = ((upload.category or '') + ' ' + (upload.veryfi_category or '')).lower()
    if any(k in cat for k in ('hotel', 'airline', 'flight', 'travel', 'car_rental',
                              'car rental', 'lodging', 'airfare')):
        return True
    v = (upload.vendor or '').lower()
    return bool(v) and any(h in v for h in _TRAVEL_VENDOR_HINTS)


def _travel_assignable_people(pid):
    """The crew people a travel doc can be assigned to: every crew-assigned cell
    (labor line, instance) on the project's current Working (else Estimated)
    budget. Returns (people_list, budget_id). Shared by the picker endpoint and
    the auto traveler→person matcher. (User 2026-06-26.)"""
    from actuals import get_current_working_budget, get_current_estimated_budget
    b = get_current_working_budget(pid) or get_current_estimated_budget(pid)
    if not b:
        return [], None
    all_lines = BudgetLine.query.filter_by(budget_id=b.id).all()
    line_by_id = {ln.id: ln for ln in all_lines}
    cas = CrewAssignment.query.filter(
        CrewAssignment.budget_line_id.in_([ln.id for ln in all_lines if ln.is_labor])).all()
    ca_by_key = {(ca.budget_line_id, ca.instance or 1): ca for ca in cas}
    people = []
    for (lid, inst), ca in ca_by_key.items():
        ln = line_by_id.get(lid)
        if not ln:
            continue
        role, person = _resolve_person_for_cell(ln, inst, ca_by_key)
        if not person:
            continue
        people.append({"line_id": lid, "instance": inst, "person": person,
                       "role": role or '', "crew_member_id": getattr(ca, 'crew_member_id', None)})
    people.sort(key=lambda p: (p["person"] or '').lower())
    return people, b.id


def _norm_name_tokens(s):
    import re as _re
    return set(t for t in _re.sub(r'[^a-z ]', ' ', (s or '').lower()).split() if len(t) > 1)


def _match_traveler_to_person(pid, traveler_name):
    """Fuzzy-match an extracted traveler/guest name to one of the project's
    assignable crew. Returns the matched person dict (+ match_score, bid) or None.
    Token-overlap based, so 'ROE/ELIZABETH', 'Elizabeth J Roe' and 'Elizabeth Roe'
    all match the crew member 'Elizabeth Roe'. (User 2026-06-26.)"""
    tnorm = _norm_name_tokens(traveler_name)
    if not tnorm:
        return None
    people, bid = _travel_assignable_people(pid)
    best, best_score = None, 0.0
    for p in people:
        pnorm = _norm_name_tokens(p.get('person'))
        if not pnorm:
            continue
        inter = tnorm & pnorm
        if not inter:
            continue
        score = len(inter) / max(1, len(tnorm | pnorm))
        # Full containment of either name (e.g. "Elizabeth Roe" ⊆ "Elizabeth Joy
        # Roe") is a strong signal even when middle names differ.
        if inter == tnorm or inter == pnorm:
            score = max(score, 0.9)
        if score > best_score:
            best, best_score = p, score
    if best is not None:
        bnorm = _norm_name_tokens(best.get('person'))
        strong = (tnorm & bnorm == tnorm) or (tnorm & bnorm == bnorm) or len(tnorm & bnorm) >= 2
        if strong and best_score >= 0.45:
            return {**best, "match_score": round(best_score, 2), "bid": bid}
    return None


def _ai_extract_travel(upload, force=False):
    """Advisory travel-reservation extraction for ONE DocUpload. Reads the doc
    (OCR text + image when available) via ai_layer.extract_travel and stores the
    structured result in upload.travel_json — a SUGGESTION the user later applies
    to a person + travel day. Stamps travel_extracted_at. Caller commits.
    Fail-open: never raises. (User 2026-06-22.)"""
    if upload is None:
        return None
    if getattr(upload, 'travel_extracted_at', None) is not None and not force:
        try:
            return json.loads(upload.travel_json) if upload.travel_json else None
        except Exception:
            return None
    import ai_layer, time as _t, json as _j
    pid = upload.project_id
    vd = {}
    if upload.veryfi_data:
        try:
            vd = upload.veryfi_data if isinstance(upload.veryfi_data, dict) else _j.loads(upload.veryfi_data)
        except Exception:
            vd = {}
    document = {
        "vendor": (upload.vendor or '').strip(),
        "amount": float(upload.amount) if upload.amount is not None else None,
        "date": upload.doc_date.isoformat() if upload.doc_date else None,
        "doc_number": upload.doc_number or None,
        "veryfi_category": upload.veryfi_category or vd.get("category"),
        "doc_type": upload.category,
        "ocr_text": (vd.get("ocr_text") or vd.get("text") or '')[:6000],
        "line_items": [li.get("description") for li in (vd.get("line_items") or [])
                       if isinstance(li, dict) and li.get("description")][:40],
    }
    payload = {"document": document}
    image_url = None
    try:
        if (upload.content_type or '').lower().startswith('image/'):
            image_url = _doc_image_temp_link(upload)
    except Exception:
        image_url = None
    t0 = _t.time()
    res = ai_layer.extract_travel(payload, image_url=image_url)
    latency = int((_t.time() - t0) * 1000)
    _ai_log_event(pid, upload.id, 'travel', res.get('_provider'), res.get('_model'),
                  payload, res, latency)
    keep = {k: v for k, v in (res or {}).items() if not str(k).startswith('_')}
    # Auto-match the traveler/guest name to an assigned crew person so the Travel
    # panel can pre-select them, and link the doc to that person's packet if it
    # isn't already assigned. (User 2026-06-26 — "look through the assigned
    # people for a match and assign it to that person".)
    try:
        match = _match_traveler_to_person(pid, keep.get('traveler_name'))
        if match:
            keep['matched_person'] = match
            _cmid = match.get('crew_member_id')
            if _cmid and not getattr(upload, 'crew_member_id', None):
                upload.crew_member_id = _cmid
    except Exception as _tme:
        logging.warning("[travel] traveler→person match failed for #%s: %s", upload.id, _tme)
    upload.travel_json = _j.dumps(keep)
    upload.travel_extracted_at = datetime.utcnow()
    return keep


@app.route("/docs/upload/<int:uid>/extract-travel", methods=["POST"])
@login_required
def docs_extract_travel(uid):
    """Manual 'Extract travel' for any doc — on-demand counterpart to the auto
    pass. Returns the extracted travel suggestion."""
    upload = DocUpload.query.get_or_404(uid)
    _require_project_role(upload.project_id, 'editor')
