@app.route("/projects/<int:pid>/budget/<int:bid>/travel/apply-doc", methods=["POST"])
@login_required
def travel_apply_doc(pid, bid):
    """Apply an extracted travel suggestion to a person + travel day: find/create
    the person's travel ScheduleDay for the date, flip the kind flag, upsert the
    TravelDetail (confirmation #, flight/hotel fields), and stamp the doc's
    crew_member_id. One-click confirm from the doc-detail Travel panel. (User
    2026-06-22.)"""
    _require_project_role(pid, 'editor')
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    data = request.get_json(force=True) or {}
    uid      = data.get("doc_upload_id")
    line_id  = int(data.get("line_id"))
    instance = int(data.get("instance") or 1)
    date_s   = (data.get("date") or "").strip()
    kind     = (data.get("kind") or "").strip()
    if kind not in ('flight', 'hotel', 'car_rental'):
        return jsonify({"error": "Invalid kind"}), 400
    from datetime import datetime as _dt
    try:
        date_obj = _dt.strptime(date_s[:10], "%Y-%m-%d").date()
    except Exception:
        return jsonify({"error": "Invalid date"}), 400

    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
    from sqlalchemy import or_ as _or_apply
    sd = ScheduleDay.query.filter(
        ScheduleDay.budget_id == bid, ScheduleDay.budget_line_id == line_id,
        ScheduleDay.crew_instance == instance, ScheduleDay.date == date_obj,
        _or_apply(ScheduleDay.schedule_mode == sched_mode, ScheduleDay.schedule_mode == None),
    ).first()
    if not sd:
        sd = ScheduleDay(budget_id=bid, budget_line_id=line_id, crew_instance=instance,
                         date=date_obj, schedule_mode=sched_mode, day_type='travel')
        db.session.add(sd)
        db.session.flush()

    import json as _j2
    try:
        flags = _j2.loads(sd.cell_flags) if sd.cell_flags else {}
    except (ValueError, TypeError):
        flags = {}
    flags[kind] = True
    sd.cell_flags = _j2.dumps(flags)

    td = TravelDetail.query.filter_by(schedule_day_id=sd.id, kind=kind).first()
    if not td:
        td = TravelDetail(schedule_day_id=sd.id, kind=kind)
        db.session.add(td)

    def _s(k):
        v = data.get(k)
        v = v.strip() if isinstance(v, str) else v
        return v or None
    def _pdt(s):
        if not s:
            return None
        try:
            return _dt.fromisoformat(s)
        except Exception:
            try:
                return _dt.strptime(s[:16], "%Y-%m-%dT%H:%M")
            except Exception:
                return None
    def _pd(s):
        if not s:
            return None
        try:
            return _dt.strptime(s[:10], "%Y-%m-%d").date()
        except Exception:
            return None

    if _s('confirmation_no'):
        td.confirmation_no = _s('confirmation_no')
    if _s('notes'):
        td.notes = _s('notes')
    if kind == 'flight':
        for f in ('airline', 'flight_no', 'depart_airport', 'arrive_airport'):
            if _s(f):
                setattr(td, f, _s(f))
        if data.get('depart_at'):
            td.depart_at = _pdt(data.get('depart_at'))
        if data.get('arrive_at'):
            td.arrive_at = _pdt(data.get('arrive_at'))
    elif kind == 'hotel':
        for f in ('hotel_name', 'hotel_address', 'room_type'):
            if _s(f):
                setattr(td, f, _s(f))
        if data.get('check_in'):
            td.check_in = _pd(data.get('check_in'))
        if data.get('check_out'):
            td.check_out = _pd(data.get('check_out'))
    elif kind == 'car_rental':
        for f in ('rental_co', 'pickup_location'):
            if _s(f):
                setattr(td, f, _s(f))
        if data.get('pickup_at'):
            td.pickup_at = _pdt(data.get('pickup_at'))
        if data.get('return_at'):
            td.return_at = _pdt(data.get('return_at'))

    # Stamp the doc with the crew member so it shows on that person.
    if uid:
        up = DocUpload.query.filter_by(id=uid, project_id=pid).first()
        ca = CrewAssignment.query.filter_by(budget_line_id=line_id, instance=instance).first()
        if up is not None and ca is not None and getattr(ca, 'crew_member_id', None):
            up.crew_member_id = ca.crew_member_id

    db.session.commit()
    try:
        sync_schedule_driven_lines(bid, db.session)
    except Exception as _se:
        logging.warning(f"[travel_apply_doc] sync failed: {_se}")
    try:
        _ws_emit_tab_refresh(bid, 'travel')
    except Exception:
        pass
    return jsonify({"ok": True, "schedule_day_id": sd.id, "travel_detail_id": td.id,
                    "kind": kind})


@app.route("/projects/<int:pid>/actuals/ai-cleanup", methods=["POST"])
@login_required
def actuals_ai_cleanup(pid):
    """Batch vendor cleanup over charges with NO receipt (CSV/QBO/manual) — the
    Actuals-side counterpart to /docs/ai-cleanup. Small batch per call; returns
    `remaining` so the UI loops until dry. (User 2026-06-18.)"""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    body = request.get_json(silent=True) or {}
    try:
        limit = min(15, max(1, int(body.get('limit', 8))))
    except (TypeError, ValueError):
        limit = 8
    force = bool(body.get('force'))
    q = (Transaction.query
         .filter(Transaction.project_id == pid,
                 Transaction.vendor.isnot(None),
                 Transaction.doc_upload_id.is_(None),   # doc-linked charges clean via the doc
                 Transaction.source.in_(('csv_import', 'qbo_sync', 'manual_entry', 'reconciled'))))
    if not force:
        q = q.filter(Transaction.ai_cleaned_at.is_(None))
    total_remaining = q.count()
    rows = q.order_by(Transaction.id.desc()).limit(limit).all()
    known = _ai_known_vendors(pid)
    applied = 0
    flagged = 0
    for t in rows:
        try:
            r = _ai_clean_transaction(t, known=known, force=force)
            if r and r.get('applied'):
                applied += 1
            if r and r.get('flagged'):
                flagged += 1
        except Exception as e:
            logging.warning(f"[actuals/ai-cleanup] txn #{getattr(t,'id','?')} failed: {e}")
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
    return jsonify({"ok": True, "processed": len(rows), "applied": applied,
                    "flagged": flagged, "remaining": max(0, total_remaining - len(rows))})


@app.route("/projects/<int:pid>/actuals/ai-suggest-codes", methods=["POST"])
@login_required
def actuals_ai_suggest_codes(pid):
    """Batch: run AI categorize over UNCODED charges and store advisory
    suggestions. Processes a small batch per call (memory hits are instant;
    LLM calls aren't) and returns `remaining` so the UI can loop until dry.
    Body: {limit?, force?}. (User 2026-06-18.)"""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    body = request.get_json(silent=True) or {}
    try:
        limit = min(20, max(1, int(body.get('limit', 10))))
    except (TypeError, ValueError):
        limit = 10
    force = bool(body.get('force'))
    q = (Transaction.query
         .filter(Transaction.project_id == pid,
                 Transaction.account_code.is_(None),
                 Transaction.not_project_expense == False,   # noqa: E712
                 Transaction.vendor.isnot(None),
                 db.or_(Transaction.claimed_by_project_id.is_(None),
                        Transaction.claimed_by_project_id == pid)))
    if not force:
        q = q.filter(Transaction.ai_suggested_code.is_(None))
    total_remaining = q.count()
    rows = q.order_by(Transaction.id.desc()).limit(limit).all()
    taxonomy = _ai_coa_taxonomy()
    past = _ai_past_corrections(pid)
    suggested = 0
    no_match = 0
    for txn in rows:
        try:
            if _ai_suggest_code_for_txn(txn, taxonomy=taxonomy, past=past, force=force):
                suggested += 1
            else:
                no_match += 1
        except Exception as e:
            logging.warning(f"[ai-suggest] txn #{getattr(txn,'id','?')} failed: {e}")
            no_match += 1
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
    return jsonify({"ok": True, "processed": len(rows), "suggested": suggested,
                    "no_match": no_match, "remaining": max(0, total_remaining - len(rows))})


