@app.route("/projects/<int:pid>/actuals/ai-match", methods=["POST"])
@login_required
def actuals_ai_match(pid):
    """AI-driven matching: for each still-unmatched charge, feed its heuristic
    candidate receipts to the AI to pick the best (or none) and write a SUGGESTED
    match — which surfaces in the existing gold 'Suggested match' banner for
    one-click Confirm. Batched (returns `remaining`); a per-charge watermark
    (ai_match_checked_at) lets it resume and skip declined charges. A single
    exact-amount + vendor candidate is taken without an AI call. (User 2026-06-18.)"""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    body = request.get_json(silent=True) or {}
    try:
        limit = min(12, max(1, int(body.get('limit', 6))))
    except (TypeError, ValueError):
        limit = 6
    force = bool(body.get('force'))
    import ai_layer, time as _t
    from actuals import find_match_candidates
    try:
        cand = find_match_candidates(pid, amount_tol=3.0, date_window=None, use_vendor=False)
    except Exception as e:
        logging.exception("[ai-match] candidate build failed")
        return jsonify({"error": str(e)}), 500
    # find_match_candidates returns {results:[{charge, candidates, ...}], ...}.
    by_charge = {c["charge"]["id"]: c for c in (cand.get("results") or [])}

    q = (Transaction.query
         .filter(Transaction.project_id == pid,
                 Transaction.source.in_(('qbo_sync', 'csv_import')),
                 Transaction.match_status == 'unmatched',
                 Transaction.doc_upload_id.is_(None),
                 Transaction.not_project_expense == False))   # noqa: E712
    if not force:
        q = q.filter(Transaction.ai_match_checked_at.is_(None))
    total_remaining = q.count()
    rows = q.order_by(Transaction.id.desc()).limit(limit).all()

    used = set()
    suggested = 0
    ai_calls = 0
    for txn in rows:
        txn.ai_match_checked_at = datetime.utcnow()
        entry = by_charge.get(txn.id)
        cands = [c for c in (entry["candidates"] if entry else [])
                 if c["doc_upload_id"] not in used]
        if not cands:
            continue
        best_id, best_conf, src = None, 0.0, 'ai'
        exacts = [c for c in cands
                  if (c.get("amount_delta") or 9) <= 0.01 and c.get("vendor_match")]
        if len(exacts) == 1:
            best_id = exacts[0]["doc_upload_id"]
            best_conf = max(0.9, float(exacts[0].get("confidence") or 0.9))
            src = 'heuristic'
        else:
            payload = {"charge": entry["charge"],
                       "candidates": [{"doc_id": c["doc_upload_id"], "vendor": c.get("vendor"),
                                       "amount": c.get("amount"), "date": c.get("date"),
                                       "card": c.get("card"), "amount_delta": c.get("amount_delta"),
                                       "day_gap": c.get("day_gap"),
                                       "opposite_sign": c.get("opposite_sign"),
                                       "vendor_match": c.get("vendor_match")} for c in cands]}
            t0 = _t.time()
            res = ai_layer.pick_match(payload)
            ai_calls += 1
            _ai_log_event(pid, None, 'match', res.get('_provider'), res.get('_model'),
                          payload, res, int((_t.time() - t0) * 1000))
            try:
                bid = res.get("best_doc_id")
                bid = int(bid) if bid is not None else None
            except (TypeError, ValueError):
                bid = None
            try:
                conf = float(res.get("confidence") or 0)
            except (TypeError, ValueError):
                conf = 0.0
            if bid in {c["doc_upload_id"] for c in cands} and conf >= 0.6:
                best_id, best_conf, src = bid, conf, 'ai'
        if best_id is not None:
            txn.doc_upload_id = best_id
            txn.match_status = 'suggested'
            txn.match_confidence = round(best_conf, 3)
            txn.match_source = src
            txn.updated_at = datetime.utcnow()
            used.add(best_id)
            suggested += 1
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
    return jsonify({"ok": True, "processed": len(rows), "suggested": suggested,
                    "ai_calls": ai_calls, "remaining": max(0, total_remaining - len(rows))})


@app.route("/projects/<int:pid>/actuals/clear-match-suggestions", methods=["POST"])
@login_required
def actuals_clear_match_suggestions(pid):
    """Undo all SUGGESTED (not confirmed) matches + reset the AI-match watermark,
    so the AI match pass can be re-run from scratch (testing). (User 2026-06-18.)"""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    n = (Transaction.query
         .filter(Transaction.project_id == pid,
                 Transaction.match_status == 'suggested')
         .update({Transaction.match_status: 'unmatched',
                  Transaction.doc_upload_id: None,
                  Transaction.match_confidence: None,
                  Transaction.match_source: None},
                 synchronize_session=False))
    (Transaction.query
     .filter(Transaction.project_id == pid,
             Transaction.ai_match_checked_at.isnot(None))
     .update({Transaction.ai_match_checked_at: None}, synchronize_session=False))
    db.session.commit()
    return jsonify({"ok": True, "cleared": n})


@app.route("/projects/<int:pid>/actuals/unmatch-all", methods=["POST"])
@login_required
def actuals_unmatch_all(pid):
    """TEST RESET: unlink EVERY charge from its receipt and return all matched
    charges (suggested AND confirmed) to the unmatched pool, reverting
    reconciled→csv_import so they re-enter the candidate pool, and clearing the
    AI-match watermark. Receipts (DocUpload) become available candidates again.
    Body {confirm:true} required — intended for a sandbox project. (User 2026-06-18.)"""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    body = request.get_json(silent=True) or {}
    if not body.get('confirm'):
        return jsonify({"error": "pass {confirm: true} to confirm this reset"}), 400
    reverted = (Transaction.query
                .filter(Transaction.project_id == pid, Transaction.source == 'reconciled')
                .update({Transaction.source: 'csv_import'}, synchronize_session=False))
    unmatched = (Transaction.query
                 .filter(Transaction.project_id == pid,
                         Transaction.source.in_(('qbo_sync', 'csv_import')),
                         db.or_(Transaction.doc_upload_id.isnot(None),
                                Transaction.match_status != 'unmatched',
                                Transaction.ai_match_checked_at.isnot(None)))
                 .update({Transaction.doc_upload_id: None,
                          Transaction.match_status: 'unmatched',
                          Transaction.match_confidence: None,
                          Transaction.match_source: None,
                          Transaction.ai_match_checked_at: None},
                         synchronize_session=False))
    # Also clear any 'remembered' rejections so nothing is suppressed in the re-test.
    try:
        from models import MatchRejection
        MatchRejection.query.filter_by(project_id=pid).delete(synchronize_session=False)
    except Exception:
        pass
    db.session.commit()
    return jsonify({"ok": True, "unmatched": unmatched, "reverted_reconciled": reverted})


@app.route("/projects/<int:pid>/docs/ai-cleanup", methods=["POST"])
@login_required
def docs_ai_cleanup(pid):
    """Batch: run the AI data-cleanup pass over docs not yet cleaned (vendor
    normalization + extraction sanity). Small batch per call (memory hits are
    instant, LLM calls aren't); returns `remaining` so the UI loops until dry.
    Mirrors actuals_ai_suggest_codes. (User 2026-06-18.)"""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    body = request.get_json(silent=True) or {}
    try:
        limit = min(15, max(1, int(body.get('limit', 8))))
    except (TypeError, ValueError):
        limit = 8
    force = bool(body.get('force'))
    q = (DocUpload.query
         .filter(DocUpload.project_id == pid,
                 DocUpload.status.notin_(('deleted', 'error')),
                 DocUpload.vendor.isnot(None)))
    if not force:
        q = q.filter(DocUpload.ai_cleaned_at.is_(None))
    total_remaining = q.count()
    docs = q.order_by(DocUpload.id.desc()).limit(limit).all()
    known = _ai_known_vendors(pid)
    applied = 0
    flagged = 0
    for d in docs:
        try:
            r = _ai_clean_document(d, known=known, force=force)
            if r and r.get('applied'):
                applied += 1
            if r and r.get('flagged'):
                flagged += 1
        except Exception as e:
            logging.warning(f"[docs/ai-cleanup] doc #{getattr(d,'id','?')} failed: {e}")
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
    return jsonify({"ok": True, "processed": len(docs), "applied": applied,
                    "flagged": flagged, "remaining": max(0, total_remaining - len(docs))})


def _run_double_coded_scan(pid):
    """Scan for double-coded spend and upsert AnomalyFlag rows. Does NOT commit
    (caller commits). Returns (clusters_found, flags_upserted)."""
    from actuals import scan_double_coded
    clusters = scan_double_coded(pid)
    flags = 0
    for c in clusters:
        coded = [m for m in c["members"] if m["coded"]]
        if len(coded) < 2:
            continue
        tids = sorted(m["tid"] for m in coded)
        dedup = "double_coded:" + "-".join(str(t) for t in tids)
        secs = ", ".join(sorted({(m["account_code_name"] or str(m["account_code"]))
                                 for m in coded if (m["account_code_name"] or m["account_code"])}))
        title = f'Possible double-coded spend · ${c["amount"]:,.2f}'
        expl = (f'{len(coded)} charges for {c["vendor"] or "this vendor"} on '
                f'{c["date"] or "the same date"} (${c["amount"]:,.2f} each) are all coded to '
                f'the budget' + (f' ({secs})' if secs else '') +
                f'. That double-counts about ${c["overcount"]:,.2f}. '
                f'Keep one and un-code or remove the rest.')
        f = _flag_anomaly(pid, 'double_coded', severity='high', title=title,
                          explanation=expl, transaction_id=tids[0],
                          payload={"members": c["members"], "overcount": c["overcount"],
                                   "amount": c["amount"], "vendor": c["vendor"],
                                   "date": c["date"]},
                          dedup_key=dedup)
        if f is not None:
            flags += 1
    return len(clusters), flags


def _run_duplicate_receipt_scan(pid):
    """Flag receipts that duplicate the same spend (when one is already
    matched/coded, the others are dupes). Catches the case scan_double_coded
    misses — a fresh receipt next to a single already-filed one. Does NOT commit.
    Returns flag count. (User 2026-06-22.)"""
    from actuals import scan_duplicate_receipts
    flags = 0
    for c in scan_duplicate_receipts(pid):
        dups = [d for d in c["docs"] if d["id"] != c["keep_doc_id"]]
        if not dups:
            continue
        doc_ids = sorted(d["id"] for d in c["docs"])
        dedup = "dup_receipt:" + "-".join(str(i) for i in doc_ids)
        keeper = next((d for d in c["docs"] if d["id"] == c["keep_doc_id"]), None)
        settled = bool(keeper and (keeper["matched"] or keeper["coded"]))
        title = f'Duplicate receipt · ${c["amount"]:,.2f}'
        expl = (f'{len(c["docs"])} receipts for {c["vendor"] or "this vendor"} on '
                f'{c["date"] or "the same date"} (${c["amount"]:,.2f}) — '
                + ('one is already matched/coded, so the rest are duplicates. '
                   if settled else 'likely the same receipt scanned more than once. ')
                + 'Keep one and delete the rest.')
        f = _flag_anomaly(pid, 'duplicate_receipt',
                          severity=('high' if settled else 'medium'),
                          title=title, explanation=expl, doc_upload_id=dups[0]["id"],
                          payload={"amount": c["amount"], "vendor": c["vendor"],
                                   "date": c["date"], "keep_doc_id": c["keep_doc_id"],
                                   "docs": c["docs"]},
                          dedup_key=dedup)
        if f is not None:
            flags += 1
    return flags


def _run_budget_mismatch_scan(pid):
    """Flag where money doesn't match the plan: (a) POs billed over their committed
    cap, and (b) non-labor budget lines whose actual spend significantly exceeds
    the planned amount. Upserts AnomalyFlag(type='budget_mismatch'). Does NOT
    commit. Returns flag count. (User 2026-06-18.)"""
    from models import PurchaseOrder, BudgetLine, Budget
    flags = 0
    # (a) POs over their committed cap — reuse the canonical PO rollup.
    try:
        for po in PurchaseOrder.query.filter_by(project_id=pid, archived=False).all():
            if po.total_committed is None:
                continue
            try:
                d = _po_to_dict(po, with_rollup=True, project_id=pid)
            except Exception:
                continue
            if not d.get('over_cap'):
                continue
            cap = float(po.total_committed)
            billed = float(d.get('billed_total') or 0)
            over = billed - cap
            f = _flag_anomaly(pid, 'budget_mismatch', severity='high',
                              title=f'PO over cap · ${over:,.2f} over',
                              explanation=(f'PO {po.po_number or po.id} '
                                           f'({po.vendor_name or "vendor"}) has ${billed:,.2f} billed '
                                           f'against a ${cap:,.2f} cap — ${over:,.2f} over. Check the '
                                           f'invoices and coding on this PO.'),
                              confidence=None,
                              payload={"kind": "po_over_cap", "po_id": po.id, "cap": round(cap, 2),
                                       "billed": round(billed, 2), "over": round(over, 2),
                                       "po_number": po.po_number, "vendor": po.vendor_name},
                              dedup_key=f'po_over_cap:{po.id}')
            if f is not None:
                flags += 1
    except Exception as e:
        logging.warning(f"[budget-scan] PO pass failed: {e}")
    # (b) non-labor Actual budget lines over their planned amount.
    try:
        actual = (Budget.query.filter_by(project_id=pid, is_actual=True, version_status='current')
                  .order_by(Budget.id.desc()).first())
        if actual:
            sums = {}
            for t in (Transaction.query
                      .filter(Transaction.project_id == pid,
                              Transaction.budget_line_id.isnot(None),
                              Transaction.not_project_expense == False).all()):   # noqa: E712
                if t.amount is None:
                    continue
                try:
                    amt = float(t.amount)
                except (TypeError, ValueError):
                    continue
                if amt <= 0:   # expenses only (refunds/credits are negative)
                    continue
                sums[t.budget_line_id] = sums.get(t.budget_line_id, 0.0) + amt
            for ln in BudgetLine.query.filter_by(budget_id=actual.id).all():
                if getattr(ln, 'is_labor', False):
                    continue
                planned = float(ln.estimated_total or 0)
                if planned <= 0:
                    continue
                actual_amt = sums.get(ln.id, 0.0)
                over = actual_amt - planned
                # Only flag a meaningful overage: ≥ $50 AND ≥ 10% over plan.
                if over < 50 or over < planned * 0.10:
                    continue
                label = ln.description or ln.account_name or f'Line {ln.id}'
                f = _flag_anomaly(pid, 'budget_mismatch', severity='medium',
                                  title=f'Over budget · {label}'[:120],
                                  explanation=(f'"{label}" has ${actual_amt:,.2f} actual vs '
                                               f'${planned:,.2f} planned — ${over:,.2f} over. Verify the '
                                               f'coded charges/invoices match the budget line.'),
                                  confidence=None,
                                  payload={"kind": "line_over_budget", "line_id": ln.id,
                                           "planned": round(planned, 2), "actual": round(actual_amt, 2),
                                           "over": round(over, 2), "line": label},
                                  dedup_key=f'line_over_budget:{ln.id}')
                if f is not None:
                    flags += 1
    except Exception as e:
        logging.warning(f"[budget-scan] line pass failed: {e}")
    return flags


def _crew_lines_for_project(pid):
    """Map crew members to their (single) Working budget line — so a person can be
    matched to a precise line. Returns (crew_one {crew_id: working_line_id},
    crews {id: CrewMember}, line_labels {line_id: label}). Only crew assigned to
    EXACTLY ONE line are returned (unambiguous). (User 2026-06-18.)"""
    from models import CrewMember, CrewAssignment, BudgetLine
    from actuals import get_current_working_budget
    wb = get_current_working_budget(pid)
    if not wb:
        return {}, {}, {}
    assigns = {}
    for ca in (CrewAssignment.query
               .join(BudgetLine, CrewAssignment.budget_line_id == BudgetLine.id)
               .filter(BudgetLine.budget_id == wb.id).all()):
        if ca.crew_member_id:
            assigns.setdefault(ca.crew_member_id, set()).add(ca.budget_line_id)
    for ln in (BudgetLine.query
               .filter(BudgetLine.budget_id == wb.id,
                       BudgetLine.assigned_crew_id.isnot(None)).all()):
        assigns.setdefault(ln.assigned_crew_id, set()).add(ln.id)
    crew_one = {cid: next(iter(lids)) for cid, lids in assigns.items() if len(lids) == 1}
    if not crew_one:
        return {}, {}, {}
    crews = {c.id: c for c in CrewMember.query.filter(CrewMember.id.in_(list(crew_one.keys()))).all()}
    line_labels = {ln.id: (ln.description or ln.account_name or f'Line {ln.id}')
                   for ln in BudgetLine.query.filter(BudgetLine.id.in_(list(crew_one.values()))).all()}
    return crew_one, crews, line_labels


def _run_people_line_scan(pid):
    """Suggest coding a charge to a PERSON's specific budget line: when an
    (uncoded-to-line) charge's vendor name matches a crew member who has a single
    budget line, queue a people_line review flag. Suggest-only — applied via
    anomaly_resolve 'apply_people_line'. Does NOT commit. Returns count."""
    from actuals import _vendor_similarity
    crew_one, crews, line_labels = _crew_lines_for_project(pid)
    if not crew_one:
        return 0
    txns = (Transaction.query
            .filter(Transaction.project_id == pid,
                    Transaction.budget_line_id.is_(None),
                    Transaction.not_project_expense == False,   # noqa: E712
                    Transaction.vendor.isnot(None)).all())
    flags = 0
    for t in txns:
        v = (t.vendor or '').strip()
        if not v:
            continue
        best, best_sim = None, 0.0
        for cid in crew_one:
            cm = crews.get(cid)
            if not cm or not cm.name:
                continue
            sim = _vendor_similarity(v, cm.name)
            if sim > best_sim:
                best_sim, best = sim, cid
        if best is None or best_sim < 0.80:
            continue
        lid = crew_one[best]
        cm = crews[best]
        label = line_labels.get(lid, 'their line')
        f = _flag_anomaly(pid, 'people_line', severity='low',
                          title=f'Code to {cm.name} · {label}'[:120],
                          explanation=(f'"{v}" looks like {cm.name}, who is on the budget line '
                                       f'"{label}". Apply to code this charge to that line and '
                                       f'attach the person.'),
                          confidence=round(best_sim, 3), transaction_id=t.id,
                          doc_upload_id=t.doc_upload_id,
                          payload={"crew_member_id": best, "crew_name": cm.name,
                                   "working_line_id": lid, "line_label": label,
                                   "transaction_id": t.id},
                          dedup_key=f'people_line:{t.id}')
        if f is not None:
            flags += 1
    return flags


@app.route("/projects/<int:pid>/actuals/scan-anomalies", methods=["POST"])
@login_required
def actuals_scan_anomalies(pid):
    """Scan for issues and upsert AnomalyFlag review-queue rows: double-coded
    duplicates, budget mismatches (POs over cap, lines over plan), and people→line
    coding suggestions (invoice person → their budget line). (User 2026-06-18.)"""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    clusters, flags = _run_double_coded_scan(pid)
    dup_receipt_flags = _run_duplicate_receipt_scan(pid)
    budget_flags = _run_budget_mismatch_scan(pid)
    people_flags = _run_people_line_scan(pid)
    try:
        db.session.commit()
    except Exception:
        db.session.rollback()
    return jsonify({"ok": True, "clusters": clusters, "flags": flags,
                    "dup_receipt_flags": dup_receipt_flags,
                    "budget_flags": budget_flags, "people_flags": people_flags,
                    "total_flags": flags + dup_receipt_flags + budget_flags + people_flags})


def _run_all_scans(pid):
    """Run the full heuristic scan suite (double-coded + budget mismatch +
    people→line) and commit. Fail-open: never raises. Returns total flags.
    Shared by the manual button and the auto-run-after-ingestion triggers.
    (Phase 3 automation, 2026-06-22.)"""
    total = 0
    try:
        _c, f1 = _run_double_coded_scan(pid)
        f4 = _run_duplicate_receipt_scan(pid)
        f2 = _run_budget_mismatch_scan(pid)
        f3 = _run_people_line_scan(pid)
        db.session.commit()
        total = (f1 or 0) + (f4 or 0) + (f2 or 0) + (f3 or 0)
    except Exception:
        db.session.rollback()
        logging.warning("[_run_all_scans] failed for pid=%s", pid, exc_info=True)
    return total


def _bg_run_all_scans(pid):
    """Fire-and-forget the scan suite in a background thread so ingestion
    (CSV import / QBO sync) returns immediately while the review queue refreshes
    on its own. (Phase 3 automation, 2026-06-22.)"""
    import threading
    def _worker():
        with app.app_context():
            try:
                _run_all_scans(pid)
            except Exception:
                logging.warning("[_bg_run_all_scans] failed pid=%s", pid, exc_info=True)
            finally:
                try:
                    db.session.remove()
                except Exception:
                    pass
    try:
        threading.Thread(target=_worker, daemon=True).start()
    except Exception:
        logging.warning("[_bg_run_all_scans] could not start thread pid=%s", pid, exc_info=True)


def _anomaly_to_dict(f):
    import json as _j
    try:
        payload = _j.loads(f.payload_json) if f.payload_json else None
    except Exception:
        payload = None
    return {"id": f.id, "type": f.type, "severity": f.severity, "title": f.title,
            "explanation": f.explanation,
            "confidence": float(f.confidence) if f.confidence is not None else None,
            "doc_upload_id": f.doc_upload_id, "transaction_id": f.transaction_id,
            "payload": payload,
            "created_at": f.created_at.isoformat() if f.created_at else None}


@app.route("/projects/<int:pid>/anomalies", methods=["GET"])
@login_required
def project_anomalies(pid):
    """Unresolved review-queue items for the Dashboard Action Center."""
    ProjectSheet.query.get_or_404(pid)
    if current_user.role not in ('super_admin', 'admin'):
        if not ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first():
            return jsonify({"error": "Forbidden"}), 403
    from models import AnomalyFlag
    flags = (AnomalyFlag.query.filter_by(project_id=pid, resolved=False)
             .order_by(AnomalyFlag.created_at.desc()).all())
    items = [_anomaly_to_dict(f) for f in flags]

    # Phase 2: surface uncoded charges that already have an AI code suggestion as
    # "Codes to confirm" queue items (one-click Accept). Synthesized live here
    # (not persisted as flags) so they vanish the moment the charge is coded.
    # (2026-06-22.)
    try:
        code_txns = (Transaction.query
                     .filter(Transaction.project_id == pid,
                             Transaction.budget_line_id.is_(None),
                             Transaction.account_code.is_(None),
                             Transaction.not_project_expense == False,   # noqa: E712
                             Transaction.ai_suggested_code.isnot(None))
                     .order_by(Transaction.id.desc()).limit(30).all())
    except Exception:
        code_txns = []
    for t in code_txns:
        conf = float(t.ai_code_confidence) if t.ai_code_confidence is not None else None
        nm = (t.ai_suggested_code_name or '').strip()
        amt = float(t.amount) if t.amount is not None else None
        items.append({
            "id": f"code-{t.id}", "type": "code_suggestion", "severity": "low",
            "title": f"Code {t.vendor or 'charge'} → {nm or t.ai_suggested_code}",
            "explanation": (f"${abs(amt):,.2f} · " if amt is not None else "")
                           + (t.vendor or '—')
                           + f" — AI suggests {t.ai_suggested_code}"
                           + (f" {nm}" if nm else "")
                           + (f" ({round(conf * 100)}%)" if conf is not None else ""),
            "confidence": conf, "transaction_id": t.id, "doc_upload_id": None,
            "payload": {"tid": t.id, "code": t.ai_suggested_code, "name": nm,
                        "vendor": t.vendor, "amount": amt},
        })

    rank = {'high': 0, 'medium': 1, 'low': 2}
    items.sort(key=lambda it: rank.get(it['severity'], 3))
    by_type = {}
    for it in items:
        by_type[it["type"]] = by_type.get(it["type"], 0) + 1
    return jsonify({"ok": True, "count": len(items), "by_type": by_type, "items": items})


@app.route("/projects/<int:pid>/anomalies/<int:fid>/resolve", methods=["POST"])
@login_required
def anomaly_resolve(pid, fid):
    """Apply a fix for a review-queue item, then mark it resolved. Body:
    {action, value?, transaction_id?}. Actions: apply_vendor | accept_amount |
    uncode | mark_not_project | delete_txn | (any other → resolve-only)."""
    ProjectSheet.query.get_or_404(pid)
    _require_project_role(pid, 'editor')
    from models import AnomalyFlag
    import json as _j
    f = AnomalyFlag.query.filter_by(id=fid, project_id=pid).first_or_404()
    body = request.get_json(silent=True) or {}
    action = (body.get('action') or '').strip()
    tid = body.get('transaction_id')
    try:
        payload = _j.loads(f.payload_json) if f.payload_json else {}
    except Exception:
        payload = {}
    applied = None
    try:
        if action == 'apply_vendor' and f.doc_upload_id:
            suggested = (body.get('value') or payload.get('suggested') or '').strip()
            doc = db.session.get(DocUpload, f.doc_upload_id)
            if suggested and doc:
                raw = doc.vendor or ''
                doc.vendor = suggested[:200]
                for tx in Transaction.query.filter_by(doc_upload_id=doc.id).all():
                    tx.vendor = suggested[:300]
                from actuals import record_vendor_alias
                record_vendor_alias(pid, raw, suggested)
                applied = f'vendor → {suggested}'
        elif action == 'apply_vendor' and f.transaction_id:
            suggested = (body.get('value') or payload.get('suggested') or '').strip()
            tx = Transaction.query.filter_by(id=f.transaction_id, project_id=pid).first()
            if suggested and tx:
                raw = tx.vendor or ''
                tx.vendor = suggested[:300]
                from actuals import record_vendor_alias
                record_vendor_alias(pid, raw, suggested)
                applied = f'vendor → {suggested}'
        elif action == 'apply_people_line':
            lid = payload.get('working_line_id')
            cid = payload.get('crew_member_id')
            tid = payload.get('transaction_id') or f.transaction_id
            if lid and tid:
                from actuals import link_transaction_to_line
                link_transaction_to_line(int(tid), int(lid),
                                         user_id=(current_user.id if current_user.is_authenticated else None))
                tx = Transaction.query.filter_by(id=int(tid), project_id=pid).first()
                if tx and tx.doc_upload_id and cid:
                    doc = db.session.get(DocUpload, tx.doc_upload_id)
                    if doc:
                        doc.crew_member_id = int(cid)
                applied = (f'coded to {payload.get("line_label") or "line"}'
                           + (f' + attached {payload.get("crew_name")}' if cid else ''))
        elif action == 'accept_amount' and f.doc_upload_id:
            amt = body.get('value', payload.get('suggested_amount'))
            doc = db.session.get(DocUpload, f.doc_upload_id)
            if amt is not None and doc:
                doc.amount = amt
                for tx in Transaction.query.filter_by(doc_upload_id=doc.id).all():
                    tx.amount = amt
                applied = f'amount → {amt}'
        elif action in ('uncode', 'mark_not_project', 'delete_txn') and tid:
            tx = Transaction.query.filter_by(id=int(tid), project_id=pid).first()
            if tx:
                if action == 'delete_txn':
                    db.session.delete(tx)
                    applied = f'deleted charge #{tid}'
                else:
                    tx.account_code = None
                    tx.account_code_name = None
                    tx.budget_line_id = None
                    tx.match_status = 'unmatched'
                    if action == 'mark_not_project':
                        tx.not_project_expense = True
                        applied = f'marked charge #{tid} not a project expense'
                    else:
                        applied = f'un-coded charge #{tid}'
                    try:
                        _sync_claim_state(tx)
                    except Exception:
                        pass
        f.resolved = True
        f.resolution = action or 'resolved'
        f.resolved_by = current_user.id if current_user.is_authenticated else None
        f.resolved_at = datetime.utcnow()
        db.session.commit()
        return jsonify({"ok": True, "applied": applied})
    except Exception as e:
        db.session.rollback()
        logging.exception(f"[anomaly resolve] {action} failed: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/projects/<int:pid>/anomalies/<int:fid>/dismiss", methods=["POST"])
@login_required
def anomaly_dismiss(pid, fid):
    """Dismiss a review-queue item with no change ('not a duplicate' / 'vendor is
    fine'). Suppresses re-flagging of the same dedup_key on later scans."""
