@app.route("/projects/<int:pid>/budget/<int:bid>/preview/<target>")
@login_required
def export_preview(pid, bid, target):
    """Returns JSON for the right-drawer preview. target ∈ {mmb, showbiz}."""
    _require_project_role(pid, 'editor')
    if target not in ('mmb', 'showbiz'):
        return jsonify({"error": "Unknown target"}), 400
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    from external_export import preview_mmb, preview_showbiz
    data = preview_mmb(budget) if target == 'mmb' else preview_showbiz(budget)
    data["budget_name"] = budget.name
    data["target"] = target
    return jsonify(data)


@app.route("/projects/<int:pid>/budget/<int:bid>/export.pdf")
@login_required
def export_pdf(pid, bid):
    budget  = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    project = ProjectSheet.query.get_or_404(pid)
    lines   = BudgetLine.query.filter_by(budget_id=bid).order_by(
        BudgetLine.account_code, BudgetLine.sort_order).all()
    fringe_cfgs = get_fringe_configs(db.session, pid)

    # ── Sub-budget filter (2026-05-26) ────────────────────────────────
    # When ?sub_budget=<id> is set, render the PDF as a slice of the
    # parent budget — keep only lines that are assigned to that
    # sub-budget. Same template, same calc, just a filtered line set.
    # The Top Sheet rolls up only the included lines, so the GRAND
    # TOTAL is the sub-budget's total (client sees only their slice).
    sub_budget_id = request.args.get('sub_budget', type=int)
    sub_budget_obj = None
    if sub_budget_id:
        sub_budget_obj = SubBudget.query.filter_by(
            id=sub_budget_id, project_id=pid).first()
        if not sub_budget_obj:
            return jsonify({"error": "Sub-budget not found"}), 404
        _sb_line_ids = {r[0] for r in db.session.query(SubBudgetLine.budget_line_id)
                                         .filter(SubBudgetLine.sub_budget_id == sub_budget_id)
                                         .all()}
        # Also include any child rows (kit fees) of included parent
        # lines, so the export reads naturally with their parent.
        _children = {ln.id for ln in lines
                     if ln.parent_line_id and ln.parent_line_id in _sb_line_ids}
        _keep_ids = _sb_line_ids | _children
        lines = [ln for ln in lines if ln.id in _keep_ids]

    # Per-export overrides from the Export Options dialog (see export_csv
    # for the same pattern). Applied to the in-memory Budget without
    # persisting so the saved settings stay untouched.
    suppress_zeros = request.args.get("suppress_zeros") == "1"
    if "fee_dispersed" in request.args:
        budget.company_fee_dispersed = request.args.get("fee_dispersed") == "1"
    profile  = budget.payroll_profile
    pw_start = budget.payroll_week_start if budget.payroll_week_start is not None else (
        profile.payroll_week_start if profile else 6)

    actuals_by_code = _actuals_by_section_code(pid)

    top_sheet   = calc_top_sheet(budget, lines, fringe_cfgs, actuals_by_code, profile, pw_start)
    detail_mode = request.args.get("detail", "0") == "1"
    dispersed   = bool(budget.company_fee_dispersed)

    # Build section detail for full-detail export
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'
    line_results = {}
    for ln in lines:
        if ln.use_schedule:
            sched = ScheduleDay.query.filter_by(budget_line_id=ln.id, schedule_mode=sched_mode).all()
            line_results[ln.id] = calc_line_from_schedule(ln, sched, fringe_cfgs, profile, pw_start)
        else:
            line_results[ln.id] = calc_line(ln, fringe_cfgs)

    # Group lines into sections
    from budget_calc import FP_COA_SECTIONS
    def _section_for_code(code):
        best = None
        for start, _ in FP_COA_SECTIONS:
            if code >= start:
                best = start
            else:
                break
        return best
    section_name_map = dict(FP_COA_SECTIONS)
    sections_detail = {}
    for ln in lines:
        sk = _section_for_code(ln.account_code)
        if sk not in sections_detail:
            sections_detail[sk] = {"code": sk, "name": section_name_map.get(sk, ""), "lines": []}
        sections_detail[sk]["lines"].append(ln)
    # Apply the same parent-child + sub-group clustering the in-app view
    # uses, so kit-fee rows attach to their parent labor line and
    # headers/spacers stay in the right sub-group on export. Without
    # this, the PDF showed kit fees in raw sort_order position (e.g.
    # "Laptop" kit fee for Tech Producer landed under Robo Cam Op
    # instead). User report 2026-05-26.
    for sec in sections_detail.values():
        sec["lines"] = _order_lines_with_children(sec["lines"])
    # Tag each section with column-visibility booleans so the PDF can
    # collapse columns that have no data — per user request 2026-04-28
    # the export shouldn't render Payroll / OT / Fringe / Agent% / Disc%
    # column headers if every cell would be empty.
    for sec in sections_detail.values():
        labor_lines    = [_l for _l in sec["lines"] if getattr(_l, 'is_labor', False)]
        nonlabor_lines = [_l for _l in sec["lines"] if not getattr(_l, 'is_labor', False)]
        sec["has_labor"]    = bool(labor_lines)
        # Show "Payroll" in place of "Qty" only when a labor line in
        # this section actually has a payroll_co value. Otherwise
        # fall back to "Qty" (filled for non-labor rows).
        sec["has_payroll"]  = any((_l.payroll_co or '').strip()
                                   for _l in labor_lines)
        # Hide Qty entirely if no non-labor line has a meaningful qty
        # (everything == 1 or empty). Lets purely-labor sections drop
        # the col without affecting non-labor sections.
        sec["has_qty"]      = any(float(_l.quantity or 0) and float(_l.quantity or 0) != 1
                                   for _l in nonlabor_lines)
        # OT / Fringe: only show if a labor line actually has them.
        sec["has_ot"]       = any(float((line_results.get(_l.id) or {}).get("ot_amount", 0) or 0) > 0
                                   for _l in labor_lines)
        sec["has_fringe"]   = any(float((line_results.get(_l.id) or {}).get("fringe_amount", 0) or 0) > 0
                                   for _l in labor_lines)
        # Agent% (labor) or Disc% (non-labor): show if any line has
        # a non-zero value.
        sec["has_agent"]    = any(float(_l.agent_pct or 0) for _l in labor_lines)
        sec["has_discount"] = any(float(_l.agent_pct or 0) for _l in nonlabor_lines)
    sections_ordered = [sections_detail[sk] for sk, _ in FP_COA_SECTIONS if sk in sections_detail]

    company_settings = CompanySettings.query.get(1) or CompanySettings()
    is_working_view  = budget.budget_mode in ('working', 'actual')

    fee_m = (1 + float(budget.company_fee_pct)) if dispersed else 1.0

    # ── Client-facing rounding for dispersed mode ──────────────────────
    # When the Prod Co Fee is dispersed across line totals, the raw math
    # produces awkward numbers ($1,070, $1,650) that flag the gross-up
    # to clients/auditors. For PDF export only (in-app stays exact), we
    # round each line's dispersed total to the nearest $10. Flat $10
    # bucket across labor + non-labor (per user 2026-04-28 — the prior
    # $25-for-labor split risked shifting line totals between exports
    # when only the bucket boundary changed).
    #
    # IMPORTANT: rounding is INDEPENDENT per line — one line's rounded
    # total never depends on another. So the same budget always exports
    # the same PDF numbers; adding/removing a line doesn't shift the
    # rounded values of existing lines. Determinism is the priority
    # over making section sums hit perfect round numbers.
    PDF_BUCKET = 10.0
    pdf_line_totals = {}
    pdf_section_totals = {}
    if dispersed:
        # ── Two-pass rounding with grand-total reconciliation ──────────
        # Pass 1: round each line's dispersed total independently to the
        #         nearest $10. Independent rounding = stability — adding
        #         or editing one line never shifts another's rounded total.
        # Pass 2: compute drift between sum(rounded lines) and
        #         round(true grand total). If drift != 0, distribute the
        #         drift in $10 increments by bumping individual lines
        #         whose fractional remainder was closest to the rounding
        #         boundary (largest-remainder method). This keeps every
        #         bumped line within $10 of its natural rounded value
        #         while making the visible grand total exact.
        true_grand = 0.0
        line_exact = {}     # id → exact dispersed total
        line_remainder = {} # id → signed distance to next $10 bucket
        for sec in sections_ordered:
            for ln in sec["lines"]:
                res = line_results.get(ln.id) or {}
                exact = float(res.get("est_total") or 0) * fee_m
                line_exact[ln.id] = exact
                rounded = round(exact / PDF_BUCKET) * PDF_BUCKET
                pdf_line_totals[ln.id] = rounded
                true_grand += exact
                # Remainder = how far from the bucket boundary in the
                # OPPOSITE direction we'd have to go (positive if we
                # rounded down and could bump up, negative if we rounded
                # up and could bump down).
                line_remainder[ln.id] = exact - rounded

        # Target = true grand total rounded to $10. Drift = target − sum(rounded).
        target_grand = round(true_grand / PDF_BUCKET) * PDF_BUCKET
        sum_rounded = sum(pdf_line_totals.values())
        drift = round((target_grand - sum_rounded) / PDF_BUCKET)  # in $10 units

        if drift != 0:
            # Bump up: pick lines that rounded DOWN (positive remainder),
            #          sorted by largest remainder first (closest to bumping anyway).
            # Bump down: pick lines that rounded UP (negative remainder),
            #          sorted by most-negative remainder first.
            # Each pick adjusts by one $10 unit; iterate until drift = 0
            # or we run out of candidates.
            ordered_ids = sorted(line_remainder, key=lambda i: line_remainder[i], reverse=(drift > 0))
            step = PDF_BUCKET if drift > 0 else -PDF_BUCKET
            remaining = abs(drift)
            for lid in ordered_ids:
                if remaining == 0:
                    break
                # Stop once the remainder sign flips — bumping further
                # would mean rounding a line away from its natural target
                # by more than $10, which defeats nearest-$10 rounding.
                if (drift > 0 and line_remainder[lid] <= 0) or \
                   (drift < 0 and line_remainder[lid] >= 0):
                    break
                pdf_line_totals[lid] += step
                remaining -= 1

        # Section totals: clean sum of the (now reconciled) rounded lines.
        for sec in sections_ordered:
            pdf_section_totals[sec["code"]] = sum(
                pdf_line_totals.get(ln.id, 0) for ln in sec["lines"]
            )

        # Top-sheet rows: re-derive from the section totals so they
        # match the detail pages exactly. Falls back to round-to-$10 of
        # the raw estimated for sections that have no detail rows
        # (Workers' Comp / Payroll Fee auto-injects).
        for row in top_sheet.get("rows", []):
            code = row.get("code")
            if code in pdf_section_totals:
                row["pdf_rounded_estimated"] = pdf_section_totals[code]
            else:
                row["pdf_rounded_estimated"] = round(float(row["estimated"]) / PDF_BUCKET) * PDF_BUCKET
        # Grand total: sum of the (now reconciled) rounded rows.
        ts_rows = top_sheet.get("rows", [])
        if ts_rows:
            top_sheet["pdf_rounded_grand_total_estimated"] = sum(
                r.get("pdf_rounded_estimated", r["estimated"]) for r in ts_rows
            )

    # Filter out zero-total lines + zero-total sections when suppress_zeros
    # is on. Done at the template-data level so the math (top sheet,
    # company fee, grand total) still uses the full budget — only the
    # printed list shrinks.
    #
    # Per user 2026-04-28: lines that are zero BECAUSE of a discount
    # (agent_pct → 100%, i.e. a comped / in-kind item) are meaningful and
    # must stay visible. Only suppress lines that are zero for "no rate /
    # no qty / no days" reasons. Heuristic: if rate * qty * days > 0 and
    # the line is non-labor with a discount, keep it; the discount column
    # will show 100% so the client sees "yes this was considered, 100%
    # discounted to zero".
    def _is_zero_due_to_discount(ln):
        try:
            r = float(ln.rate or 0); q = float(ln.quantity or 0); d = float(ln.days or 0)
            ag = float(ln.agent_pct or 0)
            return (r * q * d) > 0 and not ln.is_labor and ag > 0
        except (TypeError, ValueError):
            return False

    if suppress_zeros:
        for sec in sections_ordered:
            sec["lines"] = [
                ln for ln in sec["lines"]
                if round(float(line_results.get(ln.id, {}).get("est_total") or 0), 2) != 0
                or _is_zero_due_to_discount(ln)
            ]
        sections_ordered = [s for s in sections_ordered if s["lines"]]
        top_sheet["rows"] = [
            r for r in top_sheet["rows"]
            if round(float(r.get("estimated") or 0), 2) != 0
            or round(float(r.get("actual") or 0), 2) != 0
        ]

    # Column picker (2026-05-15). Defaults preserve previous behavior:
    # working view → Est + Work + Var; estimated view → Est only.
    # User can override via the Export Options modal — flags arrive
    # as ?col_est=1&col_work=1&col_act=1&col_var=1&var_basis=...
    # The variance basis controls what the Variance column subtracts:
    #   est_v_work  → Working - Estimated  (overrun while planning)
    #   work_v_act  → Working - Actual     (overrun in production)
    #   est_v_act   → Estimated - Actual   (overrun vs original plan)
    _any_col_param = any(k in request.args for k in
                         ('col_est', 'col_work', 'col_act', 'col_var'))
    if _any_col_param:
        col_est  = request.args.get('col_est')  == '1'
        col_work = request.args.get('col_work') == '1'
        col_act  = request.args.get('col_act')  == '1'
        col_var  = request.args.get('col_var')  == '1'
    else:
        # Legacy defaults — no params means no modal-invoked export.
        col_est  = True
        col_work = is_working_view
        col_act  = False
        col_var  = is_working_view
    var_basis = request.args.get('var_basis') or 'est_v_work'
    if var_basis not in ('est_v_work', 'work_v_act', 'est_v_act'):
        var_basis = 'est_v_work'

    # ── Pull the Estimated peer's Top Sheet so the PDF's Estimated
    # column reads from the actual Estimated budget instead of the
    # current budget's pre-fee snapshot. Without this, exporting from
    # Working / Actual put the Working pre-fee value in the Estimated
    # column (e.g. Travel showed $961.70 instead of $17.70). The in-app
    # Top Sheet already does this — mirror it here. User report
    # 2026-05-15. Same fallback as the in-app block: if no Estimated
    # peer exists, est_top_sheet collapses to top_sheet (degenerates to
    # the pre-fix behavior, which is correct when there IS no separate
    # Estimated budget).
    est_top_sheet = None
    est_section_lookup = {}
    if budget.budget_mode == 'estimated':
        # Exporting an Estimated budget — its OWN rollup IS the Estimated
        # column. Don't re-resolve a "current Estimated peer"; that could
        # pick a DIFFERENT Estimated version and make the PDF disagree
        # with the budget on screen (root cause of the active-vs-export
        # mismatch). Mirrors budget_view. 2026-05-20.
        est_top_sheet = top_sheet
    else:
      try:
        # Find the project's current Estimated peer budget. Two-step
        # lookup that mirrors the in-app view (app.py:3791): prefer
        # version_status='current'; fall back to any non-archived row
        # so projects whose Estimated peer was superseded but not
        # archived still resolve correctly.
        #
        # Critical: don't filter on is_actual — Estimated budgets in
        # this codebase either have is_actual=False or NULL, and a
        # naive `is_actual == False` SQL filter excludes NULL rows
        # entirely. Was the silent reason the previous fix (29d99c8)
        # didn't take for this user. 2026-05-19 v2.
        _est_peer = (Budget.query
                     .filter(Budget.project_id == pid,
                             Budget.budget_mode == 'estimated',
                             Budget.version_status == 'current')
                     .order_by(Budget.id.desc()).first())
        if not _est_peer:
            _est_peer = (Budget.query
                         .filter(Budget.project_id == pid,
                                 Budget.budget_mode == 'estimated',
                                 Budget.version_status != 'archived')
                         .order_by(Budget.id.desc()).first())
        if _est_peer and _est_peer.id != budget.id:
            _eb_lines = (BudgetLine.query
                         .filter_by(budget_id=_est_peer.id)
                         .order_by(BudgetLine.account_code,
                                   BudgetLine.sort_order).all())
            _eb_profile = _est_peer.payroll_profile
            _eb_pw_start = (_est_peer.payroll_week_start
                            if _est_peer.payroll_week_start is not None
                            else (_eb_profile.payroll_week_start if _eb_profile else 6))
            _eb_fringe = get_fringe_configs(db.session, pid)
            est_top_sheet = calc_top_sheet(
                _est_peer, _eb_lines, _eb_fringe, {},
                _eb_profile, _eb_pw_start,
            )
        else:
            est_top_sheet = top_sheet  # current budget IS the Estimated
      except Exception as _eee:
        logging.warning(f"[export_pdf] est_top_sheet build failed: {_eee}")
        est_top_sheet = top_sheet
    for _r in (est_top_sheet.get("rows") if est_top_sheet else []) or []:
        est_section_lookup[_r["code"]] = _r

    # ── Version labels for the budgets represented in this export ──────
    # The PDF compares an Estimated column against Working/Actual; show the
    # actual version of EACH budget whose column appears so the export is
    # unambiguous about exactly which versions were compared. (User 2026-06-03.)
    def _ver_str(b):
        if not b:
            return None
        lbl = getattr(b, 'version_label', None)
        if lbl:
            return str(lbl)
        n = getattr(b, 'version_number', None)
        return ('v%d' % n) if n else None
    est_budget_obj = (budget if budget.budget_mode == 'estimated'
                      else (_est_peer if ('_est_peer' in locals() and _est_peer) else budget))
    est_ver  = _ver_str(est_budget_obj)
    work_ver = _ver_str(budget) if is_working_view else None
    work_ver_label = ('Actual' if budget.budget_mode == 'actual' else 'Working')

    # ── Per-person travel/per-diem mirror rows (opt-in PDF export)
    # Reuses compute_travel_mirror_per_line — same helper the in-app
    # Budget tab uses to render the small italic "↪ Hotel — Crew /
    # ↪ Flights — Crew / ↪ Per Diem" rows under each labor person.
    # Gated by ?travel_notes=1 from the Export Options modal so the
    # default export stays compact. User request 2026-05-19: "I can
    # see, like, little hotel flights per diems, all of that. Can
    # that go out on the exports as well?". 2026-05-19.
    include_travel_notes = (request.args.get('travel_notes') == '1')
    travel_mirror_by_line = {}
    if include_travel_notes:
        try:
            from budget_calc import compute_travel_mirror_per_line
            _labor_lines = [ln for ln in lines if ln.is_labor]
            # Pull schedule days for this budget+mode. Same query
            # signature sync_schedule_driven_lines uses so the
            # per-person split reconciles with the aggregate.
            from sqlalchemy import or_ as _or_pdf_sd
            _sd_pdf = ScheduleDay.query.filter(
                ScheduleDay.budget_id == bid,
                _or_pdf_sd(ScheduleDay.schedule_mode == sched_mode,
                           ScheduleDay.schedule_mode.is_(None))
            ).all()
            travel_mirror_by_line = compute_travel_mirror_per_line(
                budget, _labor_lines, _sd_pdf, all_lines=lines)
        except Exception as _tm_e:
            logging.warning(f"[export_pdf] travel-mirror compute failed: {_tm_e}")

    html_str = render_template("budget_pdf.html",
        project=project,
        budget=budget,
        top_sheet=top_sheet,
        est_top_sheet=est_top_sheet,
        est_section_lookup=est_section_lookup,
        detail_mode=detail_mode,
        dispersed=dispersed,
        company_settings=company_settings,
        is_working_view=is_working_view,
        sections_ordered=sections_ordered,
        line_results=line_results,
        fee_m=fee_m,
        pdf_line_totals=pdf_line_totals,        # rounded dispersed line totals
        pdf_section_totals=pdf_section_totals,  # rounded dispersed section sums
        suppress_zeros=suppress_zeros,
        col_est=col_est, col_work=col_work, col_act=col_act, col_var=col_var,
        var_basis=var_basis,
        include_travel_notes=include_travel_notes,
        travel_mirror_by_line=travel_mirror_by_line,
        est_ver=est_ver, work_ver=work_ver, work_ver_label=work_ver_label,
        today=date.today(),
    )

    pdf_bytes = WeasyprintHTML(string=html_str, base_url=request.host_url).write_pdf()
    mode_label = "Working" if is_working_view else "Estimated"
    detail_label = "_detail" if detail_mode else "_topsheet"
    # If this is a sub-budget slice, tag the filename so the client
    # immediately knows what they got (vs the full budget export).
    sb_label = f"_{sub_budget_obj.name.replace(' ', '_')}" if sub_budget_obj else ""
    fname = f"{project.name.replace(' ', '_')}_{budget.name.replace(' ', '_')}{sb_label}_{mode_label}{detail_label}.pdf"
    return Response(
        pdf_bytes,
        mimetype="application/pdf",
        headers={"Content-Disposition": _content_disposition_attachment(fname)}
    )


# ════════════════════════════════════════════════════════════════════════
# Client estimate portal — send a budget as an estimate; client reviews &
# approves at a public /e/<token> link. (User 2026-06-03.)
# ════════════════════════════════════════════════════════════════════════

def _estimate_version_label(budget):
    mode_word = 'Working' if budget.budget_mode in ('working', 'actual') else 'Estimated'
    if budget.budget_mode == 'actual':
        mode_word = 'Actual'
    lbl = getattr(budget, 'version_label', None)
    if not lbl and getattr(budget, 'version_number', None):
        lbl = 'v%d' % budget.version_number
    # Always show a version number — a budget that predates versioning (no
    # label/number) is the first version. Better than a bare "Estimated".
    # (User 2026-06-04.)
    if not lbl:
        lbl = 'v1'
    return f"{mode_word} {lbl}".strip()


def _build_estimate_snapshot(project, budget, detail_mode):
    """Freeze the budget's section/line totals + presentation meta at send
    time, so the client always sees exactly what was sent and the approval is
    bound to this version even if the budget changes later. (User 2026-06-03.)"""
    from budget_calc import FP_COA_SECTIONS
    lines = (BudgetLine.query.filter_by(budget_id=budget.id)
             .order_by(BudgetLine.account_code, BudgetLine.sort_order).all())
    fringe_cfgs = get_fringe_configs(db.session, project.id)
    profile = budget.payroll_profile
    pw_start = (budget.payroll_week_start if budget.payroll_week_start is not None
                else (profile.payroll_week_start if profile else 6))
    sched_mode = 'working' if budget.budget_mode in ('working', 'actual') else 'estimated'

    # Use the SAME Top Sheet calc the on-screen budget + PDF use, so the totals
    # the client sees match exactly. Summing raw line totals (the old approach)
    # omitted the company fee, fringes rolled at section level, workers' comp,
    # payroll fee and production insurance — so the grand total was wrong.
    # (User 2026-06-04.)
    ts = calc_top_sheet(budget, lines, fringe_cfgs, {}, profile, pw_start)
    grand = round(float(ts.get("grand_total_estimated") or 0), 2)
    dispersed = bool(ts.get("company_fee_dispersed"))
    fee = round(float(ts.get("company_fee") or 0), 2)

    sections = []
    for row in ts.get("rows", []):
        sections.append({
            "code": row.get("code"),
            "name": row.get("account") or '',
            "total": round(float(row.get("estimated") or 0), 2),
            "lines": [],
        })
    # When the company fee is NOT dispersed it's a separate top-sheet line; add
    # it so the sections sum to the grand total. (Dispersed → already folded into
    # each section's total, so no separate line.)
    if not dispersed and fee:
        sections.append({"code": 99999, "name": "Production Company Fee",
                         "total": fee, "lines": []})

    # Optional per-line breakdown under each section (best-effort: section-level
    # adds like fringe / WC / fee live at the section total, not on a line).
    if detail_mode:
        def _sec_for(code):
            best = None
            for start, _ in FP_COA_SECTIONS:
                if code is not None and code >= start:
                    best = start
                else:
                    break
            return best
        by_code = {s["code"]: s for s in sections}
        for ln in lines:
            if getattr(ln, 'is_header', False):
                continue
            sdict = by_code.get(_sec_for(ln.account_code))
            if not sdict:
                continue
            if ln.use_schedule:
                sched = ScheduleDay.query.filter_by(budget_line_id=ln.id, schedule_mode=sched_mode).all()
                res = calc_line_from_schedule(ln, sched, fringe_cfgs, profile, pw_start)
            else:
                res = calc_line(ln, fringe_cfgs)
            sdict["lines"].append({
                "code": ln.account_code,
                "desc": (ln.description or '').strip(),
                "total": round(float((res or {}).get('est_total') or 0), 2)})

    cs = CompanySettings.query.get(1) or CompanySettings()
    company_addr = [getattr(cs, 'address_line1', None), getattr(cs, 'address_line2', None),
                    ', '.join([x for x in [getattr(cs, 'city', None), getattr(cs, 'state', None),
                                           getattr(cs, 'zip_code', None)] if x])]
    snap = {
        "project_name": project.name,
        "version_label": _estimate_version_label(budget),
        "date": date.today().isoformat(),
        "prepared_by": getattr(budget, 'prepared_by', None),
        "prepared_by_title": getattr(budget, 'prepared_by_title', None),
        "prepared_by_email": getattr(budget, 'prepared_by_email', None),
        "prepared_by_phone": getattr(budget, 'prepared_by_phone', None),
        "client_name": getattr(budget, 'client_name', None),
        "company": {
            "name": getattr(cs, 'company_name', None),
            "address": [a for a in company_addr if a],
            "phone": getattr(cs, 'phone', None),
            "email": getattr(cs, 'email', None),
        },
        "detail_mode": bool(detail_mode),
        "grand_total": round(grand, 2),
        "sections": sections,
    }
    return snap, round(grand, 2)


@app.route("/projects/<int:pid>/budget/<int:bid>/estimate/share", methods=["POST"])
@login_required
def estimate_share_create(pid, bid):
    """Create a client-facing estimate share for this budget. Freezes a
    snapshot, returns a public link, and optionally emails the client.
    (User 2026-06-03.)"""
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access or access.role not in ('owner', 'collaborator', 'editor'):
            return jsonify({"error": "Forbidden"}), 403
    project = ProjectSheet.query.get_or_404(pid)
    budget = Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    body = request.get_json(silent=True) or {}
    client_name = (body.get('client_name') or '').strip()[:200] or None
    client_email = (body.get('client_email') or '').strip()[:200] or None
    detail_mode = bool(body.get('detail_mode'))
    do_email = bool(body.get('send_email')) and bool(client_email)

    try:
        snap, grand = _build_estimate_snapshot(project, budget, detail_mode)
    except Exception as e:
        logging.exception("estimate snapshot failed")
        return jsonify({"error": "Could not build estimate snapshot", "detail": type(e).__name__}), 500

    import json as _json
    from datetime import timedelta as _td
    token = secrets.token_urlsafe(32)
    share = EstimateShare(
        project_id=pid, budget_id=bid, token=token,
        client_name=client_name, client_email=client_email,
        detail_mode=detail_mode, version_label=snap.get("version_label"),
        snapshot_json=_json.dumps(snap), grand_total=grand,
        status='sent', created_by_user_id=current_user.id,
        sent_at=datetime.utcnow(),
        expires_at=datetime.utcnow() + _td(days=90))
    db.session.add(share)
    db.session.commit()

    link = url_for('estimate_portal', token=token, _external=True)

    emailed = False
    email_error = None
    if do_email:
        if not app.config.get('MAIL_USERNAME'):
            email_error = "Email isn't configured on the server (MAIL_USERNAME unset) — use the copyable link instead."
        else:
            who = client_name or "there"
            subj = f"{project.name} — Estimate for your review"
            bodytxt = (f"Hi {who},\n\n"
                       f"Please review the estimate for {project.name} "
                       f"({snap.get('version_label')}). You can view and approve it here:\n\n"
                       f"{link}\n\n"
                       f"Estimated total: ${grand:,.2f}\n\n"
                       f"Thank you,\n"
                       f"{snap['company'].get('name') or (budget.prepared_by or '')}")
            emailed = _send_email(client_email, subj, bodytxt)
            if emailed:
                share.emailed = True
                db.session.commit()
            else:
                email_error = "Email send failed — use the copyable link instead."

    # Notify the project's Super/Admin audience that an estimate went out.
    try:
        _budget_link = url_for('budget_view', pid=pid, bid=bid, _external=True)
        _who = current_user.name or current_user.email
        _notify_project_event(
            pid,
            f"Estimate sent — {project.name} ({snap.get('version_label')})",
            (f"{_who} sent an estimate to the client for {project.name}.\n\n"
             f"Version: {snap.get('version_label')}\n"
             f"Client: {client_name or '—'}"
             + (f" <{client_email}>" if client_email else "") + "\n"
             f"Estimated total: ${grand:,.2f}\n"
             f"Emailed to client: {'yes' if emailed else 'no (link shared manually)'}\n\n"
             f"Open the budget: {_budget_link}"))
    except Exception:
        logging.warning("estimate-sent notify failed", exc_info=True)

    return jsonify({"ok": True, "share_id": share.id, "token": token, "link": link,
                    "emailed": emailed, "email_error": email_error,
                    "version_label": snap.get("version_label"),
                    "grand_total": grand})


