# DOCS MODULE — Receipt / Document Upload
# ─────────────────────────────────────────────────────────────────────────────

def _docs_accessible_projects(user):
    """Return active ProjectSheet rows visible to this user for docs."""
    active_filter = (ProjectSheet.status == 'active')
    if user.role in ('super_admin', 'admin'):
        return ProjectSheet.query.filter(active_filter).order_by(ProjectSheet.name).all()
    owned = (db.session.query(ProjectSheet)
             .join(ProjectAccess, ProjectAccess.project_id == ProjectSheet.id)
             .filter(ProjectAccess.user_id == user.id, active_filter)
             .order_by(ProjectSheet.name).all())
    return owned


@app.route("/docs/")
@login_required
def docs_dashboard():
    projects = _docs_accessible_projects(current_user)
    # Attach upload counts
    counts = {}
    if projects:
        pids = [p.id for p in projects]
        rows = (db.session.query(DocUpload.project_id, func.count(DocUpload.id))
                .filter(DocUpload.project_id.in_(pids))
                .group_by(DocUpload.project_id).all())
        counts = {pid: cnt for pid, cnt in rows}
    return render_template("docs_dashboard.html", projects=projects, counts=counts)


@app.route("/docs/<int:pid>/")
@login_required
def docs_project(pid):
    project = ProjectSheet.query.get_or_404(pid)
    # Access check
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access:
            abort(403)
    uploads = (DocUpload.query
               .filter_by(project_id=pid)
               .filter(DocUpload.status != 'deleted')   # Trash (2026-06-11)
               .order_by(DocUpload.uploaded_at.desc()).all())
    # Pass latest budget for tab bar (docs_only users won't see budget tabs)
    budget = Budget.query.filter_by(project_id=pid).order_by(Budget.created_at.desc()).first()
    return render_template("docs_upload.html", project=project, uploads=uploads, budget=budget)


@app.route("/upload", methods=["GET"])
@login_required
def mobile_upload():
    projects = _docs_accessible_projects(current_user)
    return render_template("mobile_upload.html", projects=projects)


@app.route("/docs/<int:pid>/upload", methods=["POST"])
@login_required
def docs_upload_post(pid):
    project = ProjectSheet.query.get_or_404(pid)
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access:
            return jsonify({"error": "Forbidden"}), 403

    f = request.files.get("file")
    if not f or not f.filename:
        return jsonify({"error": "No file provided"}), 400

    import hashlib, uuid as _uuid
    data = f.read()
    file_hash = hashlib.sha256(data).hexdigest()

    # Duplicate detection: hash match against an existing row in this
    # project that actually has a file in Dropbox. The strict rule —
    # `filed_dropbox_path IS NOT NULL` — kills ghost matches in two
    # failure modes:
    #   1. status='error' rows (Veryfi connection reset, OOM, etc.)
    #   2. partial-failure rows where OCR succeeded but the Dropbox
    #      filing step failed (status may be 'done' or 'review' but
    #      no file actually landed). Without this guard a re-upload
    #      gets flagged Duplicate against a phantom row.
    # `is_duplicate_of` carries the original upload id so the UI can
    # link back to the master copy.
    duplicate_of = (
        DocUpload.query
        .filter_by(project_id=pid, file_hash=file_hash)
        .filter(DocUpload.filed_dropbox_path.isnot(None))
        # Exclude review rows: they point at _UPLOADS_PENDING/, not a
        # real processed location. We don't want a not-yet-confirmed
        # upload to ghost-flag a fresh retry as a duplicate.
        .filter(DocUpload.status != 'review')
               .filter(DocUpload.status != 'deleted')
        .first()
    )

    content_type = f.content_type or "application/octet-stream"
    ext = os.path.splitext(f.filename)[1].lower() if f.filename else ""
    # r2_key kept as a unique filing id (for DocUpload.r2_key column).
    # The actual R2 upload was removed — source of truth is Dropbox.
    r2_key = f"docs/{pid}/{_uuid.uuid4().hex}{ext}"

    # Project must have a Dropbox folder set up for the Analyzer to file
    # to. If it doesn't, bail early so we don't save a ghost upload row.
    if not project.dropbox_folder:
        return jsonify({
            "error": "Project has no Dropbox folder configured — cannot file."
        }), 500

    # ── FP Document Analyzer integration (2026-04-20) ────────────────────
    # Route every upload through the embedded fp_analyzer: Veryfi OCR →
    # doc-type detection → auto-file to the correct 01_ADMIN subfolder
    # when confidence ≥ threshold. Low-confidence docs come back as
    # status='review' and the user finishes filing via the review UI.
    import re as _re
    from datetime import datetime as _dt
    from fp_analyzer import analyze_and_file_single
    import json as _json

    _raw_user = (getattr(current_user, 'name', None)
                 or (current_user.email or '').split('@')[0]
                 or 'unknown')
    _safe_user = _re.sub(r"[^\w\- ]", "", _raw_user) or "unknown"

    # Capture the size BEFORE running the analyzer so we can safely
    # release the bytes after the route finishes (the DocUpload row at
    # the bottom of this function only needs file_size, not the bytes
    # themselves).
    _data_size = len(data)

    try:
        result = analyze_and_file_single(
            file_bytes=data,
            filename=f.filename,
            project_name=project.dropbox_folder,   # Analyzer files under /{ops_root}/{project_name}/...
            user_name=_safe_user,
        )
    except Exception as _ae:
        logging.exception("Analyzer pipeline crashed")
        return jsonify({"error": f"Analyzer failed: {_ae}"}), 500
    # Release the file bytes now that the analyzer has consumed them
    # (it copies bytes into a temp file + Veryfi request internally).
    # Per user 2026-04-29: reduces peak working set so concurrent
    # uploads don't OOM Render's 512 MB worker. gc.collect runs at the
    # bottom of the route after the DB row is committed, NOT in a
    # finally block — earlier finally placement deleted `data` before
    # the DocUpload row was built and broke every upload with
    # UnboundLocalError on len(data).
    try:
        del data
    except Exception:
        pass

    status_map = {
        "filed":         "done",          # auto-filed to correct folder
        "needs_review":  "review",        # low-confidence → user picks in review UI
        "error":         "error",         # OCR / conversion failure
    }
    upload_status = status_map.get(result.get("status"), "error")

    # Extract structured OCR data from the Veryfi response so we can
    # display vendor/amount/date on the docs dashboard. The analyzer
    # now puts the raw vr on the result dict regardless of filed vs.
    # needs_review status, so high-confidence uploads also get their
    # extracted data stored on the row (was a bug — previously only
    # review rows kept the OCR data).
    vr = result.get("vr") or {}

    vendor_name = None
    amount      = None
    doc_date    = None
    doc_number  = None
    if vr:
        v = vr.get("vendor") or {}
        vendor_name = v.get("name") or v.get("raw_name")
        try:
            amount = float(vr.get("total")) if vr.get("total") is not None else None
        except Exception:
            amount = None
        try:
            from datetime import datetime as _dt_mod
            _d = vr.get("date") or ""
            doc_date = _dt_mod.strptime(_d[:10], "%Y-%m-%d").date() if _d else None
        except Exception:
            doc_date = None
        # Pull whichever doc-number-style field Veryfi extracted. We
        # don't yet know the user-confirmed type at this point so we
        # take the first available one — the modal will show it under
        # the right label depending on the doc type.
        doc_number = (vr.get("invoice_number")
                      or vr.get("purchase_order_number")
                      or vr.get("tax_id")
                      or vr.get("ein")
                      or None)
        if doc_number:
            doc_number = str(doc_number)[:100]
    from fp_analyzer import extract_card_last4 as _extract_card4
    card_last4 = _extract_card4(vr) if vr else None

    # Receipt detail for tax-credit reporting — Veryfi already returns subtotal /
    # tax / tip and the merchant address/phone; break them out so tip can be
    # excluded and name+address shown on submissions. (User 2026-07.)
    def _vmoney(x):
        try:
            return round(float(x), 2) if x not in (None, '', 'null') else None
        except (TypeError, ValueError):
            return None
    _v_ven   = (vr.get("vendor") or {}) if vr else {}
    r_subtotal = _vmoney(vr.get("subtotal")) if vr else None
    r_tax      = _vmoney(vr.get("tax")) if vr else None
    r_tip      = _vmoney(vr.get("tip")) if vr else None
    r_maddr    = (str(_v_ven.get("address"))[:300] if isinstance(_v_ven, dict) and _v_ven.get("address") else None)
    r_mphone   = (str(_v_ven.get("phone_number"))[:40] if isinstance(_v_ven, dict) and _v_ven.get("phone_number") else None)

    # Foreign-currency receipts → convert to USD by the receipt's date so the
    # ledger + matching use USD. Original foreign figure is kept; if conversion
    # isn't possible (unsupported currency / no date / fetch fail) we keep the
    # original amount and flag a note. (User 2026-06-11.)
    fx_original_amount = None
    fx_original_currency = None
    fx_note = None
    if vr and amount is not None:
        _ccy = _normalize_ccy(vr.get("currency_code"))
        if _ccy and _ccy != 'USD':
            fx_original_amount = amount
            fx_original_currency = _ccy
            _usd, _rate, _ = _convert_to_usd(amount, _ccy,
                                             doc_date.isoformat() if doc_date else None)
            if _usd is not None:
                fx_note = (f"Converted {fx_original_amount:,.2f} {_ccy} → "
                           f"${_usd:,.2f} @ {_rate:.5f} on {doc_date}")
                amount = _usd
            else:
                fx_note = (f"Foreign receipt ({_ccy}) — auto-conversion unavailable; "
                           f"amount is still {_ccy}, set USD manually")

    # Late-stage duplicate re-check. Catches the race where two parallel
    # POSTs for the same file both pass the pre-analysis duplicate query
    # (because neither has committed yet), then both file to Dropbox.
    # By the time we get here, the first request has typically already
    # committed its row — so the second one finds it. The second upload's
    # filed file then gets routed to /_DUPLICATES/ below, instead of
    # silently producing two clean copies.
    if not duplicate_of:
        duplicate_of = (
            DocUpload.query
            .filter_by(project_id=pid, file_hash=file_hash)
            .filter(DocUpload.filed_dropbox_path.isnot(None))
            .filter(DocUpload.status != 'review')
               .filter(DocUpload.status != 'deleted')
            .first()
        )

    # Persist the upload row with whatever we got back from the Analyzer.
    upload = DocUpload(
        project_id=pid,
        uploader_id=current_user.id,
        r2_key=r2_key,
        original_filename=f.filename,
        file_size=_data_size,
        content_type=content_type,
        file_hash=file_hash,
        status=upload_status,
        veryfi_data=_json.dumps(vr) if vr else None,
        vendor=vendor_name,
        amount=amount,                       # USD (converted if foreign)
        original_amount=fx_original_amount,  # foreign figure, if any
        original_currency=fx_original_currency,
        note=fx_note,
        doc_date=doc_date,
        doc_number=doc_number,
        card_last4=card_last4,
        subtotal=r_subtotal, tax=r_tax, tip=r_tip,
        merchant_address=r_maddr, merchant_phone=r_mphone,
        # confidence column is 0-100; Analyzer returns 0-1
        confidence=round(float(result.get("confidence") or 0) * 100, 2),
        category=result.get("doc_type"),
        veryfi_category=(vr.get("category") if vr else None),
        filed_filename=result.get("new_filename") or None,
        # For status='done': filed_path is the final processed location.
        # For status='review': fall back to staged_path so /docs/upload/
        # <uid>/raw can still serve the file from _SOURCE_ARCHIVE/ for
        # the preview modal. filed_at stays NULL so the UI knows the
        # doc isn't actually filed yet.
        filed_dropbox_path=result.get("filed_path") or result.get("staged_path"),
        filed_at=_dt.utcnow() if result.get("filed_path") else None,
        # Mission-critical fail-safe (2026-04-30): the source archive
        # path always points to the original uploaded bytes in Dropbox
        # at _SOURCE_ARCHIVE/, regardless of whether the processed copy
        # was filed, sent to review, or errored. The archive is never
        # deleted by the app — it's the durable source-of-truth.
        source_archive_path=result.get("staged_path"),
        # byte-hash match ONLY. A Dropbox autorename (" (1)" suffix) means a
        # DIFFERENT receipt happened to produce the same vendor/date/total
        # filename — NOT a duplicate. Treating it as one buried real spend with
        # no transaction. (Code review 2026-06-04.)
        is_duplicate=bool(duplicate_of),
        # Record WHICH upload the bytes matched so the docs UI can link
        # back and offer Keep-both / It's-a-duplicate. Only the exact
        # hash match (duplicate_of) carries an id; the soft filename-
        # collision signal (result['duplicate']) has no specific peer.
        duplicate_of_id=duplicate_of.id if duplicate_of else None,
    )
    db.session.add(upload)
    db.session.commit()

    # AI data cleanup (vendor normalization + extraction sanity). Advisory and
    # fail-open; runs BEFORE the auto-Transaction so the charge inherits the
    # clean vendor name. Auto-applies ≥0.70, else queues a review flag. (2026-06-18.)
    try:
        _ai_clean_document(upload)
        db.session.commit()
    except Exception as _cle:
        logging.warning(f"[docs/upload] ai cleanup failed for upload #{upload.id}: {_cle}")
        db.session.rollback()

    # Travel-doc intelligence: if this looks like a hotel/flight/car reservation,
    # auto-extract the confirmation # + travel details (suggestion only — the user
    # applies it to a person + travel day in the doc-detail Travel panel). Advisory
    # and fail-open. (User 2026-06-22.)
    try:
        if _looks_like_travel(upload):
            _ai_extract_travel(upload)
            db.session.commit()
    except Exception as _tle:
        logging.warning(f"[docs/upload] travel extract failed for upload #{upload.id}: {_tle}")
        db.session.rollback()

    # ── Auto-create a Transaction row for every doc upload (2026-04-30) ─
    # Each receipt / invoice / etc. that lands in Docs becomes an
    # immediate Actuals candidate: a Transaction with source='doc_upload'
    # and doc_upload_id set. budget_line_id stays NULL — the user picks
    # the line from the Actuals tab, which triggers the Working→Actual
    # auto-clone the first time.
    #
    # We skip duplicate-flagged uploads (already filed as a duplicate
    # of an earlier upload) and error-status uploads (no real file).
    # Tax forms / contracts / releases also skipped because they aren't
    # spend events — they're paperwork that lives in Docs but doesn't
    # belong on the actuals ledger.
    # Doc types that DO NOT create a Transaction at upload time:
    #   tax_form / contract / release / legal / insurance / misc → pure
    #     paperwork; not a spend event.
    #   estimate / quote / purchase_order → FORECAST documents (Working
    #     budget territory). They should feed planning, not actuals.
    #     Slice 3+ will surface a "Convert to Working line" affordance
    #     so the user can turn an estimate into a budgeted line item
    #     with the doc as backing paper. Until then they live as
    #     reference docs only.
    _NON_LEDGER_TYPES = {'tax_form', 'contract', 'release', 'legal',
                         'insurance', 'misc', 'employee_vendor_doc',
                         'estimate', 'quote', 'purchase_order'}
    auto_txn = None
    if (upload.status in ('done', 'review')
            and not upload.is_duplicate
            and (upload.category or '') not in _NON_LEDGER_TYPES):
        try:
            from datetime import datetime as _dt_mod
            _txn_date = upload.doc_date.isoformat() if upload.doc_date else None
            auto_txn = Transaction(
                project_id          = pid,
                source              = 'doc_upload',
                doc_upload_id       = upload.id,
                vendor              = upload.vendor,
                amount              = upload.amount,
                txn_date            = _txn_date,
                card_last4          = upload.card_last4,
                is_expense          = True,
                note                = upload.note,
                # No account_code yet — user picks budget line in Actuals.
                # match_status stays 'unmatched' until the user confirms.
                match_status        = 'unmatched',
                created_via_user_id = current_user.id if current_user.is_authenticated else None,
            )
            db.session.add(auto_txn)
            db.session.flush()
            # Advisory AI coding suggestion (2026-06-18). Fail-open: a model
            # hiccup must never block the upload. Stored on the txn; the user
            # sees a "✨ suggested" chip in Actuals and clicks Accept to code.
            try:
                _ai_suggest_code_for_txn(auto_txn)
            except Exception as _ae:
                logging.warning(f"[docs/upload] ai categorize failed for txn "
                                f"#{auto_txn.id}: {_ae}")
            # Cross-project claim: a receipt upload is an affirmative
            # "this expense belongs here" signal. Fire _sync_claim_state
            # so any QBO sibling on another project (same vendor + amount
            # + date within ±5d) gets claimed_by_project_id set and
            # not_project_expense=True, dropping it out of that project's
            # uncoded pile. Without this, user uploads a Lyft receipt to
            # Etoro and the same Lyft in FP General Ops sits there
            # uncoded until they remember to fix it.
            try:
                _sync_claim_state(auto_txn)
            except Exception as _ce:
                logging.warning(f"[docs/upload] cross-project claim failed "
                                f"for txn #{auto_txn.id}: {_ce}")
            db.session.commit()
            logging.info(f"[docs/upload] Created Transaction #{auto_txn.id} "
                         f"from DocUpload #{upload.id} (vendor={upload.vendor!r}, "
                         f"amount={upload.amount}, doc_date={_txn_date})")
        except Exception as _te:
            logging.warning(f"[docs/upload] Auto-Transaction creation failed for "
                            f"upload #{upload.id}: {_te}")
            db.session.rollback()
            auto_txn = None

    # Activity log
    try:
        _log_activity(
            action='create', entity_type='doc_upload',
            entity_id=upload.id,
            entity_label=(upload.filed_filename or upload.original_filename or f'Upload #{upload.id}'),
            project_id=pid,
            before=None,
            after={'status': upload.status, 'vendor': upload.vendor,
                   'amount': float(upload.amount or 0),
                   'category': upload.category,
                   'transaction_id': auto_txn.id if auto_txn else None},
            note=f'Uploaded "{upload.original_filename}"' +
                 (f' (filed as {upload.category})' if upload.filed_dropbox_path else '') +
                 (f' → Actuals txn #{auto_txn.id}' if auto_txn else ''))
    except Exception: pass

    # If this upload's content hash matched an earlier row, FLAG it for
    # review instead of auto-burying it (per user 2026-05-29). The file
    # stays filed in its normal type-folder (Dropbox already gave it a
    # " (1)" suffix if the name collided), so a genuinely-separate but
    # byte-identical recurring invoice — same vendor / amount / date,
    # no invoice number — is never silently hidden. The docs UI shows a
    # "Possible duplicate of #X" banner with Keep-both / It's-a-duplicate
    # actions; /docs/upload/<uid>/resolve-duplicate does the burying only
    # when the user confirms. Veryfi can't disambiguate byte-identical
    # files (identical input → identical OCR), so user input is the only
    # reliable signal here.
    if duplicate_of and result.get("filed_path"):
        upload.note = (f"Possible duplicate of upload #{duplicate_of.id} "
                       f"({duplicate_of.filed_filename or duplicate_of.original_filename}). "
                       f"Review: keep both, or confirm it's a duplicate.")
        db.session.commit()
        logging.info(f"[DOCS] upload #{upload.id}: flagged as possible duplicate "
                     f"of #{duplicate_of.id} (awaiting review, NOT auto-buried)")

    # Force any remaining Pillow/Veryfi response buffers to release
    # before responding. Safe here because all DB work is committed.
    try:
        import gc as _gc
        _gc.collect()
    except Exception:
        pass

    # Build a structured client response so the upload UI can show the
    # correct state (filed with path, or needs review, or error).
    # Common bag of fields surfaced to the JS so the freshly-prepended
    # row carries the same OCR-extracted data the server-rendered rows
    # do (used by the doc-detail modal to pre-populate vendor/amount/
    # doc_date without an extra round-trip).
    _ocr_fields = {
        "vendor":     upload.vendor,
        "amount":     float(upload.amount) if upload.amount is not None else None,
        "doc_date":   upload.doc_date.isoformat() if upload.doc_date else None,
        "doc_number": upload.doc_number,
    }
    if result.get("status") == "filed":
        _is_dup = bool(duplicate_of)
        return jsonify({
            # "review_dup" tells the upload UI this is a flagged-but-kept
            # possible duplicate (filed in place, awaiting Keep-both /
            # confirm), distinct from the old "duplicate" = buried state.
            "status":      "review_dup" if _is_dup else "ok",
            "upload_id":   upload.id,
            "filed_path":  upload.filed_dropbox_path,
            # Include the renamed filename so the JS prepend shows the
            # Analyzer's date/vendor/amount-formatted name instead of
            # falling back to the original (often random/uuid) filename.
            "new_filename":   upload.filed_filename or result.get("new_filename"),
            "filed_filename": upload.filed_filename,
            "doc_type":    result.get("doc_type"),
            "confidence":  result.get("confidence"),
            "duplicate":   _is_dup or bool(result.get("duplicate")),
            "duplicate_of": duplicate_of.id if duplicate_of else None,
            "message":     (f"Possible duplicate of #{duplicate_of.id} — filed, flagged for review."
                            if _is_dup
                            else f"Filed as {result.get('doc_type')} ({int((result.get('confidence') or 0) * 100)}% confidence)."),
            **_ocr_fields,
        }), 201
    if result.get("status") == "needs_review":
        return jsonify({
            "status":      "review",
            "upload_id":   upload.id,
            "doc_type":    result.get("doc_type"),
            "confidence":  result.get("confidence"),
            "new_filename": result.get("new_filename"),
            "message":     f"OCR complete but confidence too low to auto-file "
                           f"({int((result.get('confidence') or 0) * 100)}%). Review required.",
            **_ocr_fields,
        }), 202
    # status == 'error'
    return jsonify({
        "status":   "error",
        "upload_id": upload.id,
        "error":    result.get("error") or "Unknown analyzer error",
    }), 500


@app.route("/docs/upload/<int:uid>/retry-filing", methods=["POST"])
@login_required
def docs_upload_retry_filing(uid):
    """Retry filing an already-uploaded doc to Dropbox. Used when the initial
    upload succeeded to R2 but the Dropbox filing failed (common for legacy
    'pending' rows from before the current_user.username bug fix)."""
    upload = DocUpload.query.get_or_404(uid)
    # Access check
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(
            project_id=upload.project_id, user_id=current_user.id).first()
        if not access:
            return jsonify({"error": "Forbidden"}), 403
    if upload.status == 'filed':
        return jsonify({"ok": True, "already_filed": True,
                        "path": upload.filed_dropbox_path})

    project = ProjectSheet.query.get(upload.project_id)
    if not project or not project.dropbox_folder:
        return jsonify({"error": "Project has no Dropbox folder configured"}), 400

    # Re-fetch bytes from R2
    data, err = _r2_download(upload.r2_key)
    if err or data is None:
        return jsonify({"error": err or "R2 fetch failed"}), 500

    try:
        import re as _re
        from datetime import datetime as _dt
        uploader = User.query.get(upload.uploader_id)
        _raw_user = (getattr(uploader, 'name', None)
                     or (uploader.email or '').split('@')[0]
                     or 'unknown') if uploader else 'unknown'
        _safe_user = _re.sub(r"[^\w\- ]", "", _raw_user) or "unknown"
        _proj_root = f"/{project.dropbox_folder}" if _DBX_NAMESPACE_ID else f"{_DBX_OPS_ROOT}/{project.dropbox_folder}"
        dbx_filing_path = f"{_proj_root}/01_ADMIN/PROCESSED DOCUMENTS/{_safe_user}/{upload.original_filename}"
        _dbx = _dbx_client()
        from dropbox.files import WriteMode as _WM
        _dbx.files_upload(data, dbx_filing_path, autorename=True, mode=_WM('add'))
        upload.status = 'filed'
        upload.filed_dropbox_path = dbx_filing_path
        upload.filed_at = _dt.utcnow()
        db.session.commit()
        return jsonify({"ok": True, "path": dbx_filing_path})
    except Exception as e:
        logging.exception("Retry filing failed")
        return jsonify({"error": str(e)}), 500


@app.route("/docs/upload/<int:uid>/status")
@login_required
def docs_upload_status(uid):
    upload = DocUpload.query.get_or_404(uid)
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(
            project_id=upload.project_id, user_id=current_user.id).first()
        if not access:
            return jsonify({"error": "Forbidden"}), 403
    return jsonify({
        "id": upload.id,
        "status": upload.status,
        "original_filename": upload.original_filename,
        "filed_filename":    upload.filed_filename,
        "vendor": upload.vendor,
        "amount": float(upload.amount) if upload.amount else None,
        "doc_date": upload.doc_date.isoformat() if upload.doc_date else None,
        "confidence": float(upload.confidence) if upload.confidence else None,
        "category": upload.category,
        "doc_number": upload.doc_number,
        "card_last4": upload.card_last4,
        "note": upload.note,
        "crew_member_id":     upload.crew_member_id,
        "location_id":        upload.location_id,
        "is_duplicate": upload.is_duplicate,
        "filed_dropbox_path": upload.filed_dropbox_path,
        "travel": (json.loads(upload.travel_json) if upload.travel_json else None),
        "travel_extracted": bool(upload.travel_extracted_at),
    })


def _purge_old_trash(days=30):
    """Hard-delete /_TRASH/<YYYY-MM-DD>/ folders older than `days` days.

    Trash entries are organized by date-named folders (created on each
    delete via _trash_dropbox_paths). This walker lists those folders,
    parses the date from the name, hard-deletes any folder whose date
    is older than the cutoff. Best-effort; never raises. Returns
    {'deleted_folders': N, 'errors': [...]}.

    Idempotent — re-running same day is a no-op (folders already gone).
    """
    from datetime import date as _date, datetime as _dt_mod, timedelta as _td_mod
    cutoff = _date.today() - _td_mod(days=days)
    out = {'deleted_folders': 0, 'kept_folders': 0, 'errors': []}
    try:
        dbx = _dbx_client()
    except Exception as e:
        out['errors'].append(f"dbx init: {e}")
        return out
    try:
        res = dbx.files_list_folder("/_TRASH")
    except Exception as e:
        if "not_found" in str(e):
            return out  # no trash yet
        out['errors'].append(f"list /_TRASH: {e}")
        return out
    while True:
        for entry in res.entries:
            if not hasattr(entry, 'name') or hasattr(entry, 'size'):
                continue  # not a folder
            name = entry.name
            # Parse YYYY-MM-DD prefix from the folder name. The wipe
            # endpoint creates names like "2026-04-30_HHMMSS_<slug>";
            # the per-row delete uses just "YYYY-MM-DD".
            m = name[:10]
            try:
                folder_date = _dt_mod.strptime(m, "%Y-%m-%d").date()
            except ValueError:
                # Folder name doesn't start with a date — leave it alone.
                continue
            if folder_date < cutoff:
                try:
                    dbx.files_delete_v2(entry.path_lower)
                    out['deleted_folders'] += 1
                    logging.info(f"[trash purge] hard-deleted {entry.path_display} (age={(_date.today() - folder_date).days}d)")
                except Exception as _de:
                    out['errors'].append(f"delete {entry.path_display}: {_de}")
            else:
                out['kept_folders'] += 1
        if not res.has_more:
            break
        try:
            res = dbx.files_list_folder_continue(res.cursor)
        except Exception as e:
            out['errors'].append(f"list_continue: {e}")
            break
    return out


@app.route("/admin/trash/purge", methods=["POST"])
@login_required
def admin_trash_purge():
    """Hard-delete /_TRASH/ folders older than 30 days. Triggered
    manually by super-admins, or via a scheduled webhook (e.g. Render
    Cron Job). Returns counts; safe to call any time."""
    if current_user.role != 'super_admin':
        return jsonify({"error": "super admin only"}), 403
    days = int(request.args.get('days') or request.json.get('days', 30) if request.is_json else (request.args.get('days') or 30))
    result = _purge_old_trash(days=max(7, min(days, 365)))  # clamp 7–365 for safety
    return jsonify({"ok": True, "days": days, **result})


def _trash_dropbox_paths(paths, moves_out=None):
    """Move a list of Dropbox paths to /_TRASH/<YYYY-MM-DD>/ for delete
    operations. Returns count of successful moves. Best-effort; never
    raises. The trash folder uses today's date so a day's deletes
    cluster together in case the user wants to recover a file.
    If `moves_out` is a list, appends {"src","dest"} for each successful move —
    the soft-delete/restore path records these so /restore can move files back.
    (2026-06-11.)"""
    paths = [p for p in (paths or []) if p]
    if not paths:
        return 0
    try:
        dbx = _dbx_client()
    except Exception as _ce:
        logging.warning(f"[docs/delete] dbx init failed: {_ce}")
        return 0
    from datetime import datetime as _dt_mod
    trash_root = f"/_TRASH/{_dt_mod.utcnow().strftime('%Y-%m-%d')}"
    moved = 0
    for src in paths:
        # Strip the legacy ops prefix if running in namespace mode.
        norm = src
        _ops_prefix_str = (_DBX_OPS_ROOT or "").rstrip("/") if _DBX_NAMESPACE_ID else ""
        if _ops_prefix_str and norm.startswith(_ops_prefix_str + "/"):
            norm = norm[len(_ops_prefix_str):]
        safe_frag = src.lstrip('/').replace('/', '_')
        dest = f"{trash_root}/{safe_frag}"
        for path_try in (norm, src) if norm != src else (norm,):
            try:
                res = dbx.files_move_v2(path_try, dest, autorename=True)
                moved += 1
                if moves_out is not None:
                    # autorename may have altered dest — record the REAL one.
                    real_dest = getattr(getattr(res, 'metadata', None), 'path_display', None) or dest
                    moves_out.append({"src": path_try, "dest": real_dest})
                break
            except Exception as _me:
                if "not_found" in str(_me).lower():
                    # File was already gone — count as moved so the caller
                    # doesn't think the delete failed. Source bytes are
                    # not in Dropbox; nothing to trash.
                    logging.info(f"[docs/delete] {src} already gone in Dropbox")
                    break
                continue
    return moved


def _flag_person_doc_duplicate(upload):
    """If this employee/vendor person-doc (W-9, ID, driver's license, etc.)
    duplicates one the SAME person already has of the SAME sub-type, flag the
    newer copy is_duplicate + duplicate_of_id so it enters the compare/dup
    review (instead of silently piling up). Sub-type is stored in `vendor`.
    Returns the original's id if flagged, else None. (User 2026-06-02.)"""
    if (upload.category or '') != 'employee_vendor_doc':
        return None
    if not upload.crew_member_id or not (upload.vendor or '').strip():
        return None
    if upload.is_duplicate or upload.status == 'duplicate':
        return None
    sub = upload.vendor.strip().lower()
    peers = (DocUpload.query
             .filter(DocUpload.project_id == upload.project_id,
                     DocUpload.crew_member_id == upload.crew_member_id,
                     DocUpload.category == 'employee_vendor_doc',
                     DocUpload.id != upload.id,
                     DocUpload.is_duplicate == False,           # noqa: E712
                     DocUpload.status != 'duplicate')
             .all())
    match = next((d for d in peers if (d.vendor or '').strip().lower() == sub), None)
    if not match:
        return None
    # Lower id = the original; flag the newer as the duplicate.
    orig, dup = (match, upload) if match.id < upload.id else (upload, match)
    dup.is_duplicate    = True
    dup.duplicate_of_id = orig.id
    return orig.id


@app.route("/docs/<int:pid>/scan-person-duplicates", methods=["POST"])
@login_required
def docs_scan_person_duplicates(pid):
    """Find person-doc duplicates project-wide: same crew member + same sub-type
    (W-9/ID/etc.). Lowest-id kept as the original; the rest flagged for the
    compare/dup review. Dry-run by default; ?apply=1 to write. (User 2026-06-02.)"""
    if getattr(current_user, 'role', None) == 'viewer':
        return jsonify({"error": "Forbidden"}), 403
    ProjectSheet.query.get_or_404(pid)
    body = request.get_json(silent=True) or {}
    apply = (request.args.get('apply') == '1') or bool(body.get('apply'))
    rows = (DocUpload.query
            .filter(DocUpload.project_id == pid,
                    DocUpload.category == 'employee_vendor_doc',
                    DocUpload.crew_member_id.isnot(None),
                    DocUpload.status != 'duplicate')
            .all())
    groups = {}
    for d in rows:
        sub = (d.vendor or '').strip().lower()
        if not sub:
            continue
        groups.setdefault((d.crew_member_id, sub), []).append(d)
    flagged = []
    for grp in groups.values():
        if len(grp) <= 1:
            continue
        grp.sort(key=lambda x: x.id)
        orig = grp[0]
        for d in grp[1:]:
            if d.is_duplicate:
                continue
            flagged.append({"id": d.id, "duplicate_of": orig.id,
                            "crew_member_id": d.crew_member_id, "sub_type": d.vendor})
            if apply:
                d.is_duplicate = True
                d.duplicate_of_id = orig.id
    if apply and flagged:
        db.session.commit()
    return jsonify({"dry": (not apply), "applied": apply,
                    "groups_with_dupes": sum(1 for g in groups.values() if len(g) > 1),
                    "flagged": len(flagged), "sample": flagged[:25]})


@app.route("/docs/<int:pid>/scan-receipt-duplicates", methods=["POST"])
@login_required
def docs_scan_receipt_duplicates(pid):
    """Fuzzy duplicate scan for receipts/invoices — catches the SAME receipt
    saved as a different file (re-scan, screenshot vs PDF), which the byte-hash
    check on upload misses. Grouping priority per user 2026-06-16: amount first
    (most reliable OCR field), then date (within ±date_window days), then vendor
    similarity as corroboration (allowed to be blank/loose since vendor OCR is
    least reliable). Lowest-id kept as the original; the rest flagged
    is_duplicate=True (pending review) so they surface in the existing
    keep/confirm duplicate UI. Dry-run by default; ?apply=1 writes.
    (No perceptual image hashing yet — amount+date+vendor only.)"""
    if getattr(current_user, 'role', None) == 'viewer':
        return jsonify({"error": "Forbidden"}), 403
    ProjectSheet.query.get_or_404(pid)
    body = request.get_json(silent=True) or {}
    apply = (request.args.get('apply') == '1') or bool(body.get('apply'))
    try:
        date_window = max(0, int(body.get('date_window') or request.args.get('date_window') or 3))
    except (TypeError, ValueError):
        date_window = 3
    from actuals import _vendor_similarity
    rows = (DocUpload.query
            .filter(DocUpload.project_id == pid,
                    DocUpload.category.in_(('receipt', 'invoice')),
                    DocUpload.status.notin_(('duplicate', 'deleted')),
                    DocUpload.is_duplicate == False,        # noqa: E712
                    DocUpload.amount.isnot(None))
            .all())
    # Primary key: exact amount (to the cent).
    by_amt = {}
    for d in rows:
        try:
            by_amt.setdefault(round(float(d.amount), 2), []).append(d)
        except (TypeError, ValueError):
            continue
    flagged, groups_out = [], []
    for amt, grp in by_amt.items():
        if len(grp) < 2:
            continue
        grp.sort(key=lambda x: x.id)
        used = set()
        for i, a in enumerate(grp):
            if a.id in used:
                continue
            cluster = [a]
            for b in grp[i + 1:]:
                if b.id in used:
                    continue
                # Secondary: date proximity (both dated → within window; if a
                # date is missing, don't let that alone block the match).
                close = True
                if a.doc_date and b.doc_date:
                    close = abs((a.doc_date - b.doc_date).days) <= date_window
                # Tertiary: vendor corroboration (blank on either side = allow).
                av, bv = (a.vendor or '').strip(), (b.vendor or '').strip()
                vok = (not av or not bv) or _vendor_similarity(av, bv) >= 0.40
                if close and vok:
                    cluster.append(b)
                    used.add(b.id)
            if len(cluster) > 1:
                used.add(a.id)
                orig, dupes = cluster[0], cluster[1:]
                _meta = lambda x: {"id": x.id,
                                   "file": x.filed_filename or x.original_filename or f"Doc #{x.id}",
                                   "vendor": x.vendor, "date": x.doc_date.isoformat() if x.doc_date else None}
                groups_out.append({"amount": amt, "keeper": _meta(orig),
                                   "dupes": [_meta(x) for x in dupes]})
                for x in dupes:
                    flagged.append({"id": x.id, "duplicate_of": orig.id})
                    if apply:
                        x.is_duplicate = True
                        x.duplicate_of_id = orig.id
    if apply and flagged:
        db.session.commit()
        try:
            _log_activity(action='update', entity_type='doc_dup_scan', entity_id=pid,
                          entity_label='Receipt duplicate scan', project_id=pid,
                          note=f'Flagged {len(flagged)} possible receipt duplicate(s) in {len(groups_out)} group(s)')
        except Exception:
            pass
    return jsonify({"dry": (not apply), "applied": apply,
                    "groups": len(groups_out), "flagged": len(flagged),
                    "date_window": date_window, "sample_groups": groups_out[:40]})


def _apply_dup_resolution(upload, action, force=False, link_mode=None):
    """Apply one keep/confirm decision to a flagged upload. Mutates the row
    (+ session: txn add/delete, Dropbox move) but does NOT commit — the
    caller commits once. Returns (ok: bool, info: dict, error: str|None).
    Shared by the single-row route and the batch / group-review route.

    force=True (set when the user EXPLICITLY clicks "It's a dupe" and then
    confirms the coded-doc warning): bury even an assigned duplicate. Its own
    phantom doc_upload transaction is deleted (de-double-counts the ledger);
    any electronic charge matched to it is unlinked but keeps its own coding.
    (User 2026-06-17.)"""
    _peer = upload.duplicate_of_id
    if action == "keep":
        upload.is_duplicate    = False
        upload.duplicate_of_id = None
        upload.note = (f"Reviewed — confirmed distinct from #{_peer}. Kept."
                       if _peer else "Reviewed — kept.")
        # Create the deferred Actuals Transaction for ledger doc types so a
        # genuinely-separate spend shows up in Actuals.
        _NON_LEDGER_TYPES = {'tax_form', 'contract', 'release', 'legal',
                             'insurance', 'misc', 'employee_vendor_doc',
                             'estimate', 'quote', 'purchase_order'}
        made_txn = None
        if (upload.status in ('done', 'review')
                and (upload.category or '') not in _NON_LEDGER_TYPES):
            if not Transaction.query.filter_by(doc_upload_id=upload.id).first():
                try:
                    made_txn = Transaction(
                        project_id          = upload.project_id,
                        source              = 'doc_upload',
                        doc_upload_id       = upload.id,
                        vendor              = upload.vendor,
                        amount              = upload.amount,
                        txn_date            = upload.doc_date.isoformat() if upload.doc_date else None,
                        is_expense          = True,
                        note                = upload.note,
                        match_status        = 'unmatched',
                        created_via_user_id = (current_user.id if current_user.is_authenticated else None),
                    )
                    db.session.add(made_txn)
                    db.session.flush()
                except Exception:
                    made_txn = None
        return True, {"resolved": "keep", "upload_id": upload.id,
                      "txn_id": (made_txn.id if made_txn else None)}, None

    if action == "confirm":
        # SAFETY NET (user 2026-05-29): never bury a doc that's coded/assigned
        # to a budget line. A flagged duplicate is always the unassigned
        # newcomer — the earlier original is the one that carries the
        # assignment. If THIS doc has a transaction coded to a line, refuse:
        # the linked original must survive duplicate processing "no matter
        # what." (Normal flagged dupes have no transaction, so this is a
        # no-op for them; it only guards a deliberate mis-designation.)
        _assigned = (Transaction.query
                     .filter_by(doc_upload_id=upload.id)
                     .filter(db.or_(Transaction.budget_line_id.isnot(None),
                                    Transaction.account_code.isnot(None)))
                     .first())
        # Electronic charges (bank/CSV) currently matched to THIS copy — the
        # user must decide whether to unlink them or re-point them to the kept
        # original before we bury this copy. (User 2026-06-17.)
        _linked_charges = (Transaction.query
                           .filter(Transaction.doc_upload_id == upload.id,
                                   Transaction.source.in_(('qbo_sync', 'csv_import')))
                           .all())
        # The canonical copy of this set (same bytes, not itself a duplicate) —
        # the target for "re-point the charge to the original".
        keeper = None
        if upload.file_hash:
            keeper = (DocUpload.query
                      .filter(DocUpload.project_id == upload.project_id,
                              DocUpload.file_hash == upload.file_hash,
                              DocUpload.id != upload.id,
                              DocUpload.is_duplicate == False)   # noqa: E712
                      .order_by(DocUpload.id.asc()).first())
        if not keeper and upload.duplicate_of_id:
            keeper = DocUpload.query.get(upload.duplicate_of_id)

        if (_assigned or _linked_charges) and not force:
            # Don't hard-refuse — hand the UI everything it needs to prompt:
            # what it's coded to, which charges are linked, and the kept copy
            # it could re-point them to. UI retries with force + link_mode.
            _code = (_assigned.account_code_name
                     or (str(_assigned.account_code) if (_assigned and _assigned.account_code) else None)) if _assigned else None
            return False, {
                "needs_force": True,
                "coded_to": _code,
                "amount": (float(upload.amount) if upload.amount is not None else None),
                "linked_charges": [{
                    "tid": c.id, "vendor": c.vendor,
                    "amount": (float(c.amount) if c.amount is not None else None),
                    "date": c.txn_date,
                    "code": c.account_code_name or (str(c.account_code) if c.account_code else None),
                    "source": c.source,
                } for c in _linked_charges],
                "keeper": ({"id": keeper.id,
                            "filed": (keeper.filed_filename or keeper.original_filename)} if keeper else None),
            }, f"#{upload.id} is linked or coded — choose how to handle it before burying."

        # FORCE path. link_mode='transfer' re-points the linked charge(s) onto
        # the kept copy (so the charge keeps a receipt — the canonical one);
        # otherwise they're unlinked back to the pool by the cleanup below.
        transferred = 0
        if force and link_mode == 'transfer' and keeper and _linked_charges:
            for c in _linked_charges:
                c.doc_upload_id = keeper.id          # canonical copy now backs this charge
                transferred += 1
            # The kept copy's own phantom ledger row is now superseded by the
            # real charge — drop it so the spend isn't double-counted.
            try:
                Transaction.query.filter_by(doc_upload_id=keeper.id, source='doc_upload')\
                    .delete(synchronize_session=False)
            except Exception:
                pass
        moved_to = None
        if upload.filed_dropbox_path:
            try:
                _orig_path = upload.filed_dropbox_path
                _parent    = os.path.dirname(_orig_path) or "/"
                _dup_path  = f"{_parent}/_DUPLICATES/{os.path.basename(_orig_path)}"
                _mv = _dbx_client().files_move_v2(_orig_path, _dup_path, autorename=True)
                _final = getattr(getattr(_mv, 'metadata', None), 'path_display', None) or _dup_path
                upload.filed_dropbox_path = _final
                upload.filed_filename     = os.path.basename(_final)
                moved_to = _final
            except Exception as _de:
                logging.exception(f"[DOCS] confirm-duplicate move failed for #{upload.id}: {_de}")
                return False, {}, f"Could not move #{upload.id} to /_DUPLICATES/: {_de}"
        upload.status       = 'duplicate'
        upload.is_duplicate = True
        upload.note = (f"Confirmed duplicate of #{_peer}. Moved to /_DUPLICATES/."
                       if _peer else "Confirmed duplicate. Moved to /_DUPLICATES/.")
        # A confirmed duplicate isn't a real spend — drop the receipt's OWN
        # auto-created doc_upload txn. Scoped to source='doc_upload' so we never
        # delete a bank charge (qbo_sync/csv_import) that was suggested-matched
        # to this receipt — that charge is real and must survive. (User 2026-06-02.)
        try:
            Transaction.query.filter_by(doc_upload_id=upload.id, source='doc_upload').delete(synchronize_session=False)
            # Any electronic txn that was tentatively paired to this now-duplicate
            # receipt is unlinked (not deleted) so it returns to the unmatched pile.
            Transaction.query.filter_by(doc_upload_id=upload.id).update(
                {"doc_upload_id": None, "match_status": "unmatched", "match_confidence": None},
                synchronize_session=False)
        except Exception:
            pass
        return True, {"resolved": "confirm", "upload_id": upload.id, "moved_to": moved_to,
                      "link_mode": (link_mode or 'unlink'),
                      "transferred_charges": transferred,
                      "transferred_to": (keeper.id if transferred else None)}, None

    return False, {}, "action must be 'keep' or 'confirm'"


@app.route("/docs/upload/<int:uid>/resolve-duplicate", methods=["POST"])
@login_required
def docs_resolve_duplicate(uid):
    """Resolve ONE doc flagged as a possible duplicate.
    Body: {"action": "keep" | "confirm"}."""
    upload = DocUpload.query.get_or_404(uid)
    if current_user.role not in ('super_admin', 'admin'):
        if upload.uploader_id != current_user.id:
            return jsonify({"error": "Forbidden"}), 403
    _body = request.get_json(silent=True) or {}
    action = (_body.get("action") or "").strip().lower()
    force = bool(_body.get("force"))
    link_mode = (_body.get("link_mode") or "").strip().lower() or None
    ok, info, err = _apply_dup_resolution(upload, action, force=force, link_mode=link_mode)
    if not ok:
        db.session.rollback()
        # needs_force = coded doc; 409 so the UI can prompt + retry with force.
        return jsonify({"error": err, **(info or {})}), (409 if (info or {}).get("needs_force") else 400)
    db.session.commit()
    logging.info(f"[DOCS] upload #{upload.id}: duplicate review → {action.upper()}")
    info["ok"] = True
    return jsonify(info)


@app.route("/docs/<int:pid>/dup-links", methods=["POST"])
@login_required
def docs_dup_links(pid):
    """READ-ONLY: for a set of DocUpload ids, return the electronic charges
    matched to each, what each is coded to, and the kept original of its set.
    Powers the Compare-group modal's per-copy linkage display so you can see
    'these are connected' before deciding. (User 2026-06-17.)"""
    if not current_user.is_authenticated:
        return jsonify({"error": "Not authenticated"}), 401
    ProjectSheet.query.get_or_404(pid)
    if current_user.role not in ('super_admin', 'admin'):
        if not ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first():
            return jsonify({"error": "Forbidden"}), 403
    raw = (request.get_json(silent=True) or {}).get("ids") or []
    ids = []
    for x in raw:
        try: ids.append(int(x))
        except (TypeError, ValueError): pass
    out = {}
    ups = ({u.id: u for u in DocUpload.query
            .filter(DocUpload.project_id == pid, DocUpload.id.in_(ids)).all()} if ids else {})
    for uid, u in ups.items():
        charges = (Transaction.query
                   .filter(Transaction.doc_upload_id == uid,
                           Transaction.source.in_(('qbo_sync', 'csv_import'))).all())
        coded = (Transaction.query.filter_by(doc_upload_id=uid)
                 .filter(db.or_(Transaction.budget_line_id.isnot(None),
                                Transaction.account_code.isnot(None))).first())
        keeper = None
        if u.file_hash:
            keeper = (DocUpload.query
                      .filter(DocUpload.project_id == pid, DocUpload.file_hash == u.file_hash,
                              DocUpload.id != uid, DocUpload.is_duplicate == False)  # noqa: E712
                      .order_by(DocUpload.id.asc()).first())
        if not keeper and u.duplicate_of_id:
            keeper = DocUpload.query.get(u.duplicate_of_id)
        out[uid] = {
            "linked_charges": [{"tid": c.id, "vendor": c.vendor,
                                "amount": (float(c.amount) if c.amount is not None else None),
                                "date": c.txn_date,
                                "code": c.account_code_name or (str(c.account_code) if c.account_code else None),
                                "source": c.source} for c in charges],
            "coded_to": (coded.account_code_name
                         or (str(coded.account_code) if (coded and coded.account_code) else None)) if coded else None,
            "keeper": ({"id": keeper.id, "filed": (keeper.filed_filename or keeper.original_filename)} if keeper else None),
        }
    return jsonify({"ok": True, "links": out})


@app.route("/docs/<int:pid>/duplicates/resolve-batch", methods=["POST"])
@login_required
def docs_resolve_duplicates_batch(pid):
    """Resolve a whole duplicate GROUP (or sweep) in one call.
    Body: {"keep": [uid,...], "confirm": [uid,...]}.
    Confirms are processed first so a swap (keep a flagged copy, confirm the
    old original) can't leave the group with zero kept rows mid-flight.
    Partial success commits whatever worked; per-uid errors are returned."""
    data = request.get_json(silent=True) or {}
    def _ints(xs):
        out = []
        for x in (xs or []):
            try: out.append(int(x))
            except (TypeError, ValueError): pass
        return out
    keep_ids    = _ints(data.get("keep"))
    confirm_ids = _ints(data.get("confirm"))
    force = bool(data.get("force"))
    link_mode = (data.get("link_mode") or "").strip().lower() or None
    results, errors = [], []
    for action, ids in (("confirm", confirm_ids), ("keep", keep_ids)):
        for uid in ids:
            up = DocUpload.query.filter_by(id=uid, project_id=pid).first()
            if not up:
                errors.append({"uid": uid, "error": "not found"}); continue
            if current_user.role not in ('super_admin', 'admin') and up.uploader_id != current_user.id:
                errors.append({"uid": uid, "error": "forbidden"}); continue
            ok, info, err = _apply_dup_resolution(up, action, force=force, link_mode=link_mode)
            (results if ok else errors).append(info if ok else {"uid": uid, "error": err})
    db.session.commit()
    logging.info(f"[DOCS] batch dup resolve project={pid}: "
                 f"{len(results)} ok, {len(errors)} err "
                 f"(keep={len(keep_ids)}, confirm={len(confirm_ids)})")
    return jsonify({"ok": True, "results": results, "errors": errors,
                    "kept": len(keep_ids), "confirmed": len(confirm_ids)})


@app.route("/docs/upload/<int:uid>/delete", methods=["POST"])
@login_required
def docs_upload_delete(uid):
    """SOFT delete → Trash (2026-06-11, was a hard delete). The row stays with
    status='deleted' so it can be restored from the Docs Trash; Dropbox copies
    move to /_TRASH/ with their locations recorded in trash_meta for restore.

    Transactions: the doc's OWN ledger row(s) (source='doc_upload') are deleted
    (restore recreates one); a MATCHED BANK ROW is only unlinked — the old code
    deleted it too, silently destroying the bank charge when you deleted its
    receipt. PO links and duplicate back-pointers are left intact (the row
    still exists). Hard removal = /docs/upload/<uid>/purge from the Trash."""
    upload = DocUpload.query.get_or_404(uid)
    if current_user.role not in ('super_admin', 'admin'):
        if upload.uploader_id != current_user.id:
            return jsonify({"error": "Forbidden"}), 403
    if upload.status == 'deleted':
        return jsonify({"ok": True, "already": True, "soft": True})
    pid = upload.project_id
    _act_label  = upload.filed_filename or upload.original_filename or f'Upload #{uid}'
    _act_vendor = upload.vendor
    _act_amount = float(upload.amount or 0)
    # Move BOTH the filed copy AND the source archive copy to /_TRASH/,
    # recording the real destinations so /restore can move them back.
    paths_to_trash = []
    if upload.filed_dropbox_path:
        paths_to_trash.append(upload.filed_dropbox_path)
    if upload.source_archive_path and upload.source_archive_path != upload.filed_dropbox_path:
        paths_to_trash.append(upload.source_archive_path)
    _moves = []
    trashed = _trash_dropbox_paths(paths_to_trash, moves_out=_moves)
    # The doc's own ledger row(s) go (restore recreates); matched bank rows are
    # UNLINKED, never deleted — their coding survives.
    removed_doc_txns = (Transaction.query
                        .filter_by(doc_upload_id=upload.id, source='doc_upload')
                        .delete(synchronize_session=False))
    unlinked_bank = (Transaction.query
                     .filter(Transaction.doc_upload_id == upload.id,
                             Transaction.source != 'doc_upload')
                     .update({"doc_upload_id": None, "match_status": "unmatched",
                              "match_confidence": None}, synchronize_session=False))
    import json as _json
    upload.trash_meta = _json.dumps({"prior_status": upload.status, "moves": _moves})
    upload.status     = 'deleted'
    upload.deleted_at = datetime.utcnow()
    db.session.commit()
    try:
        _log_activity(action='delete', entity_type='doc_upload',
                      entity_id=uid, entity_label=_act_label,
                      project_id=pid,
                      before={'vendor': _act_vendor, 'amount': _act_amount},
                      after=None,
                      note=f'Moved "{_act_label}" to Trash (restorable; Dropbox copies in /_TRASH/)')
    except Exception: pass
    return jsonify({"status": "deleted", "soft": True, "trashed_files": trashed,
                    "removed_doc_txns": removed_doc_txns,
                    "unlinked_bank_rows": unlinked_bank})


@app.route("/docs/<int:pid>/trash", methods=["GET"])
@login_required
def docs_trash_list(pid):
    """Docs Trash: soft-deleted documents for this project, newest first.
    (User 2026-06-11 — recoverable deletes.)"""
    if current_user.role not in ('super_admin', 'admin'):
        access = ProjectAccess.query.filter_by(project_id=pid, user_id=current_user.id).first()
        if not access:
            return jsonify({"error": "Forbidden"}), 403
    rows = (DocUpload.query.filter_by(project_id=pid, status='deleted')
            .order_by(DocUpload.deleted_at.desc().nullslast()).limit(300).all())
    out = [{"id": u.id,
            "filename": u.filed_filename or u.original_filename,
            "vendor": u.vendor, "category": u.category,
            "amount": float(u.amount) if u.amount is not None else None,
            "doc_date": u.doc_date.isoformat() if u.doc_date else None,
            "deleted_at": (u.deleted_at.isoformat() + 'Z') if u.deleted_at else None}
           for u in rows]
    return jsonify({"trash": out, "count": len(out)})


@app.route("/docs/upload/<int:uid>/restore", methods=["POST"])
@login_required
def docs_upload_restore(uid):
    """Restore a soft-deleted doc from the Trash: move its Dropbox copies back
    to their original locations, restore the prior status, and recreate the
    Actuals transaction for ledger types. (User 2026-06-11.)"""
    upload = DocUpload.query.get_or_404(uid)
    if current_user.role not in ('super_admin', 'admin'):
        if upload.uploader_id != current_user.id:
            return jsonify({"error": "Forbidden"}), 403
    if upload.status != 'deleted':
        return jsonify({"error": "Not in the Trash"}), 400
    import json as _json
    meta = {}
    try:
        meta = _json.loads(upload.trash_meta) if upload.trash_meta else {}
    except Exception:
        meta = {}
    moved_back, move_errors = 0, []
    try:
        dbx = _dbx_client()
        for mv in (meta.get('moves') or []):
            try:
                dbx.files_move_v2(mv['dest'], mv['src'], autorename=True)
                moved_back += 1
            except Exception as _me:
                if 'not_found' not in str(_me).lower():
                    move_errors.append(type(_me).__name__)
    except Exception as _ce:
        move_errors.append('dbx_init:' + type(_ce).__name__)
    upload.status     = meta.get('prior_status') or ('done' if upload.filed_dropbox_path else 'review')
    upload.deleted_at = None
    upload.trash_meta = None
    db.session.commit()
    # Recreate the Actuals row for ledger doc types (mirrors unmatch_receipt).
    txn_recreated = False
    if ((upload.category or '') in ('receipt', 'invoice')
            and not upload.is_duplicate
            and upload.status in ('done', 'review')
            and not Transaction.query.filter_by(doc_upload_id=upload.id,
                                                source='doc_upload').first()):
        try:
            db.session.add(Transaction(
                project_id=upload.project_id, source='doc_upload',
                doc_upload_id=upload.id, vendor=upload.vendor,
                amount=upload.amount,
                txn_date=upload.doc_date.isoformat() if upload.doc_date else None,
                card_last4=upload.card_last4, is_expense=True,
                match_status='unmatched',
                created_via_user_id=current_user.id))
            db.session.commit()
            txn_recreated = True
        except Exception:
            db.session.rollback()
    try:
        _log_activity(action='update', entity_type='doc_upload', entity_id=uid,
                      entity_label=(upload.filed_filename or upload.original_filename
                                    or f'Upload #{uid}'),
                      project_id=upload.project_id, before=None,
                      after={'status': upload.status},
                      note='Restored from Trash')
    except Exception: pass
    return jsonify({"ok": True, "status": upload.status,
                    "files_moved_back": moved_back, "move_errors": move_errors,
                    "txn_recreated": txn_recreated})


@app.route("/docs/upload/<int:uid>/purge", methods=["POST"])
@login_required
def docs_upload_purge(uid):
    """PERMANENTLY remove a doc that is already in the Trash (the old hard
    delete, now only reachable from there). Dropbox copies stay in /_TRASH/
    until the 30-day purge. (User 2026-06-11.)"""
    upload = DocUpload.query.get_or_404(uid)
    if current_user.role not in ('super_admin', 'admin'):
        if upload.uploader_id != current_user.id:
            return jsonify({"error": "Forbidden"}), 403
    if upload.status != 'deleted':
        return jsonify({"error": "Move it to the Trash first (delete), then purge."}), 400
    pid = upload.project_id
    _lbl = upload.filed_filename or upload.original_filename or f'Upload #{uid}'
    if upload.r2_key:
        try:
            _r2_client().delete_object(Bucket=_R2_BUCKET, Key=upload.r2_key)
        except Exception:
            pass
    Transaction.query.filter_by(doc_upload_id=upload.id).update(
        {"doc_upload_id": None}, synchronize_session=False)
    try:
        db.session.execute(
            text("UPDATE purchase_order SET source_doc_upload_id=NULL "
                 "WHERE source_doc_upload_id=:uid"), {"uid": upload.id})
        db.session.execute(
            text("DELETE FROM po_doc_attachment WHERE doc_upload_id=:uid"),
            {"uid": upload.id})
    except Exception:
        db.session.rollback()
    DocUpload.query.filter_by(duplicate_of_id=upload.id).update(
        {"duplicate_of_id": None, "is_duplicate": False}, synchronize_session=False)
    db.session.delete(upload)
    db.session.commit()
    try:
        _log_activity(action='delete', entity_type='doc_upload', entity_id=uid,
                      entity_label=_lbl, project_id=pid, before=None, after=None,
                      note=f'Purged "{_lbl}" from Trash (permanent)')
    except Exception: pass
    return jsonify({"ok": True, "purged": uid})


@app.route("/docs/<int:pid>/bulk-delete", methods=["POST"])
@login_required
def docs_bulk_delete(pid):
    """Delete multiple uploads in one request. Body: {"ids": [1,2,3]}.
    Per user 2026-04-29: bulk operations on the Docs tab.
    Permission: same as single delete — admins can delete any, regular
    users only their own. Mixed-ownership requests are filtered to the
    user's own and the response reports how many were skipped.
    """
    ProjectSheet.query.get_or_404(pid)
    data = request.get_json(force=True) or {}
    ids = [int(i) for i in (data.get("ids") or []) if str(i).isdigit()]
    if not ids:
        return jsonify({"error": "No ids provided"}), 400
    is_admin = current_user.role in ('super_admin', 'admin')
    rows = DocUpload.query.filter(DocUpload.id.in_(ids),
                                  DocUpload.project_id == pid).all()
    deleted, skipped, labels = 0, 0, []
    paths_to_trash = []
    upload_ids_to_delete = []
    for u in rows:
        if not is_admin and u.uploader_id != current_user.id:
            skipped += 1
            continue
        labels.append(u.filed_filename or u.original_filename or f'Upload #{u.id}')
        # Collect both filed + archive paths for batched Dropbox-trash.
        if u.filed_dropbox_path:
            paths_to_trash.append(u.filed_dropbox_path)
        if u.source_archive_path and u.source_archive_path != u.filed_dropbox_path:
            paths_to_trash.append(u.source_archive_path)
        try:
            _r2_client().delete_object(Bucket=_R2_BUCKET, Key=u.r2_key)
        except Exception:
            pass
        upload_ids_to_delete.append(u.id)
        deleted += 1
    # Delete child Transaction rows first (FK constraint). One bulk
    # delete is faster than per-upload, and synchronize_session=False
    # is fine because we're about to delete the parents in the same
    # transaction anyway.
    if upload_ids_to_delete:
        Transaction.query.filter(
            Transaction.doc_upload_id.in_(upload_ids_to_delete)
        ).delete(synchronize_session=False)
        # Detach PO source-doc references and remove po_doc_attachment
        # rows so the doc_upload deletes don't trip FK constraints.
        try:
            db.session.execute(
                text("UPDATE purchase_order SET source_doc_upload_id=NULL "
                     "WHERE source_doc_upload_id = ANY(:ids)"),
                {"ids": upload_ids_to_delete},
            )
            db.session.execute(
                text("DELETE FROM po_doc_attachment "
                     "WHERE doc_upload_id = ANY(:ids)"),
                {"ids": upload_ids_to_delete},
            )
        except Exception:
            db.session.rollback()
        # Clear self-referential duplicate_of_id pointers into the deleted set
        # (FK: doc_upload_duplicate_of_id_fkey). (User 2026-06-01.)
        DocUpload.query.filter(
            DocUpload.duplicate_of_id.in_(upload_ids_to_delete)
        ).update({"duplicate_of_id": None, "is_duplicate": False}, synchronize_session=False)
        DocUpload.query.filter(
            DocUpload.id.in_(upload_ids_to_delete)
        ).delete(synchronize_session=False)
    db.session.commit()
    # Move all the Dropbox files to /_TRASH/ in one go (best-effort,
    # never fails the request — DB rows are already gone).
    trashed = _trash_dropbox_paths(paths_to_trash)
    try:
        if deleted:
            _log_activity(action='delete', entity_type='doc_upload_bulk',
                          entity_id=None,
                          entity_label=f'Bulk delete — {deleted} document{"s" if deleted != 1 else ""}',
                          project_id=pid,
                          before=None, after={'deleted_ids': ids[:deleted]},
                          note=f'Bulk-deleted {deleted} document{"s" if deleted != 1 else ""}: '
                               + ", ".join(labels[:5])
                               + (f' (+{len(labels)-5} more)' if len(labels) > 5 else ''))
    except Exception: pass
    return jsonify({"status": "ok", "deleted": deleted, "skipped": skipped,
                    "trashed_files": trashed})


@app.route("/docs/<int:pid>/purge-ghosts", methods=["POST"])
@login_required
def docs_purge_ghosts(pid):
    """One-shot cleanup: delete DocUpload rows that have no file behind
    them in Dropbox (filed_dropbox_path IS NULL). These are leftover
    ghosts from earlier upload failures (OOM, Veryfi connection reset,
    Dropbox partial fail). Without this they keep ghost-matching real
    re-uploads as duplicates.

    Permission: admin only — bulk delete should be deliberate.
    Returns {deleted: N, ids: [...]}.
    """
    ProjectSheet.query.get_or_404(pid)
    if current_user.role not in ('super_admin', 'admin'):
        return jsonify({"error": "Admin only"}), 403
    # Ghost = no Dropbox file behind the row. Review rows now point at
    # _UPLOADS_PENDING/ so they have a path; only error/legacy rows with
    # NULL path qualify as ghosts.
    rows = DocUpload.query.filter_by(project_id=pid).filter(
        DocUpload.filed_dropbox_path.is_(None)
    ).all()
    ids, labels = [], []
    for u in rows:
        ids.append(u.id)
        labels.append(u.filed_filename or u.original_filename or f'Upload #{u.id}')
    # Drop child Transaction rows first (FK constraint).
    if ids:
        Transaction.query.filter(
            Transaction.doc_upload_id.in_(ids)
        ).delete(synchronize_session=False)
        DocUpload.query.filter(DocUpload.id.in_(ids)).delete(synchronize_session=False)
    db.session.commit()
    try:
        if ids:
            _log_activity(action='delete', entity_type='doc_upload_bulk',
                          entity_id=None,
                          entity_label=f'Ghost purge — {len(ids)} row{"s" if len(ids) != 1 else ""}',
                          project_id=pid,
                          before=None, after={'deleted_ids': ids},
                          note=f'Purged {len(ids)} ghost upload row{"s" if len(ids) != 1 else ""} '
                               'with no Dropbox file: '
                               + ", ".join(labels[:5])
                               + (f' (+{len(labels)-5} more)' if len(labels) > 5 else ''))
    except Exception: pass
    return jsonify({"status": "ok", "deleted": len(ids), "ids": ids})


@app.route("/docs/<int:pid>/export.csv")
@login_required
def docs_export_csv(pid):
    """Export every DocUpload row for this project as a CSV. Used for
    accounting hand-off / audit. Per user 2026-04-29: separate from the
    budget CSV export — this is the receipts / OCR metadata.
    Optional ?status=done,review filter; default = everything.
    """
    ProjectSheet.query.get_or_404(pid)
    status_param = (request.args.get("status") or "").strip()
    q = DocUpload.query.filter_by(project_id=pid)
    if status_param:
        q = q.filter(DocUpload.status.in_(status_param.split(",")))
    rows = q.order_by(DocUpload.uploaded_at.desc()).all()
    import io as _io_d, csv as _csv_d
    out = _io_d.StringIO()
    w = _csv_d.writer(out)
    w.writerow([
        "ID", "Uploaded", "Uploader", "Original Filename", "Filed Filename",
        "Status", "Doc Type", "Vendor", "Amount", "Doc Date",
        "Confidence %", "Is Duplicate", "Dropbox Path", "Note", "File Size (KB)",
    ])
    for u in rows:
        uploader = ''
        if u.uploader:
            uploader = u.uploader.name or u.uploader.email or ''
        w.writerow([
            u.id,
            u.uploaded_at.strftime('%Y-%m-%d %H:%M') if u.uploaded_at else '',
            uploader,
            u.original_filename or '',
            u.filed_filename or '',
            u.status or '',
            u.category or '',
            u.vendor or '',
            f'{float(u.amount):.2f}' if u.amount else '',
            u.doc_date.isoformat() if u.doc_date else '',
            f'{float(u.confidence):.1f}' if u.confidence is not None else '',
            'yes' if u.is_duplicate else '',
            u.filed_dropbox_path or '',
            (u.note or '').replace('\n', ' '),
            f'{(u.file_size or 0) / 1024:.1f}' if u.file_size else '',
        ])
    proj = ProjectSheet.query.get(pid)
    fname = f"{(proj.name or 'project').replace(' ', '_')}_documents_{date.today().isoformat()}.csv"
    return Response(out.getvalue(), mimetype='text/csv',
                    headers={'Content-Disposition': f'attachment; filename="{fname}"'})


@app.route("/docs/upload/<int:uid>/rename", methods=["POST"])
@login_required
def docs_upload_rename(uid):
    """Rename a filed document. Updates DocUpload.filed_filename +
    filed_dropbox_path AND renames the file in Dropbox so the two stay
    in sync. Only works when the upload has been filed to Dropbox (has
    a filed_dropbox_path). Dropbox's files_move_v2 with autorename=True
    handles name collisions — we store whatever final name Dropbox used.

    Permission: project members + admins. Non-uploader non-admins
    cannot rename someone else's upload.
    """
    upload = DocUpload.query.get_or_404(uid)

    # Auth: admins can rename anything; regular users only their own.
    if current_user.role not in ('super_admin', 'admin'):
        if upload.uploader_id != current_user.id:
            return jsonify({"error": "Forbidden"}), 403

    if not upload.filed_dropbox_path:
        return jsonify({
            "error": "This document isn't filed in Dropbox yet — can't rename."
        }), 400

    data = request.get_json(force=True) or {}
    new_filename = (data.get("new_filename") or "").strip()
    if not new_filename:
        return jsonify({"error": "Filename required"}), 400
    # Sanity guards
    if "/" in new_filename or "\\" in new_filename:
        return jsonify({"error": "Filename cannot contain / or \\"}), 400
    if len(new_filename) > 200:
        return jsonify({"error": "Filename too long (>200 chars)"}), 400
    # Strip any leading/trailing whitespace and disallow control chars.
    if any(ord(c) < 32 for c in new_filename):
        return jsonify({"error": "Filename contains control characters"}), 400

    # Auto-append the original extension if the new name doesn't carry one.
    # e.g., user types 'VendorX_Receipt' on a '.pdf' file → 'VendorX_Receipt.pdf'.
    import os as _os
    old_path   = upload.filed_dropbox_path
    old_name   = _os.path.basename(old_path)
    parent_dir = _os.path.dirname(old_path) or "/"
    _, old_ext = _os.path.splitext(old_name)
    _, new_ext = _os.path.splitext(new_filename)
    if old_ext and not new_ext:
        new_filename = new_filename + old_ext

    if new_filename == old_name:
        return jsonify({
            "ok": True,
            "new_filename":  new_filename,
            "new_path":      old_path,
            "message":       "Filename unchanged — no move needed.",
        })

    new_path = f"{parent_dir}/{new_filename}"

    # Do the Dropbox move. autorename=True: if another file already has
    # this name in the same folder, Dropbox appends ' (2)' etc. — we
    # capture the final path it actually ended up at.
    try:
        dbx = _dbx_client()
        res = dbx.files_move_v2(old_path, new_path, autorename=True)
        final_path = getattr(getattr(res, 'metadata', None), 'path_display', None) or new_path
        final_name = _os.path.basename(final_path)
    except Exception as e:
        logging.exception(f"Rename failed: {old_path} → {new_path}")
        return jsonify({
            "error": f"Dropbox move failed: {type(e).__name__}: {e}"
        }), 500

    upload.filed_filename     = final_name
    upload.filed_dropbox_path = final_path
    from datetime import datetime as _dt
    # Touch filed_at so the row shows a "recently modified" sort if needed.
    upload.filed_at = _dt.utcnow()
    db.session.commit()

    try:
        _log_activity(action='update', entity_type='doc_upload',
                      entity_id=uid, entity_label=final_name,
                      project_id=upload.project_id,
                      before={'filename': old_name},
                      after={'filename': final_name},
                      note=f'Renamed "{old_name}" → "{final_name}"')
    except Exception: pass

    logging.info(f"Renamed upload {uid}: {old_path} → {final_path}")
    return jsonify({
        "ok":           True,
        "new_filename": final_name,
        "new_path":     final_path,
        "message":      "Renamed." if final_name == new_filename
                        else f"Renamed (Dropbox autorenamed to avoid collision: {final_name}).",
    })


# ── Docs: verify, preview link, update fields ───────────────────────────────
# These three endpoints back the "ironclad" docs UX:
#   * /verify       → confirm the file is actually present in Dropbox
#                     (catches silent filing failures, deleted files, drift)
#   * /preview-link → short-lived Dropbox temporary link for embedding in
#                     the in-page detail modal
#   * /update       → save edits to vendor / amount / doc_date / category /
#                     note from the detail modal

def _docs_check_row_access(upload):
    """Return None if current user may see/edit this upload, else a Flask
    response ready to be returned. Mirrors the pattern in upload_post."""
    if current_user.role in ('super_admin', 'admin'):
        return None
    access = ProjectAccess.query.filter_by(
        project_id=upload.project_id, user_id=current_user.id).first()
    if not access:
        return jsonify({"error": "Forbidden"}), 403
    return None


@app.route("/docs/upload/<int:uid>/verify", methods=["GET"])
@login_required
def docs_upload_verify(uid):
    """Check whether the filed Dropbox path actually resolves to a file.

    Returns:
      {"ok": true,  "verified": true,  "size": <bytes>}   — file present
      {"ok": true,  "verified": false, "reason": "..."}   — file missing
                                                            or path empty

    The client calls this in the background for every "Filed" row on
    page load and flips the row to RED if verified=false. This is the
    "nothing can ever be lost" guarantee — we're not just trusting the
    DB row's status field, we're confirming the bytes are actually
    sitting in Dropbox where they're supposed to be.
    """
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny

    if not upload.filed_dropbox_path:
        return jsonify({
            "ok": True, "verified": False,
            "reason": "no filed_dropbox_path on record",
            "status": upload.status,
        })

    # Build a path that works under namespace mode AND respects the
    # legacy ops-prefix that some older rows still carry. Same pattern
    # as the wipe handler — try normalized first, then raw.
    _ops_prefix_str = (_DBX_OPS_ROOT or "").rstrip("/") if _DBX_NAMESPACE_ID else ""
    raw_path  = upload.filed_dropbox_path
    norm_path = raw_path
    if _ops_prefix_str and norm_path.startswith(_ops_prefix_str + "/"):
        norm_path = norm_path[len(_ops_prefix_str):]

    try:
        dbx = _dbx_client()
    except Exception as e:
        return jsonify({
            "ok": False,
            "verified": False,
            "reason": f"Dropbox client init failed: {e}",
        }), 500

    for path_try in (norm_path, raw_path) if norm_path != raw_path else (norm_path,):
        try:
            md = dbx.files_get_metadata(path_try)
            return jsonify({
                "ok": True,
                "verified": True,
                "size": getattr(md, 'size', None),
                "path": getattr(md, 'path_display', path_try),
            })
        except Exception:
            continue
    # Both attempts failed → file is genuinely missing.
    return jsonify({
        "ok": True,
        "verified": False,
        "reason": "Dropbox returned not_found for both normalized and raw paths",
        "tried": [norm_path, raw_path] if norm_path != raw_path else [norm_path],
    })


@app.route("/docs/upload/<int:uid>/raw", methods=["GET"])
@login_required
def docs_upload_raw(uid):
    """Stream the filed Dropbox file through our server with inline
    Content-Disposition so it embeds in <img> / <iframe> / <embed>.

    Why we need this: Dropbox's temp-link content URLs serve files with
    `Content-Disposition: attachment` AND `X-Frame-Options: DENY`. The
    first triggers a download in <a> tags; the second blocks the URL in
    <iframe>. Browsers ignore Content-Disposition for <img src>, so
    images sometimes worked, but PDFs never did. Routing through our
    server gives us full control of headers and works for every type.

    Auth: same project-membership check as the rest of the docs
    endpoints. Streaming uses dbx.files_download() which returns the
    raw bytes — for receipts (typically <2 MB) this is fine memory-wise
    and avoids chunked-streaming complications.
    """
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny

    # ── Source priority ────────────────────────────────────────────
    # By default serve the filed (processed) copy. If the caller
    # passes ?source=1 (or ?archive=1), serve the durable
    # _SOURCE_ARCHIVE copy instead — that's the original bytes as
    # uploaded, untouched by the Analyzer's renaming/filing pipeline.
    # If the filed copy is unreachable, fall back to source archive
    # too (mission-critical fail-safe — 2026-04-30).
    _force_source = request.args.get('source') in ('1', 'true', 'yes') \
                 or request.args.get('archive') in ('1', 'true', 'yes')
    content = None
    fname = upload.filed_filename or upload.original_filename or f"upload_{uid}"

    if _force_source and upload.source_archive_path:
        try:
            dbx = _dbx_client()
            md, resp = dbx.files_download(upload.source_archive_path)
            content = resp.content
            fname = upload.original_filename or md.name or fname
            logging.info(f"[docs/raw] forced source archive for upload {uid}")
        except Exception as _se:
            logging.warning(f"[docs/raw] source archive fetch failed for {uid}: {_se}")
            # Fall through to filed-copy logic below as best-effort.

    if content is None and upload.filed_dropbox_path:
        # Filed in Dropbox — fetch from there.
        _ops_prefix_str = (_DBX_OPS_ROOT or "").rstrip("/") if _DBX_NAMESPACE_ID else ""
        raw_path  = upload.filed_dropbox_path
        norm_path = raw_path
        if _ops_prefix_str and norm_path.startswith(_ops_prefix_str + "/"):
            norm_path = norm_path[len(_ops_prefix_str):]
        try:
            dbx = _dbx_client()
        except Exception as e:
            return jsonify({"error": f"Dropbox init failed: {e}"}), 500
        last_err = None
        for path_try in (norm_path, raw_path) if norm_path != raw_path else (norm_path,):
            try:
                md, resp = dbx.files_download(path_try)
                content = resp.content
                fname = upload.filed_filename or upload.original_filename or md.name
                break
            except Exception as e:
                last_err = e
                continue
        if content is None:
            # Filed file is unreachable (renamed, deleted, or Dropbox
            # outage). Fall back to the durable source archive.
            if upload.source_archive_path:
                try:
                    md, resp = dbx.files_download(upload.source_archive_path)
                    content = resp.content
                    logging.info(f"[docs/raw] served from source_archive_path for upload {uid}")
                except Exception as _ae:
                    last_err = _ae
            # Last-ditch R2 fallback (legacy rows from before the
            # source-archive era).
            if content is None and upload.r2_key:
                bytes_, err = _r2_download(upload.r2_key)
                if not err:
                    content = bytes_
            if content is None:
                return jsonify({
                    "error": f"Could not fetch file: {type(last_err).__name__}: {last_err}",
                }), 500
    elif upload.source_archive_path:
        # No filed copy but we have the archive — serve directly from
        # _SOURCE_ARCHIVE/. This is the path review-status uploads take.
        try:
            dbx = _dbx_client()
            md, resp = dbx.files_download(upload.source_archive_path)
            content = resp.content
            fname = upload.filed_filename or upload.original_filename or md.name
        except Exception as e:
            return jsonify({"error": f"Source archive fetch failed: {e}"}), 502
    else:
        # Pre-archive legacy — pull from R2.
        if not upload.r2_key:
            return jsonify({"error": "No filed file and no archive — file data is missing."}), 404
        bytes_, err = _r2_download(upload.r2_key)
        if err:
            return jsonify({"error": f"R2 fetch failed: {err}"}), 502
        content = bytes_

    # Derive Content-Type. Stored content_type is sometimes
    # application/octet-stream which disables inline display in many
    # browsers — re-derive from filename when that's the case.
    import mimetypes as _mt2
    guessed_ct = _mt2.guess_type(fname)[0]
    ct = (upload.content_type
          if upload.content_type and upload.content_type != "application/octet-stream"
          else (guessed_ct or "application/octet-stream"))

    # AUTHORITATIVE: sniff the real bytes and override the type. Filenames
    # lie here — build_name() always appends ".pdf" (even to JPEG/PNG phone
    # photos), and some rows recorded content_type='application/pdf' for
    # non-PDF bytes. Serving the wrong type makes the browser's PDF viewer
    # throw "Failed to load PDF document" on what is actually an image.
    # (User 2026-06-01: verified-in-Dropbox invoice wouldn't preview — its
    # bytes were a JPEG named ".pdf".)
    def _sniff_ct(buf):
        if not buf or len(buf) < 4:
            return None
        if buf[:4] == b'%PDF':                       return 'application/pdf'
        if buf[:3] == b'\xff\xd8\xff':               return 'image/jpeg'
        if buf[:8] == b'\x89PNG\r\n\x1a\n':          return 'image/png'
        if buf[:6] in (b'GIF87a', b'GIF89a'):        return 'image/gif'
        if buf[:4] == b'RIFF' and buf[8:12] == b'WEBP': return 'image/webp'
        if buf[:2] in (b'II', b'MM'):                return 'image/tiff'
        if buf[4:8] == b'ftyp' and buf[8:12] in (
                b'heic', b'heix', b'hevc', b'mif1', b'heif'):
            return 'image/heic'
        return None
    _sniffed = _sniff_ct(content[:16] if content else b'')
    if _sniffed:
        ct = _sniffed

    # On-the-fly HEIC → JPEG conversion so iPhone receipts render in
    # Chrome/Firefox (which can't render HEIC natively). Trigger on the
    # sniffed type too, since a HEIC may be misnamed ".pdf".
    _ext = (os.path.splitext(fname)[1] or '').lower()
    if _ext in ('.heic', '.heif') or _sniffed == 'image/heic':
        try:
            import pillow_heif  # noqa: F401  (registers Pillow opener)
            from PIL import Image
            import io as _io_heic
            img = Image.open(_io_heic.BytesIO(content))
            out = _io_heic.BytesIO()
            img.convert("RGB").save(out, format="JPEG", quality=85)
            content = out.getvalue()
            ct = "image/jpeg"
        except Exception as _he:
            logging.warning(f"[docs/raw] HEIC convert failed for upload {uid}: {_he}")

    from flask import make_response
    from urllib.parse import quote as _q
    resp_out = make_response(content)
    resp_out.headers["Content-Type"]        = ct
    resp_out.headers["Content-Disposition"] = f"inline; filename=\"{_q(fname)}\""
    resp_out.headers["Cache-Control"]       = "private, max-age=300"
    return resp_out


@app.route("/docs/upload/<int:uid>/coding", methods=["GET"])
@login_required
def docs_upload_coding(uid):
    """Coding context for the doc-detail modal so the user can assign a
    budget line + see the smart suggestion right in the popup (user
    2026-05-29). Returns the linked transaction id, its current coding as a
    picker value (WORKING line id, or 'section:<code>', or ''), and the
    vendor→line suggestion. txn_id is None for non-ledger docs (no line)."""
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny
    _txns = (Transaction.query.filter_by(doc_upload_id=uid)
             .order_by(Transaction.id).all())
    if not _txns:
        return jsonify({"txn_id": None})
    # Prefer the electronic charge (it carries the AI code suggestion), else the
    # doc's own ledger row. (User 2026-06-22 — surface the suggestion in the popup.)
    txn = next((t for t in _txns if t.source in ('qbo_sync', 'csv_import', 'reconciled')
                and t.ai_suggested_code), None) \
        or next((t for t in _txns if t.source in ('qbo_sync', 'csv_import', 'reconciled')), None) \
        or _txns[0]
    cur = ''
    if txn.budget_line_id:
        bl = BudgetLine.query.get(txn.budget_line_id)
        # Picker values are WORKING line ids; an Actual line points back via
        # source_line_id, a Working line is its own id.
        cur = str((bl.source_line_id or bl.id) if bl else txn.budget_line_id)
    elif txn.account_code:
        cur = 'section:%s' % txn.account_code
    # Prefer the AI code suggestion (the ✨ purple chip) when the charge is
    # uncoded — it wasn't surfaced in the popup before, only the retired
    # heuristic vendor→line guess was. (User 2026-06-22.)
    sug = None
    if not (txn.budget_line_id or txn.account_code) and txn.ai_suggested_code:
        sug = {"code": txn.ai_suggested_code,
               "label": (txn.ai_suggested_code_name or str(txn.ai_suggested_code)),
               "line_id": "section:%s" % txn.ai_suggested_code,
               "confidence": (float(txn.ai_code_confidence) if txn.ai_code_confidence is not None else None)}
    if sug is None:
        try:
            sug = _actuals_vendor_suggestions(upload.project_id).get(txn.id)
        except Exception:
            sug = None
    return jsonify({
        "txn_id":      txn.id,
        "current":     cur,
        "suggestion":  sug,
        "not_project": bool(getattr(txn, 'not_project_expense', False)),
    })


def _line_budget_total(ln):
    """Approximate budgeted total for a line — labor: rate×days×qty; else the
    estimated total. Used for the person-profile deal headline + mismatch check."""
    try:
        if ln.is_labor:
            return round(float(ln.rate or 0) * float(ln.days or 0) * float(ln.quantity or 1), 2)
        return round(float(ln.estimated_total or 0), 2)
    except (TypeError, ValueError):
        return 0.0


@app.route("/projects/<int:pid>/person/<int:cmid>/profile", methods=["GET"])
@login_required
def person_profile(pid, cmid):
    """Wrapbook-style person profile: identity + deal (role/rate/kit/dates from
    their budget-line assignments) + documents (grouped, with a completeness
    checklist) + payments (transactions) + budget-vs-actual mismatch per line.
    (User 2026-07 — person-centric People tab.)"""
    _require_project_role(pid, 'viewer')
    ProjectSheet.query.get_or_404(pid)
    cm = CrewMember.query.get_or_404(cmid)
    _pcm = ProjectCrewMember.query.filter_by(project_id=pid, crew_member_id=cmid).first()
    from actuals import get_current_working_budget, get_current_estimated_budget
    b = get_current_working_budget(pid) or get_current_estimated_budget(pid)

    deal = []
    line_ids = []
    if b:
        lines = BudgetLine.query.filter_by(budget_id=b.id).all()
        line_by_id = {ln.id: ln for ln in lines}
        kits_by_parent = {}
        for ln in lines:
            if ln.line_tag == 'kit_fee' and ln.parent_line_id:
                kits_by_parent.setdefault(ln.parent_line_id, []).append(ln)
        # This person's lines: via CrewAssignment OR line-level assigned_crew_id.
        assigned = {}
        for ca in CrewAssignment.query.filter(
                CrewAssignment.crew_member_id == cmid,
                CrewAssignment.budget_line_id.in_(list(line_by_id.keys()) or [0])).all():
            assigned[ca.budget_line_id] = ca
        for ln in lines:
            if ln.is_labor and ln.assigned_crew_id == cmid and ln.id not in assigned:
                assigned[ln.id] = None
        for lid, ca in assigned.items():
            ln = line_by_id.get(lid)
            if not ln:
                continue
            line_ids.append(ln.id)
            rate = float((ca.rate_override if (ca and ca.rate_override is not None) else ln.rate) or 0)
            days = float(ln.days or 0)
            kits = kits_by_parent.get(ln.id, [])
            kit_total = round(sum(float(k.estimated_total or 0) for k in kits), 2)
            budgeted = _line_budget_total(ln)
            # Actuals may be coded to a SIBLING line (Working vs Actual budget), so
            # sum across every line in the project with the same section+role.
            _sib = (BudgetLine.query.join(Budget, Budget.id == BudgetLine.budget_id)
                    .filter(Budget.project_id == pid,
                            BudgetLine.account_code == ln.account_code))
            _sib = _sib.filter(BudgetLine.description == ln.description) if ln.description \
                else _sib.filter(BudgetLine.id == ln.id)
            _sib_ids = [x.id for x in _sib.all()] or [ln.id]
            actual = round(float(db.session.query(func.sum(_signed_amount()))
                           .filter(Transaction.project_id == pid,
                                   Transaction.budget_line_id.in_(_sib_ids),
                                   Transaction.not_project_expense == False).scalar() or 0), 2)
            # Mismatch = the person's actuals OVER the budgeted amount for the line.
            _tol = max(50.0, abs(budgeted) * 0.05)
            mismatch = None
            if budgeted and actual > budgeted + _tol:
                mismatch = {"budgeted": budgeted, "actual": actual,
                            "delta": round(actual - budgeted, 2), "over": True}
            deal.append({
                "line_id": ln.id, "role": (ln.description or ln.account_name or ''),
                "account_code": ln.account_code, "account_name": ln.account_name,
                "rate": rate, "rate_type": ln.rate_type, "days": days,
                "fringe_type": (ca.fringe_override if (ca and ca.fringe_override) else ln.fringe_type),
                "kit_fees": [{"description": k.description or 'Kit fee',
                              "total": float(k.estimated_total or 0)} for k in kits],
                "kit_total": kit_total,
                "budgeted": budgeted, "actual": actual, "mismatch": mismatch,
            })

    # Documents on this person + completeness checklist.
    docs = (DocUpload.query.filter_by(project_id=pid, crew_member_id=cmid)
            .filter(DocUpload.status != 'deleted')
            .order_by(DocUpload.uploaded_at.desc()).all())
    doc_out = [{
        "id": d.id, "category": d.category, "vendor": d.vendor,
        "amount": float(d.amount) if d.amount is not None else None,
        "doc_date": d.doc_date.isoformat() if d.doc_date else None,
        "filename": d.filed_filename or d.original_filename,
        "status": d.status, "has_image": bool(d.content_type and d.content_type.startswith('image/')),
    } for d in docs]
    _cats = {(d.category or '').lower() for d in docs}
    _has = lambda *ks: any(k in _cats for k in ks)
    completeness = {
        "contract":  _has('contract', 'release', 'legal'),
        "tax_form":  _has('tax_form'),
        "photo_id":  _has('id', 'photo_id', 'employee_vendor_doc'),
        "invoice":   _has('invoice'),
    }

    # Payments: transactions on this person's docs OR their assignment lines.
    _doc_ids = [d.id for d in docs]
    pay_q = Transaction.query.filter(Transaction.project_id == pid)
    conds = []
    if _doc_ids:
        conds.append(Transaction.doc_upload_id.in_(_doc_ids))
    if line_ids:
        conds.append(Transaction.budget_line_id.in_(line_ids))
    payments = []
    if conds:
        from sqlalchemy import or_ as _or_pay
        for t in (pay_q.filter(_or_pay(*conds))
                  .filter(Transaction.not_project_expense == False,
                          Transaction.source != 'invoice_split')
                  .order_by(Transaction.txn_date.desc().nullslast(), Transaction.id.desc()).all()):
            payments.append({
                "id": t.id, "amount": float(t.amount) if t.amount is not None else None,
                "date": t.txn_date, "vendor": t.vendor, "source": t.source,
                "match_status": t.match_status, "doc_upload_id": t.doc_upload_id,
                "is_expense": bool(t.is_expense),
            })
    total_paid = round(sum((p["amount"] or 0) for p in payments if p["is_expense"]), 2)

    reps = [{"name": s.name, "role_type": s.role_type, "email": s.email,
             "phone": s.phone, "company": s.company}
            for s in (cm.support_contacts or []) if getattr(s, 'active', True)]

    return jsonify({
        "ok": True,
        "identity": {
            "id": cm.id, "name": cm.name, "email": cm.email, "phone": cm.phone,
            "company": cm.company, "department": cm.department,
            # Per-project override wins; falls back to the person's global default.
            "employment_type": (_pcm.employment_type if _pcm and _pcm.employment_type
                                else getattr(cm, 'employment_type', None)),
            "union_status": (_pcm.union_status if _pcm and _pcm.union_status
                             else getattr(cm, 'union_status', None)),
            "is_vendor": bool(cm.is_vendor),
        },
        "deal": deal,
        "documents": doc_out,
        "completeness": completeness,
        "payments": payments,
        "total_paid": total_paid,
        "representation": reps,
        "has_mismatch": any(d.get("mismatch") for d in deal),
    })


@app.route("/projects/<int:pid>/budget/<int:bid>/mismatches", methods=["GET"])
@login_required
def budget_mismatches(pid, bid):
    """Lines on this budget where an assigned person's ACTUALS exceed the
    budgeted amount → drives the ⚠ over-budget badge on the budget line.
    (User 2026-07.) Computes in bulk (one txn-sum query + sibling map)."""
    _require_project_role(pid, 'viewer')
    Budget.query.filter_by(id=bid, project_id=pid).first_or_404()
    proj_lines = (BudgetLine.query.join(Budget, Budget.id == BudgetLine.budget_id)
                  .filter(Budget.project_id == pid).all())
    # sibling groups (same section+role across Working/Actual budgets)
    sib = {}
    for ln in proj_lines:
        sib.setdefault((ln.account_code, ln.description or ''), []).append(ln.id)
    rows = (db.session.query(Transaction.budget_line_id, func.sum(_signed_amount()))
            .filter(Transaction.project_id == pid,
                    Transaction.not_project_expense == False,
                    Transaction.budget_line_id.isnot(None))
            .group_by(Transaction.budget_line_id).all())
    actual_by_line = {r[0]: float(r[1] or 0) for r in rows}
    out = []
    for ln in proj_lines:
        if ln.budget_id != bid or not ln.is_labor:
            continue
        assigned = [ca for ca in (ln.crew_assignments or []) if ca.crew_member_id]
        cmid = person = None
        if assigned:
            cmid = assigned[0].crew_member_id
            person = (assigned[0].crew_member.name if assigned[0].crew_member else assigned[0].name_override)
        elif ln.assigned_crew_id:
            cmid = ln.assigned_crew_id
            _cm = CrewMember.query.get(cmid)
            person = _cm.name if _cm else None
        if not cmid:
            continue                      # only person-assigned lines
        budgeted = _line_budget_total(ln)
        actual = round(sum(actual_by_line.get(x, 0) for x in sib.get((ln.account_code, ln.description or ''), [ln.id])), 2)
        _tol = max(50.0, abs(budgeted) * 0.05)
        if budgeted and actual > budgeted + _tol:
            out.append({"line_id": ln.id, "role": (ln.description or ln.account_name),
                        "person": person, "crew_member_id": cmid,
                        "budgeted": budgeted, "actual": actual,
                        "delta": round(actual - budgeted, 2)})
    return jsonify({"ok": True, "mismatches": out})


@app.route("/projects/<int:pid>/person/<int:cmid>/update", methods=["POST"])
@login_required
def person_update(pid, cmid):
    """Update Wrapbook-style person fields from the profile panel (employment
    type + union status; also email/phone/company). (User 2026-07.)"""
    _require_project_role(pid, 'editor')
    cm = CrewMember.query.get_or_404(cmid)
    data = request.get_json(force=True) or {}
    # Employment type + union status are PER-PROJECT (someone's a different role /
    # union status on each show) → stored on ProjectCrewMember. (User 2026-07.)
    if "employment_type" in data or "union_status" in data:
        pcm = ProjectCrewMember.query.filter_by(project_id=pid, crew_member_id=cmid).first()
        if pcm is None:
            pcm = ProjectCrewMember(project_id=pid, crew_member_id=cmid)
            db.session.add(pcm)
        if "employment_type" in data:
            v = (data.get("employment_type") or "").strip().lower()
            pcm.employment_type = v[:20] if v in ('loan_out', 'employee', 'vendor') else None
        if "union_status" in data:
            v = (data.get("union_status") or "").strip().lower()
            pcm.union_status = v[:20] if v in ('union', 'non_union') else None
    # Contact info is GLOBAL identity → stays on the crew record.
    for _f in ('email', 'phone', 'company'):
        if _f in data:
            v = (data.get(_f) or "").strip()
            setattr(cm, _f, v[:200] if v else None)
    db.session.commit()
    return jsonify({"ok": True})


def _doc_receipt_detail(upload):
    """Receipt detail for the modal + reporting: subtotal / tax / tip + merchant
    address / phone. Prefers the stored column (user-edited or captured at
    upload); falls back to parsing veryfi_data so EXISTING docs show it too.
    (User 2026-07 — tax-credit reporting.)"""
    vd = {}
    if getattr(upload, 'veryfi_data', None):
        try:
            vd = upload.veryfi_data if isinstance(upload.veryfi_data, dict) else json.loads(upload.veryfi_data)
        except Exception:
            vd = {}
    ven = (vd.get("vendor") or {}) if isinstance(vd, dict) else {}
    def _m(col, key):
        v = getattr(upload, col, None)
        if v is not None:
            try:
                return round(float(v), 2)
            except (TypeError, ValueError):
                return None
        raw = vd.get(key)
        try:
            return round(float(raw), 2) if raw not in (None, '', 'null') else None
        except (TypeError, ValueError):
            return None
    addr = getattr(upload, 'merchant_address', None) or (ven.get("address") if isinstance(ven, dict) else None)
    phone = getattr(upload, 'merchant_phone', None) or (ven.get("phone_number") if isinstance(ven, dict) else None)
    return {
        "subtotal": _m('subtotal', 'subtotal'),
        "tax":      _m('tax', 'tax'),
        "tip":      _m('tip', 'tip'),
        "merchant_address": (str(addr)[:300] if addr else None),
        "merchant_phone":   (str(phone)[:40] if phone else None),
    }


def _doc_parent_txn(uid):
    """The transaction that represents a document as a whole — the electronic
    charge if the receipt is matched to one, else the doc's own ledger row.
    This is the row that gets itemized into per-line child splits."""
    _txns = (Transaction.query.filter_by(doc_upload_id=uid)
             .order_by(Transaction.id).all())
    if not _txns:
        return None
    return (next((t for t in _txns if t.source in ('qbo_sync', 'csv_import', 'reconciled')), None)
            or _txns[0])


@app.route("/docs/upload/<int:uid>/line-items", methods=["GET"])
@login_required
def docs_upload_line_items(uid):
    """Data for the QuickBooks-style 'Itemize into budget lines' grid on the
    doc-detail modal: the doc total, the Veryfi-extracted line items (suggested
    rows), and any existing itemization (child invoice_split transactions).
    (User 2026-07 — multi-line-item coding for invoices AND receipts.)"""
    upload = DocUpload.query.get_or_404(uid)
    deny = _docs_check_row_access(upload)
    if deny:
        return deny
    parent = _doc_parent_txn(uid)
    total = None
    if parent is not None and parent.amount is not None:
        total = abs(float(parent.amount))
    elif upload.amount is not None:
        total = abs(float(upload.amount))
    # Veryfi line items → suggested grid rows (description + amount).
    vd = {}
    if upload.veryfi_data:
        try:
            vd = upload.veryfi_data if isinstance(upload.veryfi_data, dict) else json.loads(upload.veryfi_data)
        except Exception:
            vd = {}
    veryfi_items = []
    for li in (vd.get("line_items") or []):
        if not isinstance(li, dict):
            continue
        amt = li.get("total")
        if amt is None:
            amt = li.get("price")
        try:
            amt = round(abs(float(amt)), 2) if amt is not None else None
        except (TypeError, ValueError):
            amt = None
        desc = (li.get("description") or li.get("text") or '').strip()
        if desc or amt:
            veryfi_items.append({"description": desc[:200], "amount": amt})
    # Existing itemization: child invoice_split rows on this doc's parent. The
    # 'Remainder → main line' child is NOT a subline — it feeds the main-line
    # picker instead. (User 2026-07 remainder model.)
    existing = []
    main_line_id = None
    if parent is not None:
        kids = (Transaction.query
                .filter_by(project_id=upload.project_id, parent_transaction_id=parent.id,
                           source='invoice_split')
                .order_by(Transaction.id).all())
        for k in kids:
            bl = BudgetLine.query.get(k.budget_line_id) if k.budget_line_id else None
            _lid = (str(bl.source_line_id or bl.id) if bl else None)
            if (k.note or '') == 'Remainder → main line':
                main_line_id = _lid
                continue
            existing.append({
                "id": k.id,
                "description": k.note or '',
                "amount": float(k.amount) if k.amount is not None else None,
                "budget_line_id": _lid,
                "line_label": (f"{bl.account_code} · {bl.description or bl.account_name}" if bl else ''),
            })
        # Not split but parent is coded → that's the main line.
        if main_line_id is None and not existing and parent.budget_line_id:
            _pbl = BudgetLine.query.get(parent.budget_line_id)
            if _pbl:
                main_line_id = str(_pbl.source_line_id or _pbl.id)
    return jsonify({
        "ok": True,
        "parent_txn_id": (parent.id if parent else None),
        "doc_total": total,
        "veryfi_items": veryfi_items,
        "existing": existing,
        "main_line_id": main_line_id,
        "is_itemized": bool(existing),
        "receipt_detail": _doc_receipt_detail(upload),
    })


@app.route("/docs/upload/<int:uid>/itemize", methods=["POST"])
@login_required
def docs_upload_itemize(uid):
    """Save a document's line-item split: replace the child invoice_split rows on
    its parent transaction, each coded to its own budget line, and un-code the
    parent so the Actual rollup counts the line items (not the parent total).
    Body: { rows: [{amount, budget_line_id, description}] }. (User 2026-07.)"""
    upload = DocUpload.query.get_or_404(uid)
    _require_project_role(upload.project_id, 'editor')
    pid = upload.project_id
    parent = _doc_parent_txn(uid)
    if parent is None:
        return jsonify({"error": "No transaction exists for this document yet."}), 400
    data = request.get_json(force=True) or {}
    rows = data.get("rows") or []
    main_line_raw = data.get("main_line_id")
    if not isinstance(rows, list):
        return jsonify({"error": "rows must be a list"}), 400

    from actuals import link_transaction_to_line, unlink_transaction

    def _as_int(v):
        try:
            return int(v) if v not in (None, '', 0, '0') else None
        except (TypeError, ValueError):
            return None
    mlid = _as_int(main_line_raw)
    doc_total = abs(float(parent.amount)) if parent.amount is not None else 0.0

    # Remove any previous itemization for this parent (replace-on-save).
    for k in Transaction.query.filter_by(project_id=pid, parent_transaction_id=parent.id,
                                         source='invoice_split').all():
        db.session.delete(k)
    db.session.flush()

    # Parse sublines (portions peeled off to OTHER budget lines).
    sublines = []
    for r in rows:
        try:
            amt = round(float(r.get("amount")), 2)
        except (TypeError, ValueError):
            return jsonify({"error": "each row needs a numeric amount"}), 400
        if amt == 0:
            continue
        sublines.append((amt, _as_int(r.get("budget_line_id")), (r.get("description") or '')[:300]))

    def _mk_child(amt, line_id, note):
        c = Transaction(project_id=pid, source='invoice_split', parent_transaction_id=parent.id,
                        doc_upload_id=upload.id, amount=amt, vendor=parent.vendor,
                        txn_date=parent.txn_date, is_expense=bool(getattr(parent, 'is_expense', True)),
                        note=note[:300], match_status='confirmed')
        db.session.add(c); db.session.flush()
        if line_id:
            try:
                link_transaction_to_line(c.id, line_id, user_id=current_user.id)
            except Exception as _le:
                logging.warning("[itemize] link child→line failed: %s", _le)
        return c.id

    if not sublines:
        # No split → the whole document codes to the main line (or clears).
        if mlid:
            try:
                link_transaction_to_line(parent.id, mlid, user_id=current_user.id)
            except Exception:
                pass
            db.session.commit()
            return jsonify({"ok": True, "children": 0, "main_line_amount": round(doc_total, 2),
                            "remainder": round(doc_total, 2)})
        try:
            unlink_transaction(parent.id)
        except Exception:
            parent.account_code = parent.account_code_name = parent.budget_line_id = None
        db.session.commit()
        return jsonify({"ok": True, "cleared": True, "children": 0})

    # Split present → parent becomes a container; children carry the coding.
    created = [_mk_child(a, l, n) for (a, l, n) in sublines]
    sub_total = round(sum(a for a, _, _ in sublines), 2)
    # Remainder auto-bills to the main line (QuickBooks 'rest goes here').
    remainder = round(doc_total - sub_total, 2)
    main_amt = 0.0
    if mlid and remainder > 0.01:
        created.append(_mk_child(remainder, mlid, 'Remainder → main line'))
        main_amt = remainder

    try:
        unlink_transaction(parent.id)
    except Exception:
        parent.account_code = parent.account_code_name = parent.budget_line_id = None
    db.session.commit()
    return jsonify({"ok": True, "children": len(created), "child_ids": created,
                    "sublines_total": sub_total, "main_line_amount": round(main_amt, 2),
                    "remainder": remainder, "doc_total": round(doc_total, 2),
                    "over": remainder < -0.01})


@app.route("/docs/upload/<int:uid>/meta", methods=["GET"])
@login_required
def docs_upload_meta(uid):
    """Thin metadata for one DocUpload — lets the duplicate-compare modal show
    the ORIGINAL doc (which lives outside the Review list) beside the flagged
    copy so the user can actually compare. Read-only. (User 2026-06-02.)"""
    d = DocUpload.query.get_or_404(uid)
